INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heroui-inc/heroui/heroui-react', 'community', 'heroui-inc', 'heroui', 'heroui-inc/heroui', 'heroui-react', 0, 0, 41, '2026-03-08T01:57:15.282Z', '2026-03-08T02:00:52.548Z', '677bc9af34543cfa9f111125f8cadfdbdd5d2a958d75aa01605fccf5b6946e92', '{"id":"heroui-inc/heroui/heroui-react","name":"heroui-react","description":{"en":"heroui-react is a component library providing accessible, customizable UI components for React applications. It is built on Tailwind CSS v4 and React Aria Components, making it a great choice for developers looking to create modern and fast React applications.","zh":"heroui-react 是一个基于 Tailwind CSS v4 和 React Aria Components 的现代 React UI 库，提供可访问性和自定义 UI 组件","ja":"heroui-react は、AIエージェント対応の React UI ライブラリで、Tailwind CSS v4 と React Aria Components を使用して高速な UI を構築します","ko":"heroui-react는 Tailwind CSS v4 및 React Aria Components 기반의 현대적인 React UI 라이브러리로, 접근성 및 사용자 지정 UI 컴포넌트를 제공합니다","es":"heroui-react es una biblioteca de componentes de interfaz de usuario para React, construida con Tailwind CSS v4 y React Aria Components, que ofrece componentes personalizables y accesibles","fr":"heroui-react est une bibliothèque de composants d''interface utilisateur pour React, construite avec Tailwind CSS v4 et React Aria Components, qui offre des composants personnalisables et accessibles","de":"heroui-react ist eine Benutzeroberflächenbibliothek für React, die mit Tailwind CSS v4 und React Aria Components erstellt wurde und anpassbare und zugängliche Komponenten bietet","pt":"O HeroUI-React é uma biblioteca de UI moderna e acessível para aplicações React, construída com Tailwind CSS v4 e React Aria Components","ru":"HeroUI-React - это современная и доступная библиотека UI для приложений React, построенная на Tailwind CSS v4 и React Aria Components","ar":"هرمي-رياكت هي مكتبة واجهة المستخدم الحديثة والسريعة لبرامج رياكت، مبنية على Tailwind CSS v4 و React Aria Components"},"seo":{"title":{"en":"heroui-react: Tailwind CSS v4 Integration Guide | AI Agen...","zh":"heroui-react 设置指南 - 基于 Tailwind CSS v4 的 React UI 库","ja":"heroui-react セットアップガイド - AIエージェント対応の React UI ライブラリ","ko":"heroui-react 설정 가이드 - Tailwind CSS v4 기반 React UI 라이브러리","es":"Guía de configuración de heroui-react para aplicaciones R...","fr":"Guide d''installation de heroui-react pour les application...","de":"Einrichtungsleitfaden für heroui-react in React-Anwendungen","pt":"Guia de Configuração do HeroUI-React: Biblioteca de UI Mo...","ru":"ИИ Агенты: Настройка HeroUI-React, Быстрой и Современной ...","ar":"إعداد هرمي-رياكت: مكتبة واجهة المستخدم الحديثة والسريعة"},"description":{"en":"Unlock the full potential of heroui-react, a modern React UI library built on Tailwind CSS v4 and React Aria Components. Get started with our expert guide an...","zh":"学习 heroui-react 的技术细节，包括基于 Tailwind CSS v4 和 React Aria Components 的可访问性和自定义 UI 组件","ja":"heroui-react のテクニカルガイド - AIエージェントと React を使用した高速な UI ライブラリの構築","ko":"heroui-react의 기술 세부 정보를 학습하세요. Tailwind CSS v4 및 React Aria Components 기반의 접근성 및 사용자 지정 UI 컴포넌트","es":"Aprende a utilizar heroui-react, una biblioteca de interfaz de usuario moderna y accesible para React, basada en Tailwind CSS v4 y React Aria Components","fr":"Découvrez heroui-react, une bibliothèque d''interface utilisateur moderne et accessible pour React, basée sur Tailwind CSS v4 et React Aria Components","de":"Erfahren Sie, wie Sie heroui-react, eine moderne und zugängliche Benutzeroberflächenbibliothek für React, basierend auf Tailwind CSS v4 und React Aria Compon...","pt":"Aprenda a configurar o HeroUI-React, uma biblioteca de UI moderna e acessível construída com Tailwind CSS v4 e React Aria Components","ru":"Узнайте, как настроить HeroUI-React, быструю и современную библиотеку React UI, построенную на Tailwind CSS v4 и React Aria Components","ar":"تعرف على كيفية إعداد هرمي-رياكت، مكتبة واجهة المستخدم الحديثة والسريعة التي بنيت باستخدام Tailwind CSS v4 و React Aria Components"},"definition":{"en":"heroui-react is a React UI library built on Tailwind CSS v4 and React Aria Components, providing accessible and customizable UI components for React applications.","zh":"heroui-react 是一个用于构建 React 应用的现代 UI 库，基于 Tailwind CSS v4 和 React Aria Components","ja":"heroui-react は、React アプリケーションの構築に使用される AIエージェント対応のモダン UI ライブラリです","ko":"heroui-react는 React 애플리케이션을 구축하는 데 사용되는 현대적인 UI 라이브러리입니다","es":"heroui-react es una biblioteca de componentes de interfaz de usuario para React que proporciona componentes personalizables y accesibles","fr":"heroui-react est une bibliothèque de composants d''interface utilisateur pour React qui propose des composants personnalisables et accessibles","de":"heroui-react ist eine Benutzeroberflächenbibliothek für React, die anpassbare und zugängliche Komponenten bereitstellt","pt":"O que é HeroUI-React? É uma biblioteca de UI para React que fornece componentes acessíveis e personalizáveis","ru":"Что такое HeroUI-React? Это библиотека UI для React, которая предоставляет доступные и настраиваемые компоненты","ar":"ما هي هرمي-رياكت؟ هي مكتبة واجهة المستخدم لرياكت توفر مكونات قابلة للوصول والتعديل"},"features":{"en":["Built on Tailwind CSS v4 for customizable styling","Utilizes React Aria Components for accessible UI components","Provides a modern and fast React UI library","Supports customizable UI components for React applications","Compatible with the latest React versions","Follows critical rules for v3, ignoring prior v2 knowledge"],"zh":["基于 Tailwind CSS v4 的可访问性和自定义 UI 组件","使用 React Aria Components 实现可访问性","提供现代化的 React UI 库","支持快速的 UI 构建","兼容 React 应用","提供可定制的 UI 组件"],"ja":["AIエージェント対応の React UI ライブラリ","Tailwind CSS v4 を使用した高速な UI 構築","React Aria Components を使用した可访问性","モダンな React UI ライブラリ","React アプリケーションとの互換性","カスタマイズ可能な UI コンポーネント"],"ko":["Tailwind CSS v4 기반의 접근성 및 사용자 지정 UI 컴포넌트","React Aria Components를 사용한 접근성 구현","현대적인 React UI 라이브러리","빠른 UI 구축 지원","React 애플리케이션과 호환","사용자 지정 가능한 UI 컴포넌트"],"es":["Basada en Tailwind CSS v4","Integración con React Aria Components","Componentes personalizables y accesibles","Compatibilidad con aplicaciones React modernas","Diseño moderno y rápido"],"fr":["Basée sur Tailwind CSS v4","Intégration avec React Aria Components","Composants personnalisables et accessibles","Compatibilité avec les applications React modernes","Conception moderne et rapide"],"de":["Basierend auf Tailwind CSS v4","Integration mit React Aria Components","Anpassbare und zugängliche Komponenten","Kompatibilität mit modernen React-Anwendungen","Modernes und schnelles Design"],"pt":["Construída com Tailwind CSS v4","Utiliza React Aria Components para acessibilidade","Fornece componentes UI personalizáveis","Compatível com aplicações React modernas","Documentação detalhada para facilitar a implementação"],"ru":["Построена на Tailwind CSS v4","Использует React Aria Components для доступности","Предоставляет настраиваемые компоненты UI","Совместима с современными приложениями React","Подробная документация для облегчения реализации"],"ar":["بناءت باستخدام Tailwind CSS v4","تستخدم React Aria Components للوصول","توفر مكونات واجهة المستخدم القابلة للتعديل","متوافقة مع تطبيقات رياكت الحديثة","توثيق مفصل لتسهيل التنفيذ"]},"keywords":{"en":["how to use heroui-react","heroui-react vs NextUI","heroui-react install","what is heroui-react","heroui-react setup guide","heroui-react alternative","heroui-react react aria components","heroui-react tailwind css v4","heroui-react customization","heroui-react accessibility"],"zh":["heroui-react","React UI 库","Tailwind CSS v4","React Aria Components","可访问性","自定义 UI 组件","现代 React UI 库","快速 UI 构建","React 应用"],"ja":["heroui-react","AIエージェント","React UI ライブラリ","Tailwind CSS v4","React Aria Components","可访问性","カスタマイズ可能な UI コンポーネント","モダンな React UI ライブラリ","高速な UI 構築","React アプリケーション"],"ko":["heroui-react","React UI 라이브러리","Tailwind CSS v4","React Aria Components","접근성","사용자 지정 UI 컴포넌트","현대적인 React UI 라이브러리","빠른 UI 구축","React 애플리케이션"],"es":["heroui-react","biblioteca de interfaz de usuario para React","Tailwind CSS v4","React Aria Components","componentes personalizables","accesibilidad en React","desarrollo de aplicaciones React","herramientas de desarrollo React","AI Agents para React","Herramientas de AI para desarrolladores"],"fr":["heroui-react","bibliothèque d''interface utilisateur pour React","Tailwind CSS v4","React Aria Components","composants personnalisables","accessibilité dans React","développement d''applications React","outils de développement React","Agents AI pour React","Outils d''IA pour les développeurs"],"de":["heroui-react","Benutzeroberflächenbibliothek für React","Tailwind CSS v4","React Aria Components","anpassbare Komponenten","Zugänglichkeit in React","Entwicklung von React-Anwendungen","Entwicklungstools für React","AI-Agents für React","KI-Tools für Entwickler"],"pt":["HeroUI-React","Biblioteca de UI React","Tailwind CSS v4","React Aria Components","Desenvolvimento de aplicações React","Componentes UI acessíveis","Personalização de UI"],"ru":["HeroUI-React","Библиотека UI для React","Tailwind CSS v4","React Aria Components","Разработка приложений React","Доступные компоненты UI","Настройка UI"],"ar":["هرمي-رياكت","مكتبة واجهة المستخدم رياكت","Tailwind CSS v4","React Aria Components","تطوير تطبيقات رياكت","مكونات واجهة المستخدم قابلة للوصول","تخصيص واجهة المستخدم"]}},"owner":"heroui-inc","repo":"heroui","repoPath":"heroui-inc/heroui","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.282Z","topics":[],"category":"community","skillMd":{"name":"heroui-react","description":"HeroUI v3 React component library (Tailwind CSS v4 + React Aria). Use when working with HeroUI components, installing HeroUI, customizing HeroUI themes, or accessing HeroUI component documentation. Keywords: HeroUI, Hero UI, heroui, @heroui/react, @heroui/styles.","version":"2.0.0","bodyPreview":"# HeroUI v3 React Development Guide\n\nHeroUI v3 is a component library built on **Tailwind CSS v4** and **React Aria Components**, providing accessible, customizable UI components for React applications.\n\n---\n\n## CRITICAL: v3 Only - Ignore v2 Knowledge\n\n**This guide is for HeroUI v3 ONLY.** Do NOT use any prior knowledge of HeroUI v2.\n\n### What Changed in v3\n\n| Feature       | v2 (DO NOT USE)                   | v3 (USE THIS)                               |\n| ------------- | ---------------------","body":"# HeroUI v3 React Development Guide\n\nHeroUI v3 is a component library built on **Tailwind CSS v4** and **React Aria Components**, providing accessible, customizable UI components for React applications.\n\n---\n\n## CRITICAL: v3 Only - Ignore v2 Knowledge\n\n**This guide is for HeroUI v3 ONLY.** Do NOT use any prior knowledge of HeroUI v2.\n\n### What Changed in v3\n\n| Feature       | v2 (DO NOT USE)                   | v3 (USE THIS)                               |\n| ------------- | --------------------------------- | ------------------------------------------- |\n| Provider      | `<HeroUIProvider>` required       | **No Provider needed**                      |\n| Animations    | `framer-motion` package           | CSS-based, no extra deps                    |\n| Component API | Flat props: `<Card title=\"x\">`    | Compound: `<Card><Card.Header>`             |\n| Styling       | Tailwind v3 + `@heroui/theme`     | Tailwind v4 + `@heroui/styles@beta`         |\n| Packages      | `@heroui/system`, `@heroui/theme` | `@heroui/react@beta`, `@heroui/styles@beta` |\n\n### WRONG (v2 patterns)\n\n```tsx\n// DO NOT DO THIS - v2 pattern\nimport { HeroUIProvider } from \"@heroui/react\";\nimport { motion } from \"framer-motion\";\n\n<HeroUIProvider>\n\t<Card title=\"Product\" description=\"A great product\" />\n</HeroUIProvider>;\n```\n\n### CORRECT (v3 patterns)\n\n```tsx\n// DO THIS - v3 pattern (no provider, compound components)\nimport { Card } from \"@heroui/react@beta\";\n\n<Card>\n\t<Card.Header>\n\t\t<Card.Title>Product</Card.Title>\n\t\t<Card.Description>A great product</Card.Description>\n\t</Card.Header>\n</Card>;\n```\n\n**Always fetch v3 docs before implementing.** Do not assume v2 patterns work.\n\n---\n\n## Core Principles\n\n- Semantic variants (`primary`, `secondary`, `tertiary`) over visual descriptions\n- Composition over configuration (compound components)\n- CSS variable-based theming with `oklch` color space\n- BEM naming convention for predictable styling\n\n---\n\n## Accessing Documentation & Component Information\n\n**For component details, examples, props, and implementation patterns, always fetch documentation:**\n\n### Using Scripts\n\n```bash\n# List all available components\nnode scripts/list_components.mjs\n\n# Get component documentation (MDX)\nnode scripts/get_component_docs.mjs Button\nnode scripts/get_component_docs.mjs Button Card TextField\n\n# Get component source code\nnode scripts/get_source.mjs Button\n\n# Get component CSS styles (BEM classes)\nnode scripts/get_styles.mjs Button\n\n# Get theme variables\nnode scripts/get_theme.mjs\n\n# Get non-component docs (guides, releases)\nnode scripts/get_docs.mjs /docs/react/getting-started/theming\n```\n\n### Direct MDX URLs\n\nComponent docs: `https://v3.heroui.com/docs/react/components/{component-name}.mdx`\n\nExamples:\n\n- Button: `https://v3.heroui.com/docs/react/components/button.mdx`\n- Modal: `https://v3.heroui.com/docs/react/components/modal.mdx`\n- Form: `https://v3.heroui.com/docs/react/components/form.mdx`\n\nGetting started guides: `https://v3.heroui.com/docs/react/getting-started/{topic}.mdx`\n\n**Important:** Always fetch component docs before implementing. The MDX docs include complete examples, props, anatomy, and API references.\n\n---\n\n## Installation Essentials\n\n**CRITICAL**: HeroUI v3 is currently in BETA. Always use `@beta` tag when installing packages.\n\n### Quick Install\n\n```bash\nnpm i @heroui/styles@beta @heroui/react@beta tailwind-variants\n```\n\n### Framework Setup (Next.js App Router - Recommended)\n\n1. **Install dependencies:**\n\n```bash\nnpm i @heroui/styles@beta @heroui/react@beta tailwind-variants tailwindcss @tailwindcss/postcss postcss\n```\n\n2. **Create/update `app/globals.css`:**\n\n```css\n/* Tailwind CSS v4 - Must be first */\n@import \"tailwindcss\";\n\n/* HeroUI v3 styles - Must be after Tailwind */\n@import \"@heroui/styles\";\n```\n\n3. **Import in `app/layout.tsx`:**\n\n```tsx\nimport \"./globals.css\";\n\nexport default function RootLayout({\n\tchildren,\n}: {\n\tchildren: React.ReactNode;\n}) {\n\treturn (\n\t\t<html lang=\"en\" suppressHydrationWarning>\n\t\t\t<body>\n\t\t\t\t{/* No Provider needed in HeroUI v3! */}\n\t\t\t\t{children}\n\t\t\t</body>\n\t\t</html>\n\t);\n}\n```\n\n4. **Configure PostCSS (`postcss.config.mjs`):**\n\n```js\nexport default {\n\tplugins: {\n\t\t\"@tailwindcss/postcss\": {},\n\t},\n};\n```\n\n### Critical Setup Requirements\n\n1. **Tailwind CSS v4 is MANDATORY** - HeroUI v3 will NOT work with Tailwind CSS v3\n2. **No Provider Required** - Unlike HeroUI v2, v3 components work directly without a Provider\n3. **Use Compound Components** - Components use compound structure (e.g., `Card.Header`, `Card.Content`)\n4. **Use onPress, not onClick** - For better accessibility, use `onPress` event handlers\n5. **Import Order Matters** - Always import Tailwind CSS before HeroUI styles\n\n---\n\n## Component Patterns\n\nHeroUI v3 uses **compound component patterns**. Each component has subcomponents accessed via dot notation.\n\n**Example - Card:**\n\n```tsx\n<Card>\n\t<Card.Header>\n\t\t<Card.Title>Title</Card.Title>\n\t\t<Card.Description>Description</Card.Description>\n\t</Card.Header>\n\t<Card.Content>{/* Content */}</Card.Content>\n\t<Card.Footer>{/* Actions */}</Card.Footer>\n</Card>\n```\n\n**Key Points:**\n\n- Always use compound structure - don''t flatten to props\n- Subcomponents are accessed via dot notation (e.g., `Card.Header`)\n- Each subcomponent may have its own props\n- **Fetch component docs for complete anatomy and examples**\n\n---\n\n## Semantic Variants\n\nHeroUI uses semantic naming to communicate functional intent:\n\n| Variant     | Purpose                           | Usage          |\n| ----------- | --------------------------------- | -------------- |\n| `primary`   | Main action to move forward       | 1 per context  |\n| `secondary` | Alternative actions               | Multiple       |\n| `tertiary`  | Dismissive actions (cancel, skip) | Sparingly      |\n| `danger`    | Destructive actions               | When needed    |\n| `ghost`     | Low-emphasis actions              | Minimal weight |\n| `outline`   | Secondary actions                 | Bordered style |\n\n**Don''t use raw colors** - semantic variants adapt to themes and accessibility.\n\n---\n\n## Theming\n\nHeroUI v3 uses CSS variables with `oklch` color space:\n\n```css\n:root {\n\t--accent: oklch(0.6204 0.195 253.83);\n\t--accent-foreground: var(--snow);\n\t--background: oklch(0.9702 0 0);\n\t--foreground: var(--eclipse);\n}\n```\n\n**Get current theme variables:**\n\n```bash\nnode scripts/get_theme.mjs\n```\n\n**Color naming:**\n\n- Without suffix = background (e.g., `--accent`)\n- With `-foreground` = text color (e.g., `--accent-foreground`)\n\n**Theme switching:**\n\n```html\n<html class=\"dark\" data-theme=\"dark\"></html>\n```\n\nFor detailed theming, fetch: `https://v3.heroui.com/docs/react/getting-started/theming.mdx`\n"},"lastSynced":"2026-03-08T02:00:52.548Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing accessible and customizable UI components for React applications.","zh":"非常适合需要可访问和可定制的UI组件的React应用的前端代理。","ja":"Reactアプリケーションにアクセス可能でカスタマイズ可能なUIコンポーネントを必要とするフロントエンドエージェントに最適です。","ko":"React 애플리케이션에 접근 가능하고 사용자 지정할 수 있는 UI 구성 요소를 필요로 하는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan componentes de interfaz de usuario accesibles y personalizables para aplicaciones de React.","fr":"Parfait pour les agents Frontend ayant besoin de composants d''interface utilisateur accessibles et personnalisables pour les applications React.","de":"Perfekt für Frontend-Agents, die zugängliche und anpassbare Benutzeroberflächenkomponenten für React-Anwendungen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de componentes de UI acessíveis e personalizáveis para aplicações React.","ru":"Идеально подходит для фронтенд-агентов, которым требуются доступные и настраиваемые компоненты интерфейса пользователя для приложений React.","ar":"مثالي لعمال الواجهة الأمامية الذين يحتاجون إلى مكونات واجهة المستخدم القابلة للوصول والتعديل لتطبيقات React."},"recommendation":{"en":"Empowers agents to build modern and fast React applications using Tailwind CSS v4 and React Aria Components, providing accessible and customizable UI components with seamless integration.","zh":"赋予代理构建使用Tailwind CSS v4和React Aria组件的现代和快速的React应用的能力，提供可访问和可定制的UI组件，并实现无缝集成。","ja":"Tailwind CSS v4とReact Ariaコンポーネントを使用して、モダンで高速なReactアプリケーションを構築するエージェントに力を与え、アクセス可能でカスタマイズ可能なUIコンポーネントを提供し、シームレスな統合を実現します。","ko":"Tailwind CSS v4와 React Aria 컴포넌트를 사용하여 현대적이고 빠른 React 애플리케이션을 구축할 수 있는 에이전트에게 힘을 부여하여 접근 가능하고 사용자 지정할 수 있는 UI 구성 요소를 제공하며, 무결점 통합을 제공합니다.","es":"Habilita a los agentes a crear aplicaciones React modernas y rápidas utilizando Tailwind CSS v4 y componentes de React Aria, proporcionando componentes de interfaz de usuario accesibles y personalizables con integración sin problemas.","fr":"Permet aux agents de créer des applications React modernes et rapides en utilisant Tailwind CSS v4 et les composants React Aria, fournissant des composants d''interface utilisateur accessibles et personnalisables avec une intégration sans problème.","de":"Ermöglicht es Agenten, moderne und schnelle React-Anwendungen mit Tailwind CSS v4 und React-Aria-Komponenten zu erstellen, wodurch zugängliche und anpassbare Benutzeroberflächenkomponenten mit nahtloser Integration bereitgestellt werden.","pt":"Habilita os agentes a construir aplicações React modernas e rápidas usando Tailwind CSS v4 e Componentes React Aria, fornecendo componentes de UI acessíveis e personalizáveis com integração perfeita.","ru":"Позволяет агентам создавать современные и быстрые приложения React, используя Tailwind CSS v4 и компоненты React Aria, обеспечивая доступные и настраиваемые компоненты интерфейса пользователя с бесшовной интеграцией.","ar":"تمكّن العمال من بناء تطبيقات React الحديثة والسريعة باستخدام Tailwind CSS v4 ومكونات React Aria، وتوفير مكونات واجهة المستخدم القابلة للوصول والتعديل مع التكامل السلس."},"useCases":{"en":["Building responsive and accessible hero sections","Creating customizable UI components for React applications","Integrating with Tailwind CSS v4 for styling"],"zh":["构建响应式和可访问的英雄部分","为React应用创建可定制的UI组件","与Tailwind CSS v4集成进行样式设置"],"ja":["レスポンシブでアクセス可能なヒーローセクションを構築する","Reactアプリケーションのカスタマイズ可能なUIコンポーネントを作成する","Tailwind CSS v4との統合によるスタイリング"],"ko":["반응형 및 접근 가능한 영웅 섹션 구축","React 애플리케이션을 위한 사용자 지정 가능한 UI 구성 요소 생성","스타일 지정에 대한 Tailwind CSS v4와의 통합"],"es":["Crear secciones de héroe responsivas y accesibles","Crear componentes de interfaz de usuario personalizables para aplicaciones de React","Integrar con Tailwind CSS v4 para el estilo"],"fr":["Créer des sections de héros réactives et accessibles","Créer des composants d''interface utilisateur personnalisables pour les applications React","Intégrer avec Tailwind CSS v4 pour la mise en page"],"de":["Erstellen von responsiven und zugänglichen Hero-Abschnitten","Erstellen von anpassbaren Benutzeroberflächenkomponenten für React-Anwendungen","Integrieren mit Tailwind CSS v4 für die Gestaltung"],"pt":["Construir seções de heróis responsivas e acessíveis","Criar componentes de UI personalizáveis para aplicações React","Integrar com Tailwind CSS v4 para estilização"],"ru":["Создание отзывчивых и доступных секций героев","Создание настраиваемых компонентов интерфейса пользователя для приложений React","Интеграция с Tailwind CSS v4 для стилизации"],"ar":["بناء أقسام البطل الاستجابة والقابلة للوصول","إنشاء مكونات واجهة المستخدم القابلة للتعديل لتطبيقات React","التكامل مع Tailwind CSS v4 لأغراض التخصيص"]},"limitations":{"en":["Requires React and Tailwind CSS v4 setup","Only compatible with HeroUI v3","Prior knowledge of HeroUI v2 is not applicable"],"zh":["需要React和Tailwind CSS v4设置","仅与HeroUI v3兼容","HeroUI v2的先前知识不适用"],"ja":["ReactとTailwind CSS v4のセットアップが必要","HeroUI v3のみと互換性がある","HeroUI v2の事前の知識は適用されない"],"ko":["React 및 Tailwind CSS v4 설정이 필요함","HeroUI v3만과 호환됨","HeroUI v2의 이전 지식은 적용되지 않음"],"es":["Requiere configuración de React y Tailwind CSS v4","Solo compatible con HeroUI v3","Conocimientos previos de HeroUI v2 no son aplicables"],"fr":["Nécessite une configuration de React et de Tailwind CSS v4","Compatible uniquement avec HeroUI v3","Les connaissances précédentes de HeroUI v2 ne sont pas applicables"],"de":["Benötigt React- und Tailwind-CSS-v4-Setup","Nur kompatibel mit HeroUI v3","Vorheriges Wissen über HeroUI v2 ist nicht anwendbar"],"pt":["Requer configuração do React e Tailwind CSS v4","Somente compatível com HeroUI v3","Conhecimento prévio do HeroUI v2 não se aplica"],"ru":["Требуется настройка React и Tailwind CSS v4","Совместимо только с HeroUI v3","Предварительные знания HeroUI v2 не применимы"],"ar":["يتطلب إعداد React و Tailwind CSS v4","متوافق فقط مع HeroUI v3","المعرفة السابقة لبرنامج HeroUI v2 لا تنطبق"]},"version":4},"contentHash":"677bc9af34543cfa9f111125f8cadfdbdd5d2a958d75aa01605fccf5b6946e92","qualityScore":41}');
