INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('heroui-inc/heroui/heroui-react', 'heroui-react', 'heroui-inc', 'heroui', 'community', 'heroui-react heroui-inc heroui community heroui-react is a component library providing accessible, customizable UI components for React applications. It is built on Tailwind CSS v4 and React Aria Components, making it a great choice for developers looking to create modern and fast React applications. heroui-react 是一个基于 Tailwind CSS v4 和 React Aria Components 的现代 React UI 库，提供可访问性和自定义 UI 组件 heroui-react は、AIエージェント対応の React UI ライブラリで、Tailwind CSS v4 と React Aria Components を使用して高速な UI を構築します heroui-react는 Tailwind CSS v4 및 React Aria Components 기반의 현대적인 React UI 라이브러리로, 접근성 및 사용자 지정 UI 컴포넌트를 제공합니다 heroui-react es una biblioteca de componentes de interfaz de usuario para React, construida con Tailwind CSS v4 y React Aria Components, que ofrece componentes personalizables y accesibles heroui-react est une bibliothèque de composants d''interface utilisateur pour React, construite avec Tailwind CSS v4 et React Aria Components, qui offre des composants personnalisables et accessibles heroui-react ist eine Benutzeroberflächenbibliothek für React, die mit Tailwind CSS v4 und React Aria Components erstellt wurde und anpassbare und zugängliche Komponenten bietet O HeroUI-React é uma biblioteca de UI moderna e acessível para aplicações React, construída com Tailwind CSS v4 e React Aria Components HeroUI-React - это современная и доступная библиотека UI для приложений React, построенная на Tailwind CSS v4 и React Aria Components هرمي-رياكت هي مكتبة واجهة المستخدم الحديثة والسريعة لبرامج رياكت، مبنية على Tailwind CSS v4 و React Aria Components how to use heroui-react heroui-react vs NextUI heroui-react install what is heroui-react heroui-react setup guide heroui-react alternative heroui-react react aria components heroui-react tailwind css v4 heroui-react customization heroui-react accessibility heroui-react React UI 库 Tailwind CSS v4 React Aria Components 可访问性 自定义 UI 组件 现代 React UI 库 快速 UI 构建 React 应用 Built on Tailwind CSS v4 for customizable styling Utilizes React Aria Components for accessible UI components Provides a modern and fast React UI library Supports customizable UI components for React applications Compatible with the latest React versions Follows critical rules for v3, ignoring prior v2 knowledge heroui-react is a React UI library built on Tailwind CSS v4 and React Aria Components, providing accessible and customizable UI components for React applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rudrankriyam/app-store-connect-cli-skills/asc-id-resolver', 'community', 'rudrankriyam', 'app-store-connect-cli-skills', 'rudrankriyam/app-store-connect-cli-skills', 'asc-id-resolver', 0, 0, 41, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:56.723Z', 'e5698ffc3bd9eb00df2ede55cdab209d3e2239a57643d82d854403163f348600', '{"id":"rudrankriyam/app-store-connect-cli-skills/asc-id-resolver","name":"asc-id-resolver","description":{"en":"The asc-id-resolver skill automates app store deployments and related tasks using the asc cli, benefiting developers who need to manage app IDs, build IDs, and version IDs. It provides a efficient way to map names to IDs.","zh":"asc-id-resolver是一个技能，用于映射名称到ID，自动化App Store部署和管理，使用ASC CLI","ja":"asc-id-resolverは、名称をIDにマッピングすることで、App Storeのデプロイと管理を自動化するスキルです","ko":"asc-id-resolver는 이름을 ID에 매핑하여 앱 스토어 배포와 관리를 자동화하는 기술입니다","es":"El asc-id-resolver es una habilidad que permite a los desarrolladores automatizar el proceso de implementación de la tienda de aplicaciones utilizando la CLI de asc.","fr":"L''asc-id-resolver est une compétence qui permet aux développeurs d''automatiser le processus de déploiement de l''app store en utilisant la CLI d''asc.","de":"Der asc-id-resolver ist eine Fähigkeit, die es Entwicklern ermöglicht, den Prozess der App-Store-Bereitstellung mithilfe der asc-CLI zu automatisieren.","pt":"O asc-id-resolver é uma habilidade que permite mapear nomes para IDs necessários por outros comandos, incluindo IDs de aplicativos, compilações e versões","ru":"ИИ Агент asc-id-resolver - это навык, который позволяет сопоставить имена с идентификаторами, необходимыми для других команд, включая идентификаторы приложений, сборок и версий","ar":"أداة asc-id-resolver هي ميزة تمكن من ربط الأسماء بمعرفات الحاجة إليها من قبل أوامر أخرى، بما في ذلك معرفات التطبيقات والنسخ والطرحات"},"seo":{"title":{"en":"asc-id-resolver: Automate App Store Deployments | AI Agen...","zh":"asc-id-resolver_SETUP GUIDE：使用ASC CLI映射名称到ID","ja":"asc-id-resolver_BEST PRACTICES：AIエージェントによるASC CLIの活用","ko":"asc-id-resolver_SETUP TUTORIAL：ASC CLI를 사용한 이름-ID 매핑","es":"Guía de configuración de asc-id-resolver para desarrollad...","fr":"Configurer asc-id-resolver : Guide pratique pour les déve...","de":"Einrichtung von asc-id-resolver: Entwicklerleitfaden","pt":"Guia de Configuração do asc-id-resolver para Desenvolvedores","ru":"Настройка ИИ Агента asc-id-resolver: Лучшие Практики","ar":"دليل إعداد أداة asc-id-resolver للبرمجة"},"description":{"en":"Discover how to streamline app store deployments with asc-id-resolver. Learn to map names to IDs and automate tasks using the asc cli. Get started now!","zh":"了解asc-id-resolver的功能和特点，使用ASC CLI自动化App Store部署和管理","ja":"asc-id-resolverを使用してASC CLIの機能を最大限に活用する方法を学ぶ","ko":"asc-id-resolver의 기능과 특징을 알아보고 ASC CLI를 사용하여 앱 스토어 배포를 자동화하십시오","es":"Automatice la implementación de la tienda de aplicaciones con asc-id-resolver y CLI. Obtenga IDs de aplicaciones, versiones y compilaciones con facilidad.","fr":"Automatisez le déploiement de l''app store avec asc-id-resolver et la CLI. Récupérez les IDs d''app, de version et de build avec facilité.","de":"Automatisieren Sie die App-Store-Bereitstellung mit asc-id-resolver und CLI. Erhalten Sie App-IDs, Versionen und Build-IDs einfach.","pt":"Aprenda a usar o asc-id-resolver para automatizar a implantação da loja de aplicativos e gerenciar IDs de aplicativos, compilações e versões","ru":"Используйте ИИ Агент asc-id-resolver для автоматизации развертывания приложений и управления идентификаторами приложений, сборок и версий","ar":"تعلم كيفية استخدام أداة asc-id-resolver لتحسين نشر التطبيقات وإدارة معرفات التطبيقات والنسخ والطرحات"},"definition":{"en":"asc-id-resolver is a skill that enables automation of app store deployments and related tasks, using the asc cli to map names to IDs and perform tasks such as fetching app IDs and setting defaults.","zh":"asc-id-resolver是一种使用ASC CLI自动化App Store部署和管理的技能","ja":"asc-id-resolverは、ASC CLIを使用してApp Storeのデプロイと管理を自動化するAIエージェントの一種です","ko":"asc-id-resolver는 ASC CLI를 사용하여 앱 스토어 배포와 관리를 자동화하는 기술の一種입니다","es":"El asc-id-resolver es una herramienta de automatización que asigna nombres a IDs necesarios para otros comandos.","fr":"L''asc-id-resolver est un outil d''automatisation qui mappe les noms aux IDs nécessaires pour d''autres commandes.","de":"Der asc-id-resolver ist ein Automatisierungstool, das Namen zu IDs zuweist, die für andere Befehle benötigt werden.","pt":"O que é asc-id-resolver? É uma habilidade que automatiza a implantação da loja de aplicativos e gerencia IDs","ru":"Что такое ИИ Агент asc-id-resolver? Это навык, который автоматизирует развертывание приложений и управляет идентификаторами","ar":"ما هي أداة asc-id-resolver؟ هي ميزة تحسن نشر التطبيقات وإدارة المعرفات"},"features":{"en":["Maps names to IDs using `asc apps list` commands","Fetches app IDs by bundle ID or name using `asc apps list --bundle-id` or `asc apps list --name`","Retrieves the latest build ID using `asc builds latest` command","Lists recent builds using `asc builds list` command with sorting and limiting options","Sets default app ID using `ASC_APP_ID` environment variable","Supports pagination for fetching all app data using `asc apps --paginate`"],"zh":["使用ASC CLI映射名称到ID","自动化App Store部署和管理","支持使用bundle ID或名称查找App ID","支持使用ASC_APP_ID环境变量设置默认App ID","支持查找最新的构建版本和最近的构建列表"],"ja":["ASC CLIを使用して名称をIDにマッピングする","App Storeのデプロイと管理を自動化する","バンドルIDまたは名称を使用してApp IDを検索する","ASC_APP_ID環境変数を使用してデフォルトのApp IDを設定する","最新のビルドバージョンと最近のビルド一覧を検索する"],"ko":["ASC CLI를 사용하여 이름을 ID에 매핑하는 기능","앱 스토어 배포와 관리를 자동화하는 기능","번들 ID 또는 이름을 사용하여 앱 ID를 검색하는 기능","ASC_APP_ID 환경 변수를 사용하여 기본 앱 ID를 설정하는 기능","최신 빌드 버전과 최근 빌드 목록을 검색하는 기능"],"es":["Asignación de nombres a IDs de aplicaciones","Recuperación de IDs de versiones y compilaciones","Soporte para la paginación de resultados","Configuración de IDs de aplicaciones por defecto","Uso de la CLI de asc para la automatización"],"fr":["Mappage des noms aux IDs d''app","Récupération des IDs de version et de build","Prise en charge de la pagination des résultats","Configuration des IDs d''app par défaut","Utilisation de la CLI d''asc pour l''automatisation"],"de":["Zuweisung von Namen zu App-IDs","Abruf von Version- und Build-IDs","Unterstützung für die Paginierung von Ergebnissen","Konfiguration von App-IDs standardmäßig","Verwendung der asc-CLI für die Automatisierung"],"pt":["Mapeamento de nomes para IDs de aplicativos","Gerenciamento de IDs de compilações e versões","Suporte à CLI para automação","Integração com o ASC para gerenciamento de aplicativos","Suporte à paginação para fetch de dados"],"ru":["Сопоставление имен с идентификаторами приложений","Управление идентификаторами сборок и версий","Поддержка CLI для автоматизации","Интеграция с ASC для управления приложениями","Поддержка постраничной загрузки данных"],"ar":["ربط الأسماء بمعرفات التطبيقات","إدارة معرفات النسخ والطرحات","دعم واجهة السطر الأوامر للتحكم الآلي","التكامل مع ASC لإدارة التطبيقات","دعم التحميل الصفحي للبيانات"]},"keywords":{"en":["how to use asc-id-resolver","asc-id-resolver setup guide","asc cli tutorial","app store deployment automation","asc-id-resolver vs fastlane","asc-id-resolver install","what is asc-id-resolver","asc-id-resolver alternative","automate app store deployments"],"zh":["asc-id-resolver","ASC CLI","App Store部署","自动化管理","名称-ID映射","bundle ID","ASC_APP_ID环境变量"],"ja":["asc-id-resolver","ASC CLI","App Storeデプロイ","自動化管理","名称-IDマッピング","バンドルID","ASC_APP_ID環境変数","AIエージェント"],"ko":["asc-id-resolver","ASC CLI","앱 스토어 배포","자동화 관리","이름-ID 매핑","번들 ID","ASC_APP_ID 환경 변수","AI 툴"],"es":["asc-id-resolver","automatización de la tienda de aplicaciones","CLI de asc","IDs de aplicaciones","IDs de versiones","IDs de compilaciones","desarrollo de aplicaciones móviles","herramientas de desarrollo"],"fr":["asc-id-resolver","automatisation de l''app store","CLI d''asc","IDs d''app","IDs de version","IDs de build","développement d''applications mobiles","outils de développement"],"de":["asc-id-resolver","Automatisierung des App-Stores","asc-CLI","App-IDs","Version-IDs","Build-IDs","Mobile-App-Entwicklung","Entwicklungstools"],"pt":["asc-id-resolver","automatização de loja de aplicativos","gerenciamento de IDs","CLI","ASC","desenvolvimento de aplicativos","implantação de aplicativos"],"ru":["ИИ Агент asc-id-resolver","автоматизация развертывания приложений","управление идентификаторами","CLI","ASC","разработка приложений","развертывание приложений"],"ar":["أداة asc-id-resolver","تحسين نشر التطبيقات","إدارة المعرفات","واجهة السطر الأوامر","ASC","برمجة التطبيقات","نشر التطبيقات"]}},"owner":"rudrankriyam","repo":"app-store-connect-cli-skills","repoPath":"rudrankriyam/app-store-connect-cli-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.285Z","topics":[],"category":"community","skillMd":{"name":"asc-id-resolver","description":"Resolve App Store Connect IDs (apps, builds, versions, groups, testers) from human-friendly names using asc. Use when commands require IDs.","bodyPreview":"# asc id resolver\n\nUse this skill to map names to IDs needed by other commands.\n\n## App ID\n- By bundle ID or name:\n  - `asc apps list --bundle-id \"com.example.app\"`\n  - `asc apps list --name \"My App\"`\n- Fetch everything:\n  - `asc apps --paginate`\n- Set default:\n  - `ASC_APP_ID=...`\n\n## Build ID\n- Latest build:\n  - `asc builds latest --app \"APP_ID\" --version \"1.2.3\" --platform IOS`\n- Recent builds:\n  - `asc builds list --app \"APP_ID\" --sort -uploadedDate --limit 5`\n\n## Version ID\n- `asc versions","body":"# asc id resolver\n\nUse this skill to map names to IDs needed by other commands.\n\n## App ID\n- By bundle ID or name:\n  - `asc apps list --bundle-id \"com.example.app\"`\n  - `asc apps list --name \"My App\"`\n- Fetch everything:\n  - `asc apps --paginate`\n- Set default:\n  - `ASC_APP_ID=...`\n\n## Build ID\n- Latest build:\n  - `asc builds latest --app \"APP_ID\" --version \"1.2.3\" --platform IOS`\n- Recent builds:\n  - `asc builds list --app \"APP_ID\" --sort -uploadedDate --limit 5`\n\n## Version ID\n- `asc versions list --app \"APP_ID\" --paginate`\n\n## TestFlight IDs\n- Groups:\n  - `asc beta-groups list --app \"APP_ID\" --paginate`\n- Testers:\n  - `asc beta-testers list --app \"APP_ID\" --paginate`\n\n## Pre-release version IDs\n- `asc pre-release-versions list --app \"APP_ID\" --platform IOS --paginate`\n\n## Review submission IDs\n- `asc review submissions-list --app \"APP_ID\" --paginate`\n\n## Output tips\n- JSON is default; use `--pretty` for debug.\n- For human viewing, use `--output table` or `--output markdown`.\n\n## Guardrails\n- Prefer `--paginate` on list commands to avoid missing IDs.\n- Use `--sort` where available to make results deterministic.\n"},"lastSynced":"2026-03-08T02:00:56.723Z","agentAnalysis":{"suitability":{"en":"Perfect for App Store Automation Agents needing efficient ID mapping and asc cli integration.","zh":"非常适合需要高效ID映射和asc cli集成的App Store自动化代理。","ja":"App Storeの自動化エージェントが効率的なIDマッピングとasc cli統合を必要とする場合に最適です。","ko":"효율적인 ID 매핑 및 asc cli 통합이 필요한 App Store 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización de App Store que necesitan un mapeo de ID eficiente y una integración con asc cli.","fr":"Parfait pour les Agents d''Automatisation de l''App Store nécessitant un mappage d''ID efficace et une intégration avec asc cli.","de":"Perfekt für App Store-Automatisierungsagenten, die eine effiziente ID-Zuordnung und eine asc cli-Integration benötigen.","pt":"Perfeito para Agentes de Automação da App Store que precisam de mapeamento de ID eficiente e integração do asc cli.","ru":"Идеально подходит для агентов автоматизации App Store, которым требуется эффективное сопоставление идентификаторов и интеграция с asc cli.","ar":"مثالي لعمليات.Automation Agents في App Store التي تحتاج إلى映ية هوية فعالة وتكامل asc cli."},"recommendation":{"en":"Empowers agents to automate app store deployments using the asc cli, mapping names to IDs for app IDs, build IDs, and version IDs, and leveraging commands like asc apps list and asc builds latest for seamless integration.","zh":"赋予代理自动化应用商店部署的能力，使用asc cli，将名称映射到应用ID、构建ID和版本ID，并利用诸如asc apps list和asc builds latest的命令实现无缝集成。","ja":"エージェントにアプリストアのデプロイを自動化する能力を与え、asc cliを使用して名前をアプリID、ビルドID、バージョンIDにマッピングし、asc apps listやasc builds latestなどのコマンドを利用してシームレスな統合を実現します。","ko":"에이전트가 앱 스토어 배포를 자동화 할 수 있는 기능을 제공하여 asc cli를 사용하여 이름을 앱 ID, 빌드 ID 및 버전 ID에 매핑하고 asc apps list 및 asc builds latest와 같은 명령을 사용하여 무缝한 통합을 구현합니다.","es":"Habilita a los agentes a automatizar implementaciones de App Store utilizando asc cli, asignando nombres a IDs para IDs de aplicaciones, IDs de compilación y IDs de versión, y aprovechando comandos como asc apps list y asc builds latest para una integración sin problemas.","fr":"Permet aux agents d''automatiser les déploiements de l''App Store en utilisant asc cli, en mappant les noms aux IDs pour les IDs d''applications, les IDs de build et les IDs de version, et en exploitant des commandes comme asc apps list et asc builds latest pour une intégration transparente.","de":"Ermächtigt Agenten, App Store-Deployments mithilfe von asc cli zu automatisieren, indem sie Namen auf IDs für App-IDs, Build-IDs und Version-IDs zuordnen und Befehle wie asc apps list und asc builds latest für eine nahtlose Integration nutzen.","pt":"Habilita os agentes a automatizar implantações de loja de aplicativos usando o asc cli, mapeando nomes para IDs para IDs de aplicativos, IDs de compilação e IDs de versão, e aproveitando comandos como asc apps list e asc builds latest para integração transparente.","ru":"Наделяет агентов возможностью автоматизировать развертывания в магазине приложений с помощью asc cli, сопоставляя имена с идентификаторами для идентификаторов приложений, идентификаторов сборок и идентификаторов версий, и использует команды, такие как asc apps list и asc builds latest, для беспрепятственной интеграции.","ar":"تمكّن الوكلاء من توفير تلقائي لتحديثات متجر التطبيقات باستخدام asc cli، و映ية الأسماء إلى المعرفات الخاصة بمعرفات التطبيقات، ومعرفات البناء، ومعرفات الإصدار، وتوفير أوامر مثل asc apps list و asc builds latest للتكامل السلس."},"useCases":{"en":["Automating app ID retrieval by bundle ID or name","Fetching latest build IDs for specific app versions and platforms","Resolving version IDs for app updates and releases"],"zh":["通过包ID或名称自动检索应用ID","为特定应用版本和平台获取最新的构建ID","解析应用更新和发布的版本ID"],"ja":["バンドルIDまたは名前によってアプリIDを自動的に取得する","特定のアプリバージョンとプラットフォームの最新のビルドIDを取得する","アプリの更新とリリースのバージョンIDを解決する"],"ko":["번들 ID 또는 이름으로 앱 ID를 자동으로 검색합니다.","특정 애플리케이션 버전 및 플랫폼에 대한 최신 빌드 ID를 가져옵니다.","애플리케이션 업데이트와 릴리스를 위한 버전 ID를 해결합니다."],"es":["Automatizar la recuperación de ID de aplicaciones por ID de paquete o nombre","Recuperar los ID de compilación más recientes para versiones y plataformas de aplicaciones específicas","Resolver ID de versión para actualizaciones y lanzamientos de aplicaciones"],"fr":["Automatiser la récupération de l''ID d''application par ID de bundle ou nom","Récupérer les ID de build les plus récents pour des versions et des plates-formes d''applications spécifiques","Résoudre les ID de version pour les mises à jour et les versions d''applications"],"de":["Automatisieren der App-ID-Abruf durch Bundle-ID oder Name","Abrufen der neuesten Build-IDs für bestimmte App-Versionen und -Plattformen","Auflösen von Version-IDs für App-Updates und -Veröffentlichungen"],"pt":["Automatizar a recuperação de IDs de aplicativos por ID do pacote ou nome","Buscar os IDs de compilação mais recentes para versões e plataformas de aplicativos específicos","Resolver IDs de versão para atualizações e lançamentos de aplicativos"],"ru":["Автоматизировать получение идентификаторов приложений по идентификатору пакета или имени","Получать самые свежие идентификаторы сборок для определенных версий и платформ приложений","Определить идентификаторы версий для обновлений и выпусков приложений"],"ar":["توفير تلقائي لاسترجاع معرفات التطبيقات بواسطة معرف الحزمة أو الاسم","استرجاع أخر معرفات البناء للنسخ والمنصات المحددة للتطبيقات","تحديد معرفات الإصدار للتحديثات والإصدارات الجديدة للتطبيقات"]},"limitations":{"en":["Requires asc cli installation and configuration","Limited to app store automation tasks"],"zh":["需要安装和配置asc cli","仅限于应用商店自动化任务"],"ja":["asc cliのインストールと設定が必要","アプリストアの自動化タスクのみに限定される"],"ko":["asc cli 설치 및 구성이 필요합니다.","앱 스토어 자동화 작업에만 국한됩니다."],"es":["Requiere la instalación y configuración de asc cli","Limitado a tareas de automatización de App Store"],"fr":["Nécessite l''installation et la configuration de asc cli","Limité aux tâches d''automatisation de l''App Store"],"de":["Erfordert die Installation und Konfiguration von asc cli","Begrenzt auf App Store-Automatisierungsaufgaben"],"pt":["Requer instalação e configuração do asc cli","Limitado a tarefas de automação da loja de aplicativos"],"ru":["Требует установки и настройки asc cli","Ограничен задачами автоматизации магазина приложений"],"ar":["يتطلب تثبيت وتكوين asc cli","محدود بمهام تلقائية لمتجر التطبيقات"]},"version":4},"contentHash":"e5698ffc3bd9eb00df2ede55cdab209d3e2239a57643d82d854403163f348600","qualityScore":41}');
