INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rudrankriyam/app-store-connect-cli-skills/asc-id-resolver', 'asc-id-resolver', 'rudrankriyam', 'app-store-connect-cli-skills', 'community', 'asc-id-resolver rudrankriyam app-store-connect-cli-skills community The asc-id-resolver skill automates app store deployments and related tasks using the asc cli, benefiting developers who need to manage app IDs, build IDs, and version IDs. It provides a efficient way to map names to IDs. asc-id-resolver是一个技能，用于映射名称到ID，自动化App Store部署和管理，使用ASC CLI asc-id-resolverは、名称をIDにマッピングすることで、App Storeのデプロイと管理を自動化するスキルです asc-id-resolver는 이름을 ID에 매핑하여 앱 스토어 배포와 관리를 자동화하는 기술입니다 El asc-id-resolver es una habilidad que permite a los desarrolladores automatizar el proceso de implementación de la tienda de aplicaciones utilizando la CLI de asc. L''asc-id-resolver est une compétence qui permet aux développeurs d''automatiser le processus de déploiement de l''app store en utilisant la CLI d''asc. Der asc-id-resolver ist eine Fähigkeit, die es Entwicklern ermöglicht, den Prozess der App-Store-Bereitstellung mithilfe der asc-CLI zu automatisieren. O asc-id-resolver é uma habilidade que permite mapear nomes para IDs necessários por outros comandos, incluindo IDs de aplicativos, compilações e versões ИИ Агент asc-id-resolver - это навык, который позволяет сопоставить имена с идентификаторами, необходимыми для других команд, включая идентификаторы приложений, сборок и версий أداة asc-id-resolver هي ميزة تمكن من ربط الأسماء بمعرفات الحاجة إليها من قبل أوامر أخرى، بما في ذلك معرفات التطبيقات والنسخ والطرحات how to use asc-id-resolver asc-id-resolver setup guide asc cli tutorial app store deployment automation asc-id-resolver vs fastlane asc-id-resolver install what is asc-id-resolver asc-id-resolver alternative automate app store deployments asc-id-resolver ASC CLI App Store部署 自动化管理 名称-ID映射 bundle ID ASC_APP_ID环境变量 Maps names to IDs using `asc apps list` commands Fetches app IDs by bundle ID or name using `asc apps list --bundle-id` or `asc apps list --name` Retrieves the latest build ID using `asc builds latest` command Lists recent builds using `asc builds list` command with sorting and limiting options Sets default app ID using `ASC_APP_ID` environment variable Supports pagination for fetching all app data using `asc apps --paginate` asc-id-resolver is a skill that enables automation of app store deployments and related tasks, using the asc cli to map names to IDs and perform tasks such as fetching app IDs and setting defaults.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pCruvinel/antig/fal-platform', 'community', 'pCruvinel', 'antig', 'pCruvinel/antig', 'fal-platform', 0, 0, 41, '2026-03-08T01:57:15.287Z', '2026-03-08T02:01:00.255Z', 'f595ac3e56ed2c2281e3db5d9dff2255c1f1b1e7458f098da1e9716e096a5a78', '{"id":"pCruvinel/antig/fal-platform","name":"fal-platform","description":{"en":"The fal-platform skill provides guidance and patterns for working with platform APIs, benefiting developers who need to manage models, track usage, and set prices. It offers a comprehensive solution for AI agent integration.","zh":"Fal Platform 提供模型管理、价格跟踪和使用情况统计的平台 API","ja":"Fal Platform はモデル管理、価格設定、使用状況の追跡を実現するプラットフォーム API を提供します","ko":"Fal Platform은 모델 관리, 가격 책정, 사용 상황 추적을 위한 플랫폼 API를 제공합니다","es":"Fal Platform es una plataforma de APIs para la gestión de modelos de AI, precios y seguimiento de uso. Ofrece patrones y orientación para el desarrollo","fr":"Fal Platform est une plateforme d''API pour la gestion de modèles de l''IA, de prix et de suivi de l''utilisation. Elle propose des modèles et des conseils pour le développement","de":"Fal Platform ist eine Plattform von APIs für die Modellverwaltung, Preise und Nutzungsverfolgung. Bietet Muster und Anleitung für die Entwicklung","pt":"O Fal Platform fornece APIs de plataforma para gerenciamento de modelos, preços e rastreamento de uso. Aprenda a usar essas APIs para seus projetos de AI","ru":"Fal Platform предоставляет платформенные API для управления моделями, ценами и отслеживания использования. Узнайте, как использовать эти API для своих проектов ИИ","ar":"تقدم منصة Fal واجهات برمجة التطبيقات الخاصة بالمنصة لإدارة النماذج والأسعار وتتبع الاستخدام. تعلم كيفية استخدام هذه الواجهات ل مشاريع الذكاء الاصطناعي"},"seo":{"title":{"en":"fal-platform: Platform API Management Setup Guide | AI Ag...","zh":"Fal Platform Setup Guide - AIエージェント模型管理","ja"