INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('doccker/cc-use-exp/java-dev', 'java-dev', 'doccker', 'cc-use-exp', 'community', 'java-dev doccker cc-use-exp community The java-dev skill provides a set of tools and guidelines for Java development, including Maven and Gradle setup. It benefits Java developers by streamlining their workflow. 本指南提供了 Java 开发规范、Maven 和 Gradle 工具链的最佳实践 このガイドでは、Java 開発のベストプラクティス、Maven と Gradle のツールチェーンについて説明します 본 가이드는 자바 개발 가이드, 메이븐 및 그레이들 도구 체인에 대한 정보를 제공합니다 El skill Java Dev proporciona una guía para desarrollar aplicaciones Java de forma efectiva, utilizando herramientas como Maven y Gradle. Le skill Java Dev offre un guide pour développer des applications Java de manière efficace, en utilisant des outils tels que Maven et Gradle. Das Skill Java Dev bietet eine Anleitung zur Entwicklung von Java-Anwendungen auf effektive Weise, unter Verwendung von Tools wie Maven und Gradle. O Java-dev é uma ferramenta para desenvolvedores que fornece um conjunto de melhores práticas e dicas para melhorar a produtividade e a qualidade do código Java-dev - это инструмент для разработчиков, который предоставляет набор лучших практик и советов для повышения производительности и качества кода Java-dev هو أداة لمراقبي التطوير توفر مجموعة من أفضل الممارسات والنصائح لتحسين الإنتاجية وجودة الكود how to use java-dev java-dev setup guide java-dev vs Maven java-dev alternative to Gradle what is java-dev java-dev install java-dev best practices java-dev for AI agents java-dev and Google Java Style Guide Java 开发规范 Maven 工具链 Gradle 工具链 Java 开发最佳实践 AI 工具 Java 项目优化 Compiles Java code using Maven''s `mvn clean compile` command Runs tests using Gradle''s `./gradlew test` command Verifies projects using Maven''s `mvn verify` command Follows naming conventions for packages, classes, and methods Supports domain-reversed package names, such as `com.example.project` java-dev is a Java development skill that provides a set of tools and guidelines for building and managing Java projects, following standards like Google Java Style Guide and Alibaba Java Development Manual.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SWUSTcyt/langchain-travel-agent/feature', 'community', 'SWUSTcyt', 'langchain-travel-agent', 'SWUSTcyt/langchain-travel-agent', 'feature', 0, 0, 41, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:28.958Z', '7ace609cea714fc7f8bc8d547bbe11038731171fb6ef903b91ab98acc9870ba5', '{"id":"SWUSTcyt/langchain-travel-agent/feature","name":"feature","description":{"en":"The feature skill enables developers to build a tourism planning agent demo using LangChain 1.0, Qwen, and MCP. It supports parallel calls to Gaode maps tools and middleware-level city constraints","zh":"Feature 旅游规划 Agent Demo 是一个基于 LangChain 1.0、阿里通义 Qwen 和 MCP(amap-maps) 的旅游规划工具，支持并行调用高德地图相关工具","ja":"Feature AIエージェントによる旅行計画デモは、LangChain 1.0、阿里通義 Qwen、MCP(amap-maps) を使用した旅行計画ツールで、高德地図関連ツールの並列呼び出しをサポート","ko":"Feature 여행 계획 AI 에이전트 데모는 LangChain 1.0, 阿里通義 Qwen, MCP(amap-maps) 를 사용하여 구축된 여행 계획 도구로, 고도地圖 관련 툴의 병렬 호출을 지원","es":"El agente de inteligencia artificial ''feature'' utiliza LangChain 1.0, MCP y Gradio para planificar viajes de manera eficiente, con capacidades de búsqueda de POI y planificación de rutas","fr":"L''agent d''intelligence artificielle ''feature'' utilise LangChain 1.0, MCP et Gradio pour planifier des voyages de manière efficace, avec des capacités de recherche de POI et de planification de routes","de":"Der KI-Agent ''feature'' nutzt LangChain 1.0, MCP und Gradio für effiziente Reiseplanung, mit Fähigkeiten zur POI-Suche und Routenplanung","pt":"O feature é uma demonstração de agente de planejamento de viagens baseado em LangChain 1.0, MCP e Gradio","ru":"Функция - это демонстрация агента планирования путешествий на основе LangChain 1.0, MCP и Gradio для ИИ Агентов","ar":"الميزة هي-demo لمخطط رحلات dựa على LangChain 1.0 و MCP و Gradio لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Feature: LangChain 1.0 Tour Planning Agent Demo Set