INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SWUSTcyt/langchain-travel-agent/feature', 'feature', 'SWUSTcyt', 'langchain-travel-agent', 'community', 'feature SWUSTcyt langchain-travel-agent community The feature skill enables developers to build a tourism planning agent demo using LangChain 1.0, Qwen, and MCP. It supports parallel calls to Gaode maps tools and middleware-level city constraints Feature 旅游规划 Agent Demo 是一个基于 LangChain 1.0、阿里通义 Qwen 和 MCP(amap-maps) 的旅游规划工具，支持并行调用高德地图相关工具 Feature AIエージェントによる旅行計画デモは、LangChain 1.0、阿里通義 Qwen、MCP(amap-maps) を使用した旅行計画ツールで、高德地図関連ツールの並列呼び出しをサポート Feature 여행 계획 AI 에이전트 데모는 LangChain 1.0, 阿里通義 Qwen, MCP(amap-maps) 를 사용하여 구축된 여행 계획 도구로, 고도地圖 관련 툴의 병렬 호출을 지원 El agente de inteligencia artificial ''feature'' utiliza LangChain 1.0, MCP y Gradio para planificar viajes de manera eficiente, con capacidades de búsqueda de POI y planificación de rutas L''agent d''intelligence artificielle ''feature'' utilise LangChain 1.0, MCP et Gradio pour planifier des voyages de manière efficace, avec des capacités de recherche de POI et de planification de routes Der KI-Agent ''feature'' nutzt LangChain 1.0, MCP und Gradio für effiziente Reiseplanung, mit Fähigkeiten zur POI-Suche und Routenplanung O feature é uma demonstração de agente de planejamento de viagens baseado em LangChain 1.0, MCP e Gradio Функция - это демонстрация агента планирования путешествий на основе LangChain 1.0, MCP и Gradio для ИИ Агентов الميزة هي-demo لمخطط رحلات dựa على LangChain 1.0 و MCP و Gradio لأدوات الذكاء الاصطناعي how to use feature for tour planning LangChain 1.0 alternative feature vs Qwen feature install guide what is feature in AI agents feature setup for MCP Gaode maps integration with feature tour planning agent demo with feature feature for travel recommendations Feature 旅游规划 Agent Demo LangChain 1.0 阿里通义 Qwen MCP(amap-maps) 高德地图 旅游规划工具 AI Agent Gradio 中间件 城市约束 Supports parallel calls to Gaode maps tools for POI search, route planning, and weather queries Implements middleware-level city constraints and tool budget control Utilizes Gradio frontend for streamlined conversations and debug log viewing Enforces output city safety checks for secure travel planning Follows strict code style guidelines for consistency with existing projects Leverages ls, grep, and read commands for efficient code location and planning Feature is a LangChain 1.0-based AI agent demo for tourism planning, utilizing Qwen and MCP for efficient travel recommendations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SpacePlushy/portfolio/Global Conventions', 'community', 'SpacePlushy', 'portfolio', 'SpacePlushy/portfolio', 'Global Conventions', 0, 0, 41, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:51.084Z', '32f3e933f0d89e7ac240fd62e02a382fcaaa9905fa59936f039d6dbbd9d13a25', '{"id":"SpacePlushy/portfolio/Global Conventions","name":"Global Conventions","description":{"en":"Global Conventions provides Claude Code with guidance on coding standards, helping developers organize project directories and manage environment variables. This skill benefits developers working with AI agents.","zh":"全球约定技能提供了如何保持编码标准的指导，包括项目目录结构、环境变量和Git提交消息","ja":"グローバル規約スキルは、コード規約を維持する方法を提供します。プロジェクトディレクトリ構造、環境変数、Gitコミットメッセージなど","ko":"글로벌 규약 스킬은 코딩 표준을 유지하는 방법을 제공합니다. 프로젝트 디렉토리 구조, 환경 변수, Git 커밋 메시지 등","es":"Las Convenciones Globales proporcionan a Claude Code orientación específica sobre cómo adherirse a los estándares de codificación. Mejora la organización y la gestión de proyectos.","fr":"Les Conventions Globales fournissent à Claude Code des conseils spécifiques sur la façon d''adhérer aux normes de codage. Améliorez l''organisation et la gestion de vos projets.","de":"Die Globalen Konventionen liefern Claude Code spezifische Anleitung zur Einhaltung von Codierungsstandards. Verbessern Sie die Organisation und Verwaltung Ihrer Projekte.","pt":"Conheça as convenções globais para desenvolvedores, incluindo estruturas de diretórios e variáveis de ambiente, para projetos de desenvolvimento com Claude Code","ru":"Ознакомьтесь с глобальными конвенциями для разработчиков, включая структуры директорий и переменные окружения, для проектов разработки с помощью Claude Code","ar":"تعرف على الاتفاقيات العالمية لأدوات الذكاء الاصطناعي، بما في ذلك هيكل الدليل ومتغيرات البيئة، لمشاريع التطوير مع Claude Code"},"seo":{"title":{"en":"Global Conventions: Setu