INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SpacePlushy/portfolio/Global Conventions', 'Global Conventions', 'SpacePlushy', 'portfolio', 'community', 'Global Conventions SpacePlushy portfolio community Global Conventions provides Claude Code with guidance on coding standards, helping developers organize project directories and manage environment variables. This skill benefits developers working with AI agents. 全球约定技能提供了如何保持编码标准的指导，包括项目目录结构、环境变量和Git提交消息 グローバル規約スキルは、コード規約を維持する方法を提供します。プロジェクトディレクトリ構造、環境変数、Gitコミットメッセージなど 글로벌 규약 스킬은 코딩 표준을 유지하는 방법을 제공합니다. 프로젝트 디렉토리 구조, 환경 변수, Git 커밋 메시지 등 Las Convenciones Globales proporcionan a Claude Code orientación específica sobre cómo adherirse a los estándares de codificación. Mejora la organización y la gestión de proyectos. Les Conventions Globales fournissent à Claude Code des conseils spécifiques sur la façon d''adhérer aux normes de codage. Améliorez l''organisation et la gestion de vos projets. Die Globalen Konventionen liefern Claude Code spezifische Anleitung zur Einhaltung von Codierungsstandards. Verbessern Sie die Organisation und Verwaltung Ihrer Projekte. Conheça as convenções globais para desenvolvedores, incluindo estruturas de diretórios e variáveis de ambiente, para projetos de desenvolvimento com Claude Code Ознакомьтесь с глобальными конвенциями для разработчиков, включая структуры директорий и переменные окружения, для проектов разработки с помощью Claude Code تعرف على الاتفاقيات العالمية لأدوات الذكاء الاصطناعي، بما في ذلك هيكل الدليل ومتغيرات البيئة، لمشاريع التطوير مع Claude Code how to use Global Conventions what is Global Conventions Global Conventions alternative Global Conventions vs coding standards Global Conventions install Global Conventions setup guide coding standards for AI agents organizing project directories managing environment variables 全球约定 编码标准 项目目录结构 环境变量 Git提交消息 AIエージェント 代码质量 开发最佳实践 Organizes project directory structure using src/, public/, components/, and pages/ directories Manages environment variables with .env files and PUBLIC_ prefix for client-exposed variables Sets up Content Collections with Zod schemas in src/content/config.ts Writes git commit messages using standardized formatting Provides guidance on coding standards for AI agent development Global Conventions is a skill that provides specific guidance on coding standards for handling global conventions in AI agent development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yu-iskw/meta-agent-skills/add-skill-templates', 'community', 'yu-iskw', 'meta-agent-skills', 'yu-iskw/meta-agent-skills', 'add-skill-templates', 0, 0, 41, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:51.376Z', 'c9c55a3c8d270063c7eb2fdc70a600ee370936cb1dce5309df0743eee5da418b', '{"id":"yu-iskw/meta-agent-skills/add-skill-templates","name":"add-skill-templates","description":{"en":"The add-skill-templates skill standardizes the process of adding new Agent Skill templates to the meta-agent-skills framework, ensuring automatic instantiation by the Meta-Agent. This benefits developers seeking to add new capabilities to their AI agents.","zh":"标准化的AIエージェント技能模板添加，用于Meta-Agent框架的自动实例化","ja":"AIエージェントスキルテンプレートを追加してMeta-Agentフレームワークを自動インスタンス化","ko":"표준화된 AI 에이전트 스킬 템플릿 추가, 메타 에이전트 프레임워크 자동 인스턴스화","es":"Las plantillas de habilidades de agente de inteligencia artificial estandarizan el proceso de agregar nuevas capacidades al framework de meta-agent-skills.","fr":"Les modèles de compétences d''agent d''intelligence artificielle standardisent le processus d''ajout de nouvelles capacités au framework de meta-agent-skills.","de":"KI-Agenten-Skill-Vorlagen standardisieren den Prozess des Hinzufügens neuer Fähigkeiten zum meta-agent-skills-Framework.","pt":"O add-skill-templates padroniza o processo de adicionar novos templates de habilidades de agentes de IA ao framework meta-agent-skills","ru":"Add-skill-templates стандартизирует процесс добавления новых шаблонов навыков ИИ Агентов в фреймворк meta-agent-skills","ar":"يحدد add-skill-templates عملية إضافة قوالب مهارات جديدة للوكلاء الذكيين إلى إطار عمل meta-agent-skills"},"seo":{"title":{"en":"add-skill-templates: Setup Guide for AI Agents","zh":"AIエージェント技能模板添加指南","ja":"AIエージェントスキルテンプレートの設定方法","ko":"AI 에이전트 스킬 템플릿 추가 가이드","es":"Guía de configuración de plantillas de habilidades de age...","fr":"Guide de configuration des modèles de compétences d''agent...","de":"Konfigurationsleitfaden für KI-Agenten-Skill-Vorlagen","pt":"Guia de Configuração add-skill-templates para Agentes de IA","ru":"Настройка ИИ Агентов с помощью add-skill-templates","ar":"دليل إعداد add-skill-templates لعمليات التطوير الذاتي للو..."},"description":{"en":"Discover how to bootstrap your codebase with standardized AI agent skills. Learn to add new templates with our step-by-step guide and unlock autonomous devel...","zh":"标准化的AIエージェント技能模板添加，自动实例化Meta-Agent框架","ja":"AIエージェントスキルテンプレートを追加してMeta-Agentフレームワークを自動インスタンス化","ko":"표준화된 AI 에이전트 스킬 템플릿 추가, 메타 에이전트 프레임워크 자동 인스턴스화","es":"Aprende a agregar plantillas de habilidades de agente de inteligencia artificial con nuestro framework de meta-agent-skills","fr":"Découvrez comment ajouter des modèles de compétences d''agent d''intelligence artificielle avec notre framework de meta-agent-skills","de":"Erfahren Sie, wie Sie KI-Agenten-Skill-Vorlagen mit unserem meta-agent-skills-Framework hinzufügen","pt":"Aprenda a adicionar templates de habilidades de agentes de IA de forma padrão e portátil com add-skill-templates","ru":"Откройте для себя, как добавлять шаблоны навыков ИИ Агентов с помощью add-skill-templates","ar":"اكتشف كيفية إضافة قوالب مهارات الوكلاء الذكيين بسهولة باستخدام add-skill-templates"},"definition":{"en":"add-skill-templates is a skill that standardizes the process of adding new Agent Skill templates to the meta-agent-skills framework for autonomous development.","zh":"AIエージェント技能模板添加是一种标准化的过程，用于向Meta-Agent框架添加新技能","ja":"AIエージェントスキルテンプレート追加は、Meta-Agentフレームワークに新しいスキルを追加するための標準化されたプロセス","ko":"AI 에이전트 스킬 템플릿 추가는 메타 에이전트 프레임워크에 새로운 스킬을 추가하기 위한 표준화된 프로세스","es":"Una plantilla de habilidad de agente de inteligencia artificial es un conjunto de capacidades estandarizadas para el desarrollo autónomo","fr":"Un modèle de compétence d''agent d''intelligence artificielle est un ensemble de capacités standardisées pour le développement autonome","de":"Eine KI-Agenten-Skill-Vorlage ist ein Satz standardisierter Fähigkeiten für die autonome Entwicklung","pt":"Add-skill-templates é uma habilidade que padroniza a criação de templates de habilidades de agentes de IA","ru":"Add-skill-templates — это навык, который стандартизирует создание шаблонов навыков ИИ Агентов","ar":"add-skill-templates هو مهارة تحدد قوالب مهارات الوكلاء الذكيين"},"features":{"en":["Ensures new templates follow the required structure for automatic instantiation by the Meta-Agent","Supports adding new standard capabilities such as deploy-k8s and performance-bench to the meta-agent-skills framework","Allows cloning or using existing templates as a basis for new ones","Standardizes the process of adding new Agent Skill templates","Enables automatic instantiation by the Meta-Agent"],"zh":["标准化的AIエージェント技能模板","自动实例化Meta-Agent框架","支持添加新标准能力（例如deploy-k8s、performance-bench）","支持克隆或使用现有模板作为新模板的基础","适用于Meta-Agent框架的自动化开发"],"ja":["標準化されたAIエージェントスキルテンプレート","Meta-Agentフレームワークの自動インスタンス化","新しい標準能力（例：deploy-k8s、performance-bench）の追加をサポート","既存のテンプレートをクローンまたは新しいテンプレートの基礎として使用することをサポート","Meta-Agentフレームワークの自動化開発に適している"],"ko":["표준화된 AI 에이전트 스킬 템플릿","메타 에이전트 프레임워크의 자동 인스턴스화","새로운 표준 능력（예：deploy-k8s、performance-bench）的 추가를 지원","기존 템플릿을 클론 또는 새로운 템플릿의 基礎로 사용하는 것을 지원","메타 에이전트 프레임워크의 자동화 개발에 적합"],"es":["Estructura de plantillas de habilidades estandarizadas","Instanciación automática por el Meta-Agente","Compatibilidad con capacidades como deploy-k8s y performance-bench","Clonación y personalización de plantillas existentes","Integración con el framework de meta-agent-skills"],"fr":["Structure de modèles de compétences standardisés","Instanciation automatique par le Meta-Agente","Compatibilité avec des capacités comme deploy-k8s et performance-bench","Clonage et personnalisation de modèles existants","Intégration avec le framework de meta-agent-skills"],"de":["Struktur standardisierter Skill-Vorlagen","Automatische Instanzierung durch den Meta-Agente","Kompatibilität mit Fähigkeiten wie deploy-k8s und performance-bench","Klonen und Anpassen bestehender Vorlagen","Integration mit dem meta-agent-skills-Framework"],"pt":["Padronização de templates de habilidades de agentes de IA","Instanciação automática por meio do Meta-Agent","Suporte à clonagem de templates existentes","Integração com o framework meta-agent-skills"],"ru":["Стандартизация шаблонов навыков ИИ Агентов","Автоматическая инстанциация с помощью Meta-Agent","Поддержка клонирования существующих шаблонов","Интеграция с фреймворком meta-agent-skills"],"ar":["تحديد قوالب مهارات الوكلاء الذكيين","الاستخدام التلقائي بواسطة الوكيل الأعلى","دعم استنساخ القوالب الحالية","التكامل مع إطار عمل meta-agent-skills"]},"keywords":{"en":["how to use add-skill-templates","what is add-skill-templates","add-skill-templates setup guide","add-skill-templates install","add-skill-templates alternative","add-skill-templates vs meta-agent-skills"],"zh":["AIエージェント技能模板添加","Meta-Agent框架","自动实例化","标准化的AIエージェント技能","deploy-k8s","performance-bench","AIエージェント开发"],"ja":["AIエージェントスキルテンプレート追加","Meta-Agentフレームワーク","自動インスタンス化","標準化されたAIエージェントスキル","deploy-k8s","performance-bench","AIエージェント開発"],"ko":["AI 에이전트 스킬 템플릿 추가","메타 에이전트 프레임워크","자동 인스턴스화","표준화된 AI 에이전트 스킬","deploy-k8s","performance-bench","AI 에이전트 개발"],"es":["agente de inteligencia artificial","plantillas de habilidades","meta-agent-skills","desarrollo autónomo","deploy-k8s","performance-bench","framework de inteligencia artificial","_agentes de inteligencia artificial","herramientas de inteligencia artificial"],"fr":["agent d''intelligence artificielle","modèles de compétences","meta-agent-skills","développement autonome","deploy-k8s","performance-bench","framework d''intelligence artificielle","agents d''intelligence artificielle","outils d''intelligence artificielle"],"de":["KI-Agent","Skill-Vorlagen","meta-agent-skills","autonome Entwicklung","deploy-k8s","performance-bench","KI-Framework","KI-Agenten","KI-Tools"],"pt":["agentes de IA","templates de habilidades","meta-agent-skills","desenvolvimento de software","padronização de código","instanciação automática"],"ru":["ИИ Агенты","шаблоны навыков","meta-agent-skills","разработка программного обеспечения","стандартизация кода","автоматическая инстанциация"],"ar":["الوكلاء الذكيين","قوالب مهارات","meta-agent-skills","تطوير البرمجيات","تحديد الكود","الاستخدام التلقائي"]}},"owner":"yu-iskw","repo":"meta-agent-skills","repoPath":"yu-iskw/meta-agent-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.317Z","topics":[],"category":"community","skillMd":{"name":"add-skill-templates","description":"Add new Agent Skill templates to the meta-agent-skills framework.","bodyPreview":"# Add Skill Templates\n\n## Purpose\n\nThis skill standardizes the process of adding new Agent Skill templates to the `meta-agent-skills` framework. It ensures that new templates follow the required structure for automatic instantiation by the Meta-Agent.\n\n## When to Use\n\n- When you want to add a new standard capability (e.g., `deploy-k8s`, `performance-bench`) to the `meta-agent-skills` framework.\n- When existing templates need to be cloned or used as a basis for a new one.\n\n## Instructions\n\n1.  **","body":"# Add Skill Templates\n\n## Purpose\n\nThis skill standardizes the process of adding new Agent Skill templates to the `meta-agent-skills` framework. It ensures that new templates follow the required structure for automatic instantiation by the Meta-Agent.\n\n## When to Use\n\n- When you want to add a new standard capability (e.g., `deploy-k8s`, `performance-bench`) to the `meta-agent-skills` framework.\n- When existing templates need to be cloned or used as a basis for a new one.\n\n## Instructions\n\n1.  **Identify New Skill Requirements**:\n    - Determine the name and purpose of the new skill.\n    - Identify the primary commands that should be included in its **Commands** table.\n\n2.  **Use Boilerplate**:\n    - Read the boilerplate template from `assets/skill-template-boilerplate.md`.\n    - Create a new file in `skills/meta-agent-skills/assets/templates/skills/` named `<skill-name>.md`.\n\n3.  **Configure Template**:\n    - Fill in the YAML frontmatter (`name`, `description`).\n    - Use placeholders like `{{ order }}`, `{{ component }}`, `{{ path }}`, `{{ layer }}`, `{{ command }}`, and `{{ description }}` in the **Commands** table.\n    - Refer to [references/conventions.md](references/conventions.md) for guidance on placeholder usage and layer naming.\n\n4.  **Register Capability**:\n    - Update the `Capabilities Generated` section in `skills/meta-agent-skills/SKILL.md` to include the new skill.\n\n5.  **Verify**:\n    - Ensure the template is readable and follows the format of existing templates like `lint-fix.md`.\n\n## References\n\n- [Conventions](references/conventions.md)\n- [Agent Skills Specification](https://agentskills.io/specification)\n"},"lastSynced":"2026-03-08T02:02:51.376Z","agentAnalysis":{"suitability":{"en":"Perfect for Meta-Agents needing standardized skill template integration for automatic instantiation.","zh":"非常适合需要标准化技能模板集成以实现自动实例化的Meta-Agents","ja":"Meta-Agentsが標準化されたスキルテンプレートの統合を自動的にインスタンス化する必要がある場合に最適","ko":"메타 에이전트가 표준화된 스킬 템플릿 통합을 자동으로 인스턴스화해야 하는 경우에 적합","es":"Perfecto para los Meta-Agentes que necesitan integración de plantillas de habilidades estandarizadas para instanciación automática.","fr":"Parfait pour les Meta-Agents ayant besoin d''une intégration de modèles de compétences standardisés pour l''instanciation automatique.","de":"Perfekt für Meta-Agents, die eine standardisierte Skill-Vorlagen-Integration für die automatische Instanziierung benötigen.","pt":"Perfeito para Meta-Agents que necessitam de integração de modelo de habilidade padronizado para instância automática.","ru":"Идеально подходит для Meta-агентов, требующих стандартизированного шаблона навыков для автоматического создания экземпляра.","ar":"مثالي لملحقات Meta التي تحتاج إلى دمج قالب مهارات معياري للتنسيق التلقائي."},"recommendation":{"en":"Empowers agents to standardize new skill templates within the meta-agent-skills framework, ensuring seamless integration and automatic instantiation by the Meta-Agent, utilizing required structure and protocols for capabilities like deploy-k8s and performance-bench.","zh":"赋予代理标准化新的技能模板在meta-agent-skills框架内，确保无缝集成和自动实例化由Meta-Agent，利用所需的结构和协议，例如deploy-k8s和performance-bench的能力","ja":"エージェントにmeta-agent-skillsフレームワーク内で新しいスキルテンプレートを標準化する力を与え、Meta-Agentによるシームレスな統合と自動インスタンス化を保証する、deploy-k8sやperformance-benchなどの機能のための必要な構造とプロトコルを利用する","ko":"에이전트가 메타 에이전트 스킬 프레임워크 내에서 새로운 스킬 템플릿을 표준화할 수 있도록 하여 메타 에이전트에 의한 자동 인스턴스화와无缝集成을 보장하며, deploy-k8s 및 performance-bench와 같은 기능을 위한 필요한 구조 및 프로토콜을 활용","es":"Habilita a los agentes a estandarizar nuevos modelos de habilidades dentro del marco de habilidades del meta-agente, garantizando una integración sin problemas y una instanciación automática por el Meta-Agente, utilizando la estructura y los protocolos necesarios para capacidades como deploy-k8s y performance-bench.","fr":"Permet aux agents de standardiser de nouveaux modèles de compétences au sein du cadre des compétences du meta-agent, assurant une intégration sans heurts et une instanciation automatique par le Meta-Agent, en utilisant la structure et les protocoles nécessaires pour des capacités comme deploy-k8s et performance-bench.","de":"Ermöglicht es den Agenten, neue Skill-Vorlagen innerhalb des Meta-Agent-Skill-Frameworks zu standardisieren, um eine nahtlose Integration und eine automatische Instanziierung durch den Meta-Agenten sicherzustellen, unter Verwendung der erforderlichen Struktur und Protokolle für Fähigkeiten wie deploy-k8s und performance-bench.","pt":"Habilita os agentes a padronizar novos modelos de habilidades dentro do framework meta-agent-skills, garantindo integração sem problemas e instância automática pelo Meta-Agent, utilizando estrutura e protocolos necessários para capacidades como deploy-k8s e performance-bench.","ru":"Предоставляет агентам возможность стандартизировать новые шаблоны навыков в рамках фреймворка meta-agent-skills, обеспечивая бесшовную интеграцию и автоматическое создание экземпляра Meta-агентом, используя необходимую структуру и протоколы для возможностей, таких как deploy-k8s и performance-bench.","ar":"تمكين الوكلاء من تحديد معايير قوالب مهارات جديدة داخل إطار عمل meta-agent-skills، مما يضمن التكامل السلس والتنسيق التلقائي بواسطة Meta-Agent، باستخدام الهيكل والبروتوكولات المطلوبة لميزات مثل deploy-k8s و performance-bench."},"useCases":{"en":["Standardizing new skill templates for meta-agent-skills framework","Cloning existing templates for customized capabilities","Ensuring automatic instantiation of new agent skills by the Meta-Agent"],"zh":["为meta-agent-skills框架标准化新的技能模板","克隆现有的模板以实现自定义功能","确保新的代理技能由Meta-Agent自动实例化"],"ja":["meta-agent-skillsフレームワーク用の新しいスキルテンプレートを標準化する","既存のテンプレートをクローンしてカスタマイズされた機能を実現する","新しいエージェントスキルがMeta-Agentによって自動的にインスタンス化されることを保証する"],"ko":["메타 에이전트 스킬 프레임워크를 위한 새로운 스킬 템플릿을 표준화하는 것","기존 템플릿을 복제하여 사용자 지정 기능을 구현하는 것","新的 에이전트 스킬이 메타 에이전트에 의해 자동으로 인스턴스화되는 것을 보장"],"es":["Estandarizar nuevos modelos de habilidades para el marco de habilidades del meta-agente","Clonar plantillas existentes para capacidades personalizadas","Garantizar la instanciación automática de nuevas habilidades del agente por el Meta-Agente"],"fr":["Standardiser de nouveaux modèles de compétences pour le cadre des compétences du meta-agent","Cloner des modèles existants pour des capacités personnalisées","Assurer l''instanciation automatique de nouvelles compétences de l''agent par le Meta-Agent"],"de":["Neue Skill-Vorlagen für das Meta-Agent-Skill-Framework standardisieren","Vorhandene Vorlagen für benutzerdefinierte Fähigkeiten klonen","Automatische Instanziierung neuer Agentenfähigkeiten durch den Meta-Agenten sicherstellen"],"pt":["Padronizar novos modelos de habilidades para o framework meta-agent-skills","Clonar modelos existentes para capacidades personalizadas","Garantir a instância automática de novas habilidades de agente pelo Meta-Agent"],"ru":["Стандартизировать новые шаблоны навыков для фреймворка meta-agent-skills","Клонировать существующие шаблоны для настраиваемых возможностей","Обеспечить автоматическое создание экземпляра новых навыков агента Meta-агентом"],"ar":["تحديد معايير قوالب مهارات جديدة لإطار عمل meta-agent-skills","استنساخ قوالب موجودة لميزات مخصصة","ضمان التنسيق التلقائي لمهارات الوكيل الجديدة بواسطة Meta-Agent"]},"limitations":{"en":["Requires adherence to meta-agent-skills framework structure","Limited to templates compatible with the Meta-Agent''s instantiation protocol"],"zh":["需要遵守meta-agent-skills框架的结构","仅限与Meta-Agent的实例化协议兼容的模板"],"ja":["meta-agent-skillsフレームワークの構造に従う必要がある","Meta-Agentのインスタンス化プロトコルと互換性のあるテンプレートのみ"],"ko":["메타 에이전트 스킬 프레임워크의 구조를 따라야 함","메타 에이전트의 인스턴스화 프로토콜과 호환되는 템플릿만"],"es":["Requiere adherencia a la estructura del marco de habilidades del meta-agente","Limitado a plantillas compatibles con el protocolo de instanciación del Meta-Agente"],"fr":["Nécessite l''adhésion à la structure du cadre des compétences du meta-agent","Limité aux modèles compatibles avec le protocole d''instanciation du Meta-Agent"],"de":["Erfordert die Einhaltung der Struktur des Meta-Agent-Skill-Frameworks","Begrenzt auf Vorlagen, die mit dem Instanziierungsprotokoll des Meta-Agents kompatibel sind"],"pt":["Exige aderência à estrutura do framework meta-agent-skills","Limitado a modelos compatíveis com o protocolo de instância do Meta-Agent"],"ru":["Требует соблюдения структуры фреймворка meta-agent-skills","Ограничен шаблонами, совместимыми с протоколом создания экземпляра Meta-агента"],"ar":["يتطلب الالتزام بهيكل إطار عمل meta-agent-skills","محدود بالمواد المتوافقة مع بروتوكول إنشاء Meta-Agent"]},"version":4},"contentHash":"c9c55a3c8d270063c7eb2fdc70a600ee370936cb1dce5309df0743eee5da418b","qualityScore":41}');
