INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yu-iskw/meta-agent-skills/add-skill-templates', 'add-skill-templates', 'yu-iskw', 'meta-agent-skills', 'community', 'add-skill-templates yu-iskw meta-agent-skills community The add-skill-templates skill standardizes the process of adding new Agent Skill templates to the meta-agent-skills framework, ensuring automatic instantiation by the Meta-Agent. This benefits developers seeking to add new capabilities to their AI agents. 标准化的AIエージェント技能模板添加，用于Meta-Agent框架的自动实例化 AIエージェントスキルテンプレートを追加してMeta-Agentフレームワークを自動インスタンス化 표준화된 AI 에이전트 스킬 템플릿 추가, 메타 에이전트 프레임워크 자동 인스턴스화 Las plantillas de habilidades de agente de inteligencia artificial estandarizan el proceso de agregar nuevas capacidades al framework de meta-agent-skills. Les modèles de compétences d''agent d''intelligence artificielle standardisent le processus d''ajout de nouvelles capacités au framework de meta-agent-skills. KI-Agenten-Skill-Vorlagen standardisieren den Prozess des Hinzufügens neuer Fähigkeiten zum meta-agent-skills-Framework. O add-skill-templates padroniza o processo de adicionar novos templates de habilidades de agentes de IA ao framework meta-agent-skills Add-skill-templates стандартизирует процесс добавления новых шаблонов навыков ИИ Агентов в фреймворк meta-agent-skills يحدد add-skill-templates عملية إضافة قوالب مهارات جديدة للوكلاء الذكيين إلى إطار عمل meta-agent-skills how to use add-skill-templates what is add-skill-templates add-skill-templates setup guide add-skill-templates install add-skill-templates alternative add-skill-templates vs meta-agent-skills AIエージェント技能模板添加 Meta-Agent框架 自动实例化 标准化的AIエージェント技能 deploy-k8s performance-bench AIエージェント开发 Ensures new templates follow the required structure for automatic instantiation by the Meta-Agent Supports adding new standard capabilities such as deploy-k8s and performance-bench to the meta-agent-skills framework Allows cloning or using existing templates as a basis for new ones Standardizes the process of adding new Agent Skill templates Enables automatic instantiation by the Meta-Agent add-skill-templates is a skill that standardizes the process of adding new Agent Skill templates to the meta-agent-skills framework for autonomous development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Swader/rescuekit/rescuekit-quickstart', 'community', 'Swader', 'rescuekit', 'Swader/rescuekit', 'rescuekit-quickstart', 0, 0, 41, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:52.841Z', '49b7425b370d57f65b49e5bda7a1ec89f6421009f57794b4456be90af65c46c9', '{"id":"Swader/rescuekit/rescuekit-quickstart","name":"rescuekit-quickstart","description":{"en":"The rescuekit-quickstart skill helps developers onboard to the RescueKit repo or CLI, setup Bun, env vars, or RPC/Alchemy access, and prepare scan, triage, or rescue command sequences.","zh":"RescueKit Quickstart 是一个快速入门指南，帮助开发者快速设置和使用 RescueKit","ja":"RescueKit Quickstart は、開発者が RescueKit を迅速に設定し使用するためのクイックスタートガイドです","ko":"RescueKit Quickstart는 개발자가 RescueKit를 빠르게 설정하고 사용하는 빠른 시작 가이드입니다","es":"RescueKit Quickstart es una herramienta para desarrolladores que facilita la configuración de proyectos con Bun, env vars y acceso RPC/Alchemy","fr":"RescueKit Quickstart est un outil pour les développeurs qui facilite la configuration de projets avec Bun, env vars et l''accès RPC/Alchemy","de":"RescueKit Quickstart ist ein Tool für Entwickler, das die Konfiguration von Projekten mit Bun, env vars und RPC/Alchemy-Zugriff erleichtert","pt":"O RescueKit Quickstart é uma ferramenta para configurar e executar comandos de resgate. Aprenda a usá-lo com segurança e eficiência","ru":"RescueKit Quickstart - это инструмент для настройки и выполнения команд спасения. Узнайте, как использовать его безопасно и эффективно, ИИ Агенты","ar":"RescueKit Quickstart هو أداة لتهيئة وتشغيل أوامر الإنقاذ. تعلم كيفية استخدامها بأمان وفعالية"},"seo":{"title":{"en":"rescuekit-quickstart: Setup Guide for AI Agents","zh":"RescueKit Quickstart 安装指南 - AIエージェント快速入门","ja":"RescueKit Quickstart セットアップガイド - AIエージェントのベストプラクティス","ko":"RescueKit Quickstart 설정 가이드 - AI 도구 빠른 시작","es":"Guía de configuración d