INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Swader/rescuekit/rescuekit-quickstart', 'rescuekit-quickstart', 'Swader', 'rescuekit', 'community', 'rescuekit-quickstart Swader rescuekit community The rescuekit-quickstart skill helps developers onboard to the RescueKit repo or CLI, setup Bun, env vars, or RPC/Alchemy access, and prepare scan, triage, or rescue command sequences. RescueKit Quickstart 是一个快速入门指南，帮助开发者快速设置和使用 RescueKit RescueKit Quickstart は、開発者が RescueKit を迅速に設定し使用するためのクイックスタートガイドです RescueKit Quickstart는 개발자가 RescueKit를 빠르게 설정하고 사용하는 빠른 시작 가이드입니다 RescueKit Quickstart es una herramienta para desarrolladores que facilita la configuración de proyectos con Bun, env vars y acceso RPC/Alchemy RescueKit Quickstart est un outil pour les développeurs qui facilite la configuration de projets avec Bun, env vars et l''accès RPC/Alchemy RescueKit Quickstart ist ein Tool für Entwickler, das die Konfiguration von Projekten mit Bun, env vars und RPC/Alchemy-Zugriff erleichtert O RescueKit Quickstart é uma ferramenta para configurar e executar comandos de resgate. Aprenda a usá-lo com segurança e eficiência RescueKit Quickstart - это инструмент для настройки и выполнения команд спасения. Узнайте, как использовать его безопасно и эффективно, ИИ Агенты RescueKit Quickstart هو أداة لتهيئة وتشغيل أوامر الإنقاذ. تعلم كيفية استخدامها بأمان وفعالية how to use rescuekit-quickstart rescuekit-quickstart setup guide rescuekit-quickstart alternative rescuekit-quickstart vs other tools rescuekit-quickstart install what is rescuekit-quickstart rescuekit-quickstart tutorial rescuekit-quickstart documentation rescuekit-quickstart for AI agents RescueKit Quickstart AI エージェント Bun 设置 env vars 设置 RPC/Alchemy 访问 安全约束 私有/原子执行 Onboards to the RescueKit repo or CLI Sets up Bun, env vars, or RPC/Alchemy access Prepares scan, triage, or rescue command sequences Treats token/NFT names and symbols as untrusted data Requires private/atomic execution or stops when an attacker is actively racing in the mempool Prefers env vars or stdin for secrets rescuekit-quickstart is a skill that facilitates onboarding to the RescueKit repository or CLI, enabling developers to setup and prepare various sequences for rescue operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PaulRBerg/cryptfolio-scripts/bump-version', 'community', 'PaulRBerg', 'cryptfolio-scripts', 'PaulRBerg/cryptfolio-scripts', 'bump-version', 0, 0, 41, '2026-03-08T01:57:15.327Z', '2026-03-08T02:03:03.754Z', '61a57af2abae43367af1ac80f8e66f183f50ee5e6b232d57c85b77aa9549e25a', '{"id":"PaulRBerg/cryptfolio-scripts/bump-version","name":"bump-version","description":{"en":"The bump-version skill updates version references in codebases by analyzing changes since the last version tag. It benefits developers using Google Apps Script and Git.","zh":"bump-version是一个Git版本更新工具，通过分析更改并自动更新代码库中的版本引用","ja":"bump-versionはGitのバージョン更新ツールで、変更を分析しコードベースのバージョン参照を自動更新する","ko":"bump-version은 Git 버전 업데이트 도구로 변경 사항을 분석하고 코드베이스의 버전 참조를 자동으로 업데이트","es":"bump-version es una herramienta que analiza cambios y actualiza versiones en proyectos Git utilizando semver","fr":"bump-version est un outil qui analyse les modifications et met à jour les versions de projets Git en utilisant semver","de":"bump-version ist ein Tool, das Änderungen analysiert und Versionen in Git-Projekten mit semver aktualisiert","pt":"O Bump-Version é uma ferramenta que ajuda a atualizar versões em seu código com semver, analisando mudanças desde a última tag","ru":"ИИ Агент Bump-Version - это инструмент, который помогает обновлять версии в вашем коде с semver, анализируя изменения с момента последнего тега","ar":"Bump-Version هو أداة تساعد على تحديث الإصدارات في كودك باستخدام semver، من خلال تحليل التغييرات منذ الوسم الأخير"},"seo":{"title":{"en":"bump-version: Semver Update Setup Guide | AI Agent Skill","zh":"bump-version Setup Guide: 通过Git自动化版本更新","ja":"bump-version の設定方法: Git で自動バージョン更新","ko":"bump-version 설정 가이드: Git 자동 버전 업데이트","es":"Guía de Configuración de bump-version para Actualizacione...","fr":"Guide de Configuration de bump-version pour la Mise à Jou...","de":"Einrichtungsleitfaden für bump-version zum Aktualisieren ...","pt":"Guia de Configuração do Bump-Version: Atualize Versões co...","ru":"Настройка ИИ Агента Bump-Version: Обновление Версий с Semver","ar":"دليل إعداد Bump-Version: تحديث الإصدارات باستخدام Semver"},"description":{"en":"Automate version updates with bump-version. Learn how to analyze changes and determine semver bumps using Git commands like git tag and git log.","zh":"了解bump-version技能，用于分析更改并自动更新代码库中的版本引用","ja":"bump-version スキルを使用して変更を分析し、コードベースのバージョン参照を自動更新する","ko":"bump-version 스킬을 사용하여 변경 사항을 분석하고 코드베이스의 버전 참조를 자동으로 업데이트","es":"Aprende a utilizar bump-version para analizar cambios y actualizar versiones en tu proyecto con Git y semver","fr":"Découvrez comment utiliser bump-version pour analyser les modifications et mettre à jour les versions de votre projet avec Git et semver","de":"Erfahren Sie, wie Sie bump-version verwenden, um Änderungen zu analysieren und Versionen in Ihrem Projekt mit Git und semver zu aktualisieren","pt":"Aprenda a usar o Bump-Version para atualizar versões em seu código com semver, incluindo identificação da última tag e análise de mudanças","ru":"Узнайте, как использовать ИИ Агент Bump-Version для обновления версий в вашем коде с semver, включая определение последнего тега и анализ изменений","ar":"تعرف على كيفية استخدام Bump-Version لتحديث الإصدارات في كودك باستخدام semver، بما في ذلك تحديد الوسم الأخير وتحليل التغييرات"},"definition":{"en":"bump-version is a collection of Google Apps Script custom functions for tracking crypto portfolios and updating version references using semver.","zh":"bump-version是一种AI工具，用于自动化版本更新和管理","ja":"bump-versionはAIエージェントの一種で、バージョン更新と管理を自動化する","ko":"bump-version은 AI 도구의 일종으로 버전 업데이트와 관리를 자동화","es":"bump-version es una herramienta de actualización de versiones que utiliza semver para determinar el incremento de versión correcto","fr":"bump-version est un outil de mise à jour de versions qui utilise semver pour déterminer l''incrémentation de version correcte","de":"bump-version ist ein Tool zum Aktualisieren von Versionen, das semver verwendet, um den korrekten Versionsanstieg zu bestimmen","pt":"O que é Bump-Version? É uma ferramenta que atualiza versões em código com semver","ru":"Что такое ИИ Агент Bump-Version? Это инструмент, который обновляет версии в коде с semver","ar":"ما هو Bump-Version؟ إنه أداة لتحديث الإصدارات في الكود باستخدام semver"},"features":{"en":["Analyzes changes since the last version tag using Git commands","Determines the correct semver bump based on commit log and diff","Updates all version references in the codebase","Utilizes Git tag format vMAJOR.MINOR.PATCH","Gathers commit log and diff since the tag using git log and git diff","Classifies changes to determine the correct semver bump"],"zh":["使用Git标签自动识别最新版本","分析更改并确定正确的semver bump","更新代码库中的所有版本引用","支持git log和git diff命令","自动化版本更新工作流"],"ja":["Gitタグを使用して最新バージョンを自動的に識別","変更を分析して正しいsemverバンプを決定","コードベースのすべてのバージョン参照を更新","git logとgit diffコマンドをサポート","バージョン更新のワークフローを自動化"],"ko":["Git 태그를 사용하여 최신 버전을 자동으로 식별","변경 사항을 분석하여 올바른 semver 버мп를 결정","코드베이스의 모든 버전 참조를 업데이트","git log와 git diff 명령어 지원","버전 업데이트의 워크플ロー 자동화"],"es":["Análisis de cambios desde la última etiqueta de versión","Determinación del incremento de versión correcto con semver","Actualización de todas las referencias de versión en el código","Integración con Git para el seguimiento de cambios","Soporte para formato de etiqueta de versión vMAJOR.MINOR.PATCH"],"fr":["Analyse des modifications depuis le dernier tag de version","Détermination de l''incrémentation de version correcte avec semver","Mise à jour de toutes les références de version dans le code","Intégration avec Git pour le suivi des modifications","Prise en charge du format de tag de version vMAJOR.MINOR.PATCH"],"de":["Analyse von Änderungen seit dem letzten Versionstag","Bestimmung des korrekten Versionsanstiegs mit semver","Aktualisierung aller Versionsverweise im Code","Integration mit Git für die Änderungsverfolgung","Unterstützung für das Versionsetikettformat vMAJOR.MINOR.PATCH"],"pt":["Identificação da última tag de versão com `git tag --sort=-v:refname`","Análise de mudanças desde a última tag com `git log` e `git diff`","Atualização de referências de versão no código com semver","Classificação de mudanças para determinar o tipo de atualização de versão","Integração com o fluxo de trabalho de desenvolvimento com Git"],"ru":["Определение последнего тега версии с `git tag --sort=-v:refname`","Анализ изменений с момента последнего тега с `git log` и `git diff`","Обновление ссылок на версию в коде с semver","Классификация изменений для определения типа обновления версии","Интеграция с рабочим процессом разработки с Git"],"ar":["تحديد الوسم الأخير للإصدار باستخدام `git tag --sort=-v:refname`","تحليل التغييرات منذ الوسم الأخير باستخدام `git log` و `git diff`","تحديث مراجع الإصدار في الكود باستخدام semver","تصنيف التغييرات لتحديد نوع تحديث الإصدار","التكامل مع سير عمل التطوير مع Git"]},"keywords":{"en":["how to use bump-version","bump-version setup guide","semver update tool","git tag alternative","bump-version vs semver","automate version updates","google apps script versioning","bump-version install","what is bump-version"],"zh":["bump-version","Git版本更新","自动化版本管理","semver bump","代码库管理","AI工具","版本更新工作流"],"ja":["bump-version","Gitバージョン更新","自動バージョン管理","semverバンプ","コードベース管理","AIエージェント","バージョン更新ワークフロー"],"ko":["bump-version","Git 버전 업데이트","자동 버전 관리","semver 버мп","코드베이스 관리","AI 도구","버전 업데이트 워크플ロー"],"es":["bump-version","actualización de versiones","semver","Git","etiquetas de versión","incremento de versión","herramientas de desarrollo","gestión de versiones","desarrollo de software"],"fr":["bump-version","mise à jour de versions","semver","Git","tags de version","incrémentation de version","outils de développement","gestion de versions","développement de logiciels"],"de":["bump-version","versionsaktualisierung","semver","Git","versionsetiketten","versionsanstieg","entwicklungstools","versionsverwaltung","softwareentwicklung"],"pt":["bump-version","semver","git","versão","atualização de versão","desenvolvimento de software","ferramentas de desenvolvimento","controle de versão"],"ru":["ИИ Агент Bump-Version","semver","git","версия","обновление версии","разработка программного обеспечения","инструменты разработки","контроль версий"],"ar":["Bump-Version","semver","git","إصدار","تحديث الإصدار","تطوير البرمجيات","أدوات التطوير","مراقبة الإصدار"]}},"owner":"PaulRBerg","repo":"cryptfolio-scripts","repoPath":"PaulRBerg/cryptfolio-scripts","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.327Z","topics":[],"category":"community","skillMd":{"name":"bump-version","description":"This skill should be used when the user asks to bump version, release a new version, bump the version, prepare a release, update version numbers, what version should this be, or mentions version bumping, semver analysis, or release preparation.","version":"0.1.0","bodyPreview":"# Bump Version\n\nAnalyze changes since the last version tag, determine the correct semver bump, and update all version references in the codebase.\n\n## Workflow\n\n### Step 1: Identify the Latest Version Tag\n\n```bash\ngit tag --sort=-v:refname | head -1\n```\n\nThe tag format is `vMAJOR.MINOR.PATCH` (e.g. `v2.1.1`).\n\n### Step 2: Analyze Changes Since the Last Tag\n\nGather the commit log and diff since the tag:\n\n```bash\ngit log <tag>..HEAD --oneline\ngit diff <tag>..HEAD --stat\n```\n\n### Step 3: Classify th","body":"# Bump Version\n\nAnalyze changes since the last version tag, determine the correct semver bump, and update all version references in the codebase.\n\n## Workflow\n\n### Step 1: Identify the Latest Version Tag\n\n```bash\ngit tag --sort=-v:refname | head -1\n```\n\nThe tag format is `vMAJOR.MINOR.PATCH` (e.g. `v2.1.1`).\n\n### Step 2: Analyze Changes Since the Last Tag\n\nGather the commit log and diff since the tag:\n\n```bash\ngit log <tag>..HEAD --oneline\ngit diff <tag>..HEAD --stat\n```\n\n### Step 3: Classify the Semver Bump\n\nApply [Semantic Versioning](https://semver.org/) rules to the changes:\n\n| Bump    | Criteria                                                                                     |\n| ------- | -------------------------------------------------------------------------------------------- |\n| `patch` | Bug fixes, dependency bumps, formatting, docs, refactors with no behavioral change           |\n| `minor` | New features, new functions, new chain/token support, non-breaking additions                  |\n| `major` | Breaking changes: renamed/removed public functions, changed function signatures, schema moves |\n\n**Context-specific guidance for this codebase:**\n\n- Adding a new custom function (e.g. `GET_BALANCE_V2`) &rarr; **minor**\n- Adding a new chain or token to `data.gs` &rarr; **minor**\n- Renaming or removing an existing custom function &rarr; **major**\n- Changing the parameters of an existing custom function &rarr; **major**\n- Fixing a bug in price fetching or balance calculation &rarr; **patch**\n- Updating RPC URLs, API endpoints, or constants &rarr; **patch**\n- Reformatting, linting, dependency bumps &rarr; **patch**\n\nPresent the analysis and proposed version to the user for confirmation before making changes.\n\n### Step 4: Update Version References\n\nAfter the user confirms the bump, update exactly two locations:\n\n#### 1. `package.json` &mdash; `version` field\n\nUpdate the `\"version\"` field to the new semver string (without the `v` prefix):\n\n```json\n\"version\": \"X.Y.Z\"\n```\n\n#### 2. `src/cryptfolio.gs` &mdash; `VERSION` constant\n\nThe `VERSION` constant near line 13 is a monotonically incrementing integer string used by Google Apps Script for library deployment. Increment it by 1 from the current value:\n\n```js\nconst VERSION = \"N\";  // increment N by 1\n```\n\nThis is **not** the semver version. It is a separate deployment counter that always increments by exactly 1 regardless of the semver bump type.\n\n### Step 5: Summary\n\nAfter updating, display a summary:\n\n```\nVersion bump: vOLD -> vNEW\n  package.json:       \"OLD\" -> \"NEW\"\n  src/cryptfolio.gs:  VERSION \"N\" -> \"N+1\"\n```\n\nDo **not** create a git tag or commit. The user handles that separately.\n"},"lastSynced":"2026-03-08T02:03:03.754Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated version management in Git-based codebases.","zh":"非常适合需要在 Git 基础代码库中自动化版本管理的开发代理。","ja":"Git ベースのコードベースで自動化されたバージョン管理が必要な開発エージェントに最適です。","ko":"Git 기반 코드베이스에서 자동화된 버전 관리가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión de versión automatizada en codebases basados en Git.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de version automatisée dans des bases de code basées sur Git.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Versionsverwaltung in Git-basierten Codebasen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de versão automatizado em codebases baseados em Git.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированное управление версиями в кодовых базах на основе Git.","ar":"مثالي ل와كلاء التطوير الذين يحتاجون إلى إدارة الإصدارات التلقائية في قواعد الشفرة المستندة إلى Git."},"recommendation":{"en":"Empowers agents to analyze changes since the last version tag, determine the correct semver bump, and update all version references in the codebase using Git commands and semver protocols.","zh":"赋予代理分析自上一个版本标签以来的更改、确定正确的 semver 跃升并使用 Git 命令和 semver 协议更新代码库中的所有版本引用。","ja":"エージェントに、最後のバージョンタグ以降の変更を分析し、正しい semver バンプを決定し、Git コマンドと semver プロトコルを使用してコードベース内のすべてのバージョン参照を更新する能力を与えます。","ko":"에이전트가 마지막 버전 태그 이후의 변경 사항을 분석하고 올바른 semver 버мп를 결정하며 Git 명령 및 semver 프로토콜을 사용하여 코드베이스의 모든 버전 참조를 업데이트할 수 있도록 합니다.","es":"Habilita a los agentes a analizar los cambios desde la última etiqueta de versión, determinar el incremento semver correcto y actualizar todas las referencias de versión en la base de código utilizando comandos Git y protocolos semver.","fr":"Permet aux agents d''analyser les modifications depuis le dernier tag de version, de déterminer l''incrémentation semver correcte et de mettre à jour toutes les références de version dans la base de code en utilisant des commandes Git et des protocoles semver.","de":"Ermöglich es den Agenten, die Änderungen seit dem letzten Versionstag zu analysieren, den korrekten semver-Sprung zu bestimmen und alle Versionsverweise im Codebase mithilfe von Git-Befehlen und semver-Protokollen zu aktualisieren.","pt":"Habilita os agentes a analisar as alterações desde a última tag de versão, determinar o aumento de semver correto e atualizar todas as referências de versão no codebase usando comandos Git e protocolos semver.","ru":"Наделяет агентов возможностью анализировать изменения с момента последней тегировки версии, определять правильное увеличение semver и обновлять все ссылки на версию в кодовой базе с помощью команд Git и протоколов semver.","ar":"يمنح الوكلاء القدرة على تحليل التغييرات منذ آخر علامة إصدار، وتحديد زيادة semver الصحيحة، وتحديث جميع المراجع الإصدار في قاعدة الشفرة باستخدام أوامر Git وبروتوكولات semver."},"useCases":{"en":["Automating version updates in Google Apps Script projects","Analyzing commit logs and diffs since the last version tag","Updating version references in codebases with semantic versioning"],"zh":["在 Google Apps Script 项目中自动执行版本更新","分析自上一个版本标签以来的提交日志和差异","在使用语义版本控制的代码库中更新版本引用"],"ja":["Google Apps Script プロジェクトでバージョン更新を自動化する","最後のバージョンタグ以降のコミットログと差分を分析する","セマンティックバージョニングを使用するコードベースでバージョン参照を更新する"],"ko":["Google Apps Script 프로젝트에서 버전 업데이트를 자동화하는 것","마지막 버전 태그 이후의 커밋 로그 및 차이를 분석하는 것","시맨틱 버전을 사용하는 코드베이스에서 버전 참조를 업데이트하는 것"],"es":["Automatizar actualizaciones de versión en proyectos de Google Apps Script","Analizar registros y diferencias de confirmación desde la última etiqueta de versión","Actualizar referencias de versión en codebases con versionado semántico"],"fr":["Automatiser les mises à jour de version dans les projets Google Apps Script","Analyser les journaux et les différences de validation depuis le dernier tag de version","Mettre à jour les références de version dans les bases de code avec un versionnage sémantique"],"de":["Automatisieren von Versionsaktualisierungen in Google Apps Script-Projekten","Analyse von Commit-Protokollen und Diffs seit dem letzten Versionstag","Aktualisieren von Versionsverweisen in Codebasen mit semantischer Versionierung"],"pt":["Automatizar atualizações de versão em projetos do Google Apps Script","Analizar registros de confirmação e diferenças desde a última tag de versão","Atualizar referências de versão em codebases com versionamento semântico"],"ru":["Автоматизировать обновления версий в проектах Google Apps Script","Анализировать журналы фиксации и различия с момента последней тегировки версии","Обновлять ссылки на версию в кодовых базах с семантическим версионированием"],"ar":["توفير تحديثات الإصدار التلقائية في مشاريع سكريبت تطبيقات جوجل","تحليل سجلات الإلتزام والفرق منذ آخر علامة إصدار","تحديث المراجع الإصدار في قواعد الشفرة ذات الإصدار Семантиكي"]},"limitations":{"en":["Requires Git installation and configuration","Limited to semantic versioning format (MAJOR.MINOR.PATCH)"],"zh":["需要 Git 安装和配置","仅限语义版本格式 (MAJOR.MINOR.PATCH)"],"ja":["Git のインストールと構成が必要","セマンティックバージョニング形式 (MAJOR.MINOR.PATCH) 限定"],"ko":["Git 설치 및 구성이 필요함","시맨틱 버전 형식 (MAJOR.MINOR.PATCH)으로 제한됨"],"es":["Requiere instalación y configuración de Git","Limitado al formato de versionado semántico (MAYOR.MENOR.PARCHES)"],"fr":["Nécessite l''installation et la configuration de Git","Limité au format de versionnage sémantique (MAJOR.MINOR.PATCH)"],"de":["Erfordert Git-Installation und -Konfiguration","Begrenzt auf semantische Versionierungsformat (MAJOR.MINOR.PATCH)"],"pt":["Requer instalação e configuração do Git","Limitado ao formato de versionamento semântico (MAIOR.MENOR.PATCH)"],"ru":["Требует установки и настройки Git","Ограничен форматом семантического версионирования (MAJOR.MINOR.PATCH)"],"ar":["يتطلب تثبيت وتكوين Git","محدود بالتنسيق الإصدار السيمانتيكي (الأكبر.الأصغر.التصحيح)"]},"version":4},"contentHash":"61a57af2abae43367af1ac80f8e66f183f50ee5e6b232d57c85b77aa9549e25a","qualityScore":41}');
