INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PaulRBerg/cryptfolio-scripts/bump-version', 'bump-version', 'PaulRBerg', 'cryptfolio-scripts', 'community', 'bump-version PaulRBerg cryptfolio-scripts community The bump-version skill updates version references in codebases by analyzing changes since the last version tag. It benefits developers using Google Apps Script and Git. bump-version是一个Git版本更新工具，通过分析更改并自动更新代码库中的版本引用 bump-versionはGitのバージョン更新ツールで、変更を分析しコードベースのバージョン参照を自動更新する bump-version은 Git 버전 업데이트 도구로 변경 사항을 분석하고 코드베이스의 버전 참조를 자동으로 업데이트 bump-version es una herramienta que analiza cambios y actualiza versiones en proyectos Git utilizando semver bump-version est un outil qui analyse les modifications et met à jour les versions de projets Git en utilisant semver bump-version ist ein Tool, das Änderungen analysiert und Versionen in Git-Projekten mit semver aktualisiert O Bump-Version é uma ferramenta que ajuda a atualizar versões em seu código com semver, analisando mudanças desde a última tag ИИ Агент Bump-Version - это инструмент, который помогает обновлять версии в вашем коде с semver, анализируя изменения с момента последнего тега Bump-Version هو أداة تساعد على تحديث الإصدارات في كودك باستخدام semver، من خلال تحليل التغييرات منذ الوسم الأخير how to use bump-version bump-version setup guide semver update tool git tag alternative bump-version vs semver automate version updates google apps script versioning bump-version install what is bump-version bump-version Git版本更新 自动化版本管理 semver bump 代码库管理 AI工具 版本更新工作流 Analyzes changes since the last version tag using Git commands Determines the correct semver bump based on commit log and diff Updates all version references in the codebase Utilizes Git tag format vMAJOR.MINOR.PATCH Gathers commit log and diff since the tag using git log and git diff Classifies changes to determine the correct semver bump bump-version is a collection of Google Apps Script custom functions for tracking crypto portfolios and updating version references using semver.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('D1ngirsu/MiniDrive/cloud-architect', 'community', 'D1ngirsu', 'MiniDrive', 'D1ngirsu/MiniDrive', 'cloud-architect', 0, 0, 41, '2026-03-08T01:57:15.342Z', '2026-03-08T02:03:30.022Z', '62ee5a98edb64bfb571f1209cc9636a7fddeacd94f057d594db2ee794d00100d', '{"id":"D1ngirsu/MiniDrive/cloud-architect","name":"cloud-architect","description":{"en":"The cloud-architect skill enables senior cloud architects to design enterprise cloud solutions, specializing in multi-cloud strategies and migration patterns. It benefits developers and architects working with AWS, Azure, and GCP.","zh":"云架构师是一种高级云解决方案设计专家，专注于多云架构、迁移策略、成本优化和云原生架构","ja":"クラウドアーキテクトは、高度なクラウドソリューション設計の専門家であり、マルチクラウドアーキテクチャ、移行戦略、コスト最適化、クラウドネイティブアーキテクチャに重点を置いています","ko":"클라우드 아키텍트는 고급 클라우드 솔루션 설계 전문가로, 멀티 클라우드 아키텍처, 마이그레이션 전략, 비용 최적화, 클라우드 네이티브 아키텍처에 중점을 둡니다","es":"Cloud-architect es una herramienta para diseñar soluciones de nube híbrida, con especialización en estrategias de migración y optimización de costos","fr":"Cloud-architect est un outil pour concevoir des architectures cloud natives, avec une spécialisation dans les stratégies de migration et l''optimisation des coûts","de":"Cloud-architect ist ein Tool zum Entwerfen hybrider Cloud-Lösungen, mit Spezialisierung auf Migrationsstrategien und Kostenoptimierung","pt":"O skill de arquiteto de nuvem permite projetar soluções de nuvem escaláveis e seguras, com estratégias de migração e otimização de custos","ru":"Навык облачного архитектора позволяет проектировать масштабируемые и безопасные облачные решения, с стратегиями миграции и оптимизации затрат","ar":"مهارة مهندس سحابي تمكن من تصميم حلول سحابية قابلة للتنمية وأمنة، مع استراتيجيات النقل وتحسين التكاليف"},"seo":{"title":{"en":"cloud-architect: Multi-Cloud Strategy Setup Guide | AI Ag...","zh":"云架构师设置指南 - 多云策略和迁移模式","ja":"クラウドアーキテクトのベストプラクティス - マルチクラウドと移