INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('D1ngirsu/MiniDrive/cloud-architect', 'cloud-architect', 'D1ngirsu', 'MiniDrive', 'community', 'cloud-architect D1ngirsu MiniDrive community The cloud-architect skill enables senior cloud architects to design enterprise cloud solutions, specializing in multi-cloud strategies and migration patterns. It benefits developers and architects working with AWS, Azure, and GCP. 云架构师是一种高级云解决方案设计专家，专注于多云架构、迁移策略、成本优化和云原生架构 クラウドアーキテクトは、高度なクラウドソリューション設計の専門家であり、マルチクラウドアーキテクチャ、移行戦略、コスト最適化、クラウドネイティブアーキテクチャに重点を置いています 클라우드 아키텍트는 고급 클라우드 솔루션 설계 전문가로, 멀티 클라우드 아키텍처, 마이그레이션 전략, 비용 최적화, 클라우드 네이티브 아키텍처에 중점을 둡니다 Cloud-architect es una herramienta para diseñar soluciones de nube híbrida, con especialización en estrategias de migración y optimización de costos Cloud-architect est un outil pour concevoir des architectures cloud natives, avec une spécialisation dans les stratégies de migration et l''optimisation des coûts Cloud-architect ist ein Tool zum Entwerfen hybrider Cloud-Lösungen, mit Spezialisierung auf Migrationsstrategien und Kostenoptimierung O skill de arquiteto de nuvem permite projetar soluções de nuvem escaláveis e seguras, com estratégias de migração e otimização de custos Навык облачного архитектора позволяет проектировать масштабируемые и безопасные облачные решения, с стратегиями миграции и оптимизации затрат مهارة مهندس سحابي تمكن من تصميم حلول سحابية قابلة للتنمية وأمنة، مع استراتيجيات النقل وتحسين التكاليف how to use cloud-architect cloud-architect alternative cloud-architect setup guide what is cloud-architect cloud-architect vs AWS multi-cloud strategy with cloud-architect cloud-architect install cloud-architect cost optimization cloud-architect security by design 云架构师 多云策略 迁移模式 成本优化 云原生架构 AWS Azure GCP 6Rs 迁移策略 Designs highly available, secure, and cost-effective cloud architectures Specializes in multi-cloud strategies across AWS, Azure, and GCP Implements migration strategies using the 6Rs Optimizes cloud costs and ensures operational excellence Ensures security by design in cloud-native architectures Supports enterprise cloud solutions with 15+ years of experience cloud-architect is a senior cloud architect specializing in multi-cloud strategies, migration patterns, cost optimization, and cloud-native architectures across AWS, Azure, and GCP.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Agentic-Engineering-Agency/specsafe/specsafe-complete', 'community', 'Agentic-Engineering-Agency', 'specsafe', 'Agentic-Engineering-Agency/specsafe', 'specsafe-complete', 0, 0, 41, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:48.995Z', '8ac32d13858208bb25a7383275f8dc402f0dea5a7bca808944601cbad20e4a8c', '{"id":"Agentic-Engineering-Agency/specsafe/specsafe-complete","name":"specsafe-complete","description":{"en":"The specsafe-complete skill completes a SpecSafe specification, moving it to the COMPLETE stage. It benefits developers by automating the finalization of specs after QA validation.","zh":"SpecSafe Complete 是一个测试驱动开发框架，用于 AI 辅助开发。它可以完成规格验证并将规格标记为生产就绪","ja":"SpecSafe Complete は、AI エージェントを使用した開発のためのテスト駆動開発フレームワークです。規格を完了し、生産就緒とすることができます","ko":"SpecSafe Complete는 AI 에이전트를 사용한 개발을 위한 테스트 주도 개발 프레임워크입니다. 규격을 완료하고 생산 준비를 표시할 수 있습니다","es":"specsafe-complete es un marco de desarrollo de AI que permite a los desarrolladores finalizar especificaciones de manera eficiente. Utiliza comandos como ''specsafe complete'' para mover las especificaciones al estado de completado.","fr":"specsafe-complete est un cadre de développement d''agents d''IA qui permet aux développeurs de terminer les spécifications de manière efficace. Il utilise des commandes comme ''specsafe complete'' pour déplacer les spécifications à l''état terminé.","de":"specsafe-complete ist ein Rahmenwerk für die AI-Entwicklung, das es Entwicklern ermöglicht, Spezifikationen effizient abzuschließen. Es verwendet Befehle wie ''specsafe complete'', um die Spezifikationen in den abgeschlossenen Status zu versetzen.","pt":"O specsafe-complete é um framework de Test-Driven Development para desenvolvimento de AI assistido, permitindo a validação de QA e a finalização de especificações","ru":"Specsafe-complete - это рамка для тестирования, управляемого разработкой, для разработки приложений ИИ, обеспечивающая проверку QA и завершение спецификаций","ar":"specsafe-complete هو إطار عمل لتطوير الذكاء الاصطناعي مدعوم بالاختبار، يسمح بالتحقق من جودة Guarantee وإتمام المواصفات"},"seo":{"title":{"en":"specsafe-complete: Setup Guide for AI Agents | AI Agent S...","zh":"SpecSafe Complete 设置指南 - AI工具","ja":"SpecSafe Complete のベストプラクティス - AIエージェント","ko":"SpecSafe Complete 설정 가이드 - AI 에이전트","es":"Guía de Configuración de specsafe-complete para Desarroll...","fr":"Configurer specsafe-complete pour le Développement d''Agen...","de":"Einrichtungsanleitung für specsafe-complete in der AI-Ent...","pt":"Guia de Configuração do specsafe-complete: Desenvolviment...","ru":"Настройка specsafe-complete: Рамка для разработки с помощ...","ar":"دليل إعداد specsafe-complete: إطار عمل التطوير المدعوم با..."},"description":{"en":"Get started with specsafe-complete, a Test-Driven Development framework for AI assisted development. Learn how to complete a SpecSafe specification and move ...","zh":"了解如何使用 SpecSafe Complete 完成规格验证，实现 AI 辅助开发的高效性","ja":"SpecSafe Complete を使用して規格を完了し、AI エージェントによる開発を効率化する方法を学びます","ko":"SpecSafe Complete로 규격을 완료하고 AI 에이전트를 통한 개발을 효율화하는 방법을 알아보세요","es":"Aprende a utilizar specsafe-complete para finalizar especificaciones y avanzar en el desarrollo de AI con nuestra guía paso a paso","fr":"Découvrez comment configurer specsafe-complete pour terminer les spécifications et progresser dans le développement d''agents d''IA avec notre guide étape par ...","de":"Erfahren Sie, wie Sie specsafe-complete einrichten, um Spezifikationen abzuschließen und die AI-Entwicklung voranzutreiben, mit unserer Schritt-für-Schritt-A...","pt":"Aprenda a utilizar o specsafe-complete para desenvolver aplicações de AI de forma eficiente com testes dirigidos por desenvolvimento","ru":"Изучите, как использовать specsafe-complete для разработки приложений ИИ с помощью тестирования, управляемого разработкой","ar":"تعرف على كيفية استخدام specsafe-complete لتطوير تطبيقات الذكاء الاصطناعي بفعالية باستخدام اختبار مدعوم بالتطوير"},"definition":{"en":"specsafe-complete is a Test-Driven Development framework for AI assisted development that completes a SpecSafe specification, marking it as production-ready.","zh":"SpecSafe Complete 是一个 AI 工具，用于完成规格验证和将规格标记为生产就绪","ja":"SpecSafe Complete は、規格を完了し、生産就緒とする AI エージェントです","ko":"SpecSafe Complete는 규격을 완료하고 생산 준비를 표시하는 AI 에이전트입니다","es":"specsafe-complete es un marco de desarrollo de AI que permite la finalización de especificaciones mediante pruebas dirigidas","fr":"specsafe-complete est un cadre de développement d''agents d''IA qui permet la finalisation de spécifications via des tests dirigés","de":"specsafe-complete ist ein Rahmenwerk für die AI-Entwicklung, das die Finalisierung von Spezifikationen durch testgetriebene Entwicklung ermöglicht","pt":"Specsafe-complete é um framework de desenvolvimento de AI que permite completar especificações de forma eficiente","ru":"Specsafe-complete - это рамка для разработки ИИ, которая позволяет завершать спецификации эффективно","ar":"specsafe-complete هو إطار عمل لتطوير الذكاء الاصطناعي الذي يسمح بإتمام المواصفات بفعالية"},"features":{"en":["Validates QA passed with GO recommendation","Resolves all critical issues before completion","Uses the `specsafe complete` command to move spec to COMPLETE stage","Moves spec to production-ready stage after completion","Takes spec ID as input (e.g., SPEC-20240204-001)","Automates the finalization of specs after QA validation"],"zh":["验证 QA 通过并检查所有关键问题已解决","使用 CLI 命令 `specsafe complete` 完成规格","将规格移动到 COMPLETE 阶段","将规格标记为生产就绪","支持测试驱动开发","适用于 AI 辅助开发"],"ja":["QA の通過を検証し、すべてのクリティカルな問題が解決されていることを確認する","CLI コマンド `specsafe complete` を使用して規格を完了する","規格を COMPLETE 阶段に移動する","規格を生産就緒とする","テスト駆動開発をサポートする","AI エージェントを使用した開発に適する"],"ko":["QA 통과를 검증하고 모든 임계 문제가 해결되었는지 확인","CLI 명령 `specsafe complete`를 사용하여 규격을 완료","규격을 COMPLETE 단계로 이동","규격을 생산 준비로 표시","테스트 주도 개발을 지원","AI 에이전트를 사용한 개발에 적합"],"es":["Validación de QA para asegurar la calidad de las especificaciones","Uso de comandos como ''specsafe complete'' para mover las especificaciones al estado de completado","Soporte para la finalización de especificaciones mediante pruebas dirigidas","Integración con herramientas de desarrollo de AI para una experiencia de desarrollo más fluida","Capacidad para resolver problemas críticos antes de marcar las especificaciones como listas para producción"],"fr":["Validation de la QA pour assurer la qualité des spécifications","Utilisation de commandes comme ''specsafe complete'' pour déplacer les spécifications à l''état terminé","Prise en charge de la finalisation de spécifications via des tests dirigés","Intégration avec des outils de développement d''agents d''IA pour une expérience de développement plus fluide","Capacité à résoudre des problèmes critiques avant de marquer les spécifications comme prêtes pour la production"],"de":["Qualitätssicherung durch QA-Validierung","Verwendung von Befehlen wie ''specsafe complete'', um Spezifikationen in den abgeschlossenen Status zu versetzen","Unterstützung für die Finalisierung von Spezifikationen durch testgetriebene Entwicklung","Integration mit AI-Entwicklungstools für eine nahtlose Entwicklungserfahrung","Fähigkeit, kritische Probleme vor der Markierung von Spezifikationen als produktionsbereit zu lösen"],"pt":["Validação de QA com recomendação GO","Movimentação da especificação para o estágio COMPLETE","Resolução de problemas críticos","Uso da CLI para completar especificações","Integração com desenvolvimento de AI assistido"],"ru":["Проверка QA с рекомендацией GO","Перемещение спецификации в стадию COMPLETE","Решение критических проблем","Использование CLI для завершения спецификаций","Интеграция с разработкой приложений ИИ"],"ar":["التحقق من جودة Guarantee مع التوصية GO","نقل المواصفات إلى مرحلة COMPLETE","حل المشكلات الحرجة","استخدام CLI لإتمام المواصفات","التكامل مع تطوير تطبيقات الذكاء الاصطناعي"]},"keywords":{"en":["how to use specsafe-complete","specsafe-complete setup guide","specsafe-complete alternative","specsafe-complete vs test-driven development","specsafe-complete install","what is specsafe-complete","specsafe-complete tutorial","specsafe-complete best practices","specsafe-complete for AI agents"],"zh":["SpecSafe Complete","AI 工具","测试驱动开发","规格验证","生产就绪","CLI 命令","AI 辅助开发","软件开发"],"ja":["SpecSafe Complete","AI エージェント","テスト駆動開発","規格検証","生産就緒","CLI コマンド","AI エージェントを使用した開発","ソフトウェア開発"],"ko":["SpecSafe Complete","AI 에이전트","테스트 주도 개발","규격 검증","생산 준비","CLI 명령","AI 에이전트를 사용한 개발","소프트웨어 개발"],"es":["desarrollo de AI","pruebas dirigidas","specsafe-complete","herramientas de desarrollo de AI","finalización de especificaciones","validación de QA","Agentes de IA","desarrollo de software","pruebas de software"],"fr":["développement d''agents d''IA","tests dirigés","specsafe-complete","outils de développement d''agents d''IA","finalisation de spécifications","validation de la QA","Agents d''IA","développement de logiciels","tests de logiciels"],"de":["AI-Entwicklung","testgetriebene Entwicklung","specsafe-complete","AI-Entwicklungstools","Finalisierung von Spezifikationen","QA-Validierung","KI-Agenten","Softwareentwicklung","Softwaretests"],"pt":["specsafe-complete","desenvolvimento de AI","test-driven development","validação de QA","CLI","desenvolvimento de software","técnicas de desenvolvimento de AI","ferramentas de desenvolvimento de AI","framework de desenvolvimento de AI"],"ru":["specsafe-complete","разработка ИИ","тестирование, управляемое разработкой","проверка QA","CLI","разработка программного обеспечения","техники разработки ИИ","инструменты разработки ИИ","рамка для разработки ИИ"],"ar":["specsafe-complete","تطوير الذكاء الاصطناعي","اختبار مدعوم بالتطوير","التحقق من جودة Guarantee","CLI","تطوير البرمجيات","تقنيات تطوير الذكاء الاصطناعي","أدوات تطوير الذكاء الاصطناعي","إطار عمل لتطوير الذكاء الاصطناعي"]}},"owner":"Agentic-Engineering-Agency","repo":"specsafe","repoPath":"Agentic-Engineering-Agency/specsafe","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"specsafe-complete","description":"Complete a SpecSafe specification. Moves spec from QA to COMPLETE stage.","version":"1.0","bodyPreview":"Complete a SpecSafe specification (QA → COMPLETE stage).\n\n**When to use:**\n- QA validation passed with GO recommendation\n- Ready to mark as production-ready\n- Finalizing the spec\n\n**Input**: The spec ID (e.g., SPEC-20240204-001)\n\n**Steps**\n\n1. **Validate QA passed**\n\n   Verify QA report shows GO recommendation.\n   Check that all critical issues are resolved.\n\n2. **Complete the spec**\n\n   ```bash\n   specsafe complete \"<spec-id>\"\n   ```\n\n   This:\n   - Moves spec to COMPLETE stage\n   - Moves spec f","body":"Complete a SpecSafe specification (QA → COMPLETE stage).\n\n**When to use:**\n- QA validation passed with GO recommendation\n- Ready to mark as production-ready\n- Finalizing the spec\n\n**Input**: The spec ID (e.g., SPEC-20240204-001)\n\n**Steps**\n\n1. **Validate QA passed**\n\n   Verify QA report shows GO recommendation.\n   Check that all critical issues are resolved.\n\n2. **Complete the spec**\n\n   ```bash\n   specsafe complete \"<spec-id>\"\n   ```\n\n   This:\n   - Moves spec to COMPLETE stage\n   - Moves spec file to `specs/completed/`\n   - Archives QA report\n   - Updates PROJECT_STATE.md\n\n3. **Show completion summary**\n\n   Display:\n   - Spec completion confirmation\n   - Metrics (time to complete, coverage, etc.)\n   - Location of completed spec\n   - Next steps\n\n**Output**\n\nAfter completion:\n- ✅ Completion confirmation\n- Spec moved to `specs/completed/`\n- PROJECT_STATE.md updated\n- Prompt: \"Ready to start a new spec? Run `specsafe new`\"\n\n**Guardrails**\n- Spec must be in QA stage\n- QA report must recommend GO\n- Do NOT complete if NO-GO\n- Confirm all requirements met"},"lastSynced":"2026-03-08T02:03:48.995Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents automating SpecSafe workflows with comprehensive content analysis and QA validation","zh":"适用于开发代理自动执行SpecSafe工作流，具有全面的内容分析和QA验证","ja":"SpecSafeワークフローを自動化する開発エージェントに適しています。包括的なコンテンツ分析とQA検証を提供します","ko":"SpecSafe 워크플로를 자동화하는 개발 에이전트에게 적합합니다. 포괄적인 컨텐츠 분석 및 QA 검증을 제공합니다","es":"Ideal para agentes de desarrollo que automatizan flujos de trabajo de SpecSafe con análisis de contenido integral y validación de QA","fr":"Idéal pour les agents de développement automatisant les workflows SpecSafe avec analyse de contenu complète et validation de QA","de":"Ideal für Entwicklungsmittel, die SpecSafe-Workflows mit umfassender Inhaltsanalyse und QA-Validierung automatisieren","pt":"Ideal para Agentes de Desenvolvimento que automatizam fluxos de trabalho do SpecSafe com análise de conteúdo abrangente e validação de QA","ru":"Идеально для агентов разработки, автоматизирующих рабочие процессы SpecSafe с полным анализом содержания и проверкой валидации QA","ar":"مثالي للوكلاء النموزجيين الذين يقومون بتشغيل عمليات SpecSafe مع تحليل المحتوى الشامل وتأكيد التحقق من جودة QA"},"recommendation":{"en":"Empowers agents to complete SpecSafe specifications, moving them to the COMPLETE stage via the specsafe complete command, after verifying QA reports show GO recommendations and all critical issues are resolved, utilizing SpecSafe''s COMPLETE stage functionality and QA validation protocols","zh":"赋予代理完成SpecSafe规格的能力，通过specsafe complete命令将其移动到COMPLETE阶段，在验证QA报告显示GO建议并解决所有关键问题之后，利用SpecSafe的COMPLETE阶段功能和QA验证协议","ja":"エージェントがSpecSafeの仕様を完了できるようにします。QAレポートがGOの提案を示し、すべての重要な問題が解決された後に、specsafe completeコマンドを使用してCOMPLETEステージに移動します。SpecSafeのCOMPLETEステージの機能とQA検証プロトコルを利用します","ko":"에이전트가 SpecSafe 사양을 완료할 수 있도록 합니다. QA 보고서가 GO 제안을 표시하고 모든 중요한 문제가 해결된 후에 specsafe complete 명령을 사용하여 COMPLETE 단계로 이동합니다. SpecSafe의 COMPLETE 단계 기능 및 QA 검증 프로토콜을 활용합니다","es":"Habilita a los agentes a completar especificaciones de SpecSafe, moviéndolas al estado COMPLETO a través del comando specsafe complete, después de verificar que los informes de QA muestren recomendaciones de GO y que todos los problemas críticos estén resueltos, utilizando la funcionalidad de la etapa COMPLETA de SpecSafe y los protocolos de validación de QA","fr":"Permet aux agents de compléter les spécifications SpecSafe, en les déplaçant vers l''étape COMPLETE via la commande specsafe complete, après vérification que les rapports de QA affichent des recommandations de GO et que tous les problèmes critiques sont résolus, en utilisant la fonctionnalité de l''étape COMPLETE de SpecSafe et les protocoles de validation de QA","de":"Ermöglicht es Agenten, SpecSafe-Spezifikationen zu vervollständigen und in den COMPLETE-Status zu versetzen, indem sie den specsafe complete-Befehl verwenden, nachdem sie die QA-Berichte überprüft haben, um sicherzustellen, dass GO-Empfehlungen angezeigt werden und alle kritischen Probleme behoben sind, unter Verwendung der COMPLETE-Stage-Funktionalität und der QA-Validierungsprotokolle von SpecSafe","pt":"Habilita os agentes a concluir especificações do SpecSafe, movendo-as para a etapa COMPLETE por meio do comando specsafe complete, após verificar relatórios de QA que mostram recomendações GO e todos os problemas críticos estejam resolvidos, utilizando a funcionalidade da etapa COMPLETE do SpecSafe e protocolos de validação de QA","ru":"Наделяет агентов возможностью завершить спецификации SpecSafe, переместив их на стадию COMPLETE с помощью команды specsafe complete, после проверки отчетов QA, показывающих рекомендации GO, и всех критических проблем, решенных с использованием функциональности стадии COMPLETE SpecSafe и протоколов проверки QA","ar":"يمكن للوكلاء إكمال مواصفات SpecSafe ، نقلها إلى مرحلة COMPLETE من خلال أمر specsafe complete ، بعد التحقق من تقارير جودة QA التي تظهر توصيات GO وجميع القضايا الحاسمة محلولة ، باستخدام وظيفة مرحلة COMPLETE من SpecSafe وبروتوكولات التحقق من جودة QA"},"useCases":{"en":["Automating spec finalization after QA validation","Moving specs to production-ready status","Completing SpecSafe specifications with verified QA reports"],"zh":["自动完成规格最终确定后的QA验证","将规格移动到生产就绪状态","使用经过验证的QA报告完成SpecSafe规格"],"ja":["QA検証後の仕様最終決定を自動化する","仕様を本稼働準備状態に移動する","検証済みのQAレポートを使用してSpecSafeの仕様を完了する"],"ko":["QA 검증 이후 사양 최종 확정을 자동화하는 것","사양을 生産 준비 상태로 이동하는 것","검증된 QA 보고서를 사용하여 SpecSafe 사양을 완료하는 것"],"es":["Automatización de la finalización de especificaciones después de la validación de QA","Movimiento de especificaciones al estado listo para la producción","Completar especificaciones de SpecSafe con informes de QA verificados"],"fr":["Automatisation de la finalisation des spécifications après validation de QA","Déplacement des spécifications vers le statut prêt pour la production","Complétion des spécifications SpecSafe avec des rapports de QA vérifiés"],"de":["Automatisierung der Spezifikationsfinalisierung nach QA-Validierung","Versetzen von Spezifikationen in den produktionsbereiten Status","Vervollständigen von SpecSafe-Spezifikationen mit verifizierten QA-Berichten"],"pt":["Automatizar a finalização da especificação após validação de QA","Mover especificações para status pronto para produção","Concluir especificações do SpecSafe com relatórios de QA verificados"],"ru":["Автоматизировать окончательное оформление спецификации после проверки валидации QA","Переместить спецификации в статус готовности к производству","Завершить спецификации SpecSafe с проверенными отчетами QA"],"ar":["التشغيل الآلي لإنهاء المواصفة بعد التحقق من جودة QA","نقل المواصفات إلى حالة جاهزية للإنتاج","إكمال مواصفات SpecSafe مع تقارير جودة QA المحققة"]},"limitations":{"en":["Requires spec ID as input","Depends on SpecSafe''s complete command functionality","Limited to SpecSafe specifications"],"zh":["需要规格ID作为输入","依赖于SpecSafe的complete命令功能","仅限于SpecSafe规格"],"ja":["仕様IDを入力として必要とする","SpecSafeのcompleteコマンドの機能に依存する","SpecSafeの仕様のみに限定される"],"ko":["사양 ID를 입력으로 필요로 함","SpecSafe의 complete 명령 기능에 의존함","SpecSafe 사양에만 제한됨"],"es":["Requiere la ID de especificación como entrada","Depende de la funcionalidad del comando complete de SpecSafe","Limitado a especificaciones de SpecSafe"],"fr":["Exige l''ID de spécification comme entrée","Dépend de la fonctionnalité de la commande complete de SpecSafe","Limité aux spécifications SpecSafe"],"de":["Benötigt die Spezifikations-ID als Eingabe","Hängt von der Funktionalität des specsafe complete-Befehls ab","Begrenzt auf SpecSafe-Spezifikationen"],"pt":["Exige ID de especificação como entrada","Depende da funcionalidade do comando complete do SpecSafe","Limitado a especificações do SpecSafe"],"ru":["Требует ID спецификации в качестве входных данных","Зависит от функциональности команды complete SpecSafe","Ограничен спецификациями SpecSafe"],"ar":["يتطلب معرف المواصفة كمدخل","يعتمد على وظيفة أمر SpecSafe الكامل","محدود بمواصفات SpecSafe"]},"version":4},"contentHash":"8ac32d13858208bb25a7383275f8dc402f0dea5a7bca808944601cbad20e4a8c","qualityScore":41}');
