INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Agentic-Engineering-Agency/specsafe/specsafe-complete', 'specsafe-complete', 'Agentic-Engineering-Agency', 'specsafe', 'community', 'specsafe-complete Agentic-Engineering-Agency specsafe community The specsafe-complete skill completes a SpecSafe specification, moving it to the COMPLETE stage. It benefits developers by automating the finalization of specs after QA validation. SpecSafe Complete 是一个测试驱动开发框架，用于 AI 辅助开发。它可以完成规格验证并将规格标记为生产就绪 SpecSafe Complete は、AI エージェントを使用した開発のためのテスト駆動開発フレームワークです。規格を完了し、生産就緒とすることができます SpecSafe Complete는 AI 에이전트를 사용한 개발을 위한 테스트 주도 개발 프레임워크입니다. 규격을 완료하고 생산 준비를 표시할 수 있습니다 specsafe-complete es un marco de desarrollo de AI que permite a los desarrolladores finalizar especificaciones de manera eficiente. Utiliza comandos como ''specsafe complete'' para mover las especificaciones al estado de completado. specsafe-complete est un cadre de développement d''agents d''IA qui permet aux développeurs de terminer les spécifications de manière efficace. Il utilise des commandes comme ''specsafe complete'' pour déplacer les spécifications à l''état terminé. specsafe-complete ist ein Rahmenwerk für die AI-Entwicklung, das es Entwicklern ermöglicht, Spezifikationen effizient abzuschließen. Es verwendet Befehle wie ''specsafe complete'', um die Spezifikationen in den abgeschlossenen Status zu versetzen. O specsafe-complete é um framework de Test-Driven Development para desenvolvimento de AI assistido, permitindo a validação de QA e a finalização de especificações Specsafe-complete - это рамка для тестирования, управляемого разработкой, для разработки приложений ИИ, обеспечивающая проверку QA и завершение спецификаций specsafe-complete هو إطار عمل لتطوير الذكاء الاصطناعي مدعوم بالاختبار، يسمح بالتحقق من جودة Guarantee وإتمام المواصفات how to use specsafe-complete specsafe-complete setup guide specsafe-complete alternative specsafe-complete vs test-driven development specsafe-complete install what is specsafe-complete specsafe-complete tutorial specsafe-complete best practices specsafe-complete for AI agents SpecSafe Complete AI 工具 测试驱动开发 规格验证 生产就绪 CLI 命令 AI 辅助开发 软件开发 Validates QA passed with GO recommendation Resolves all critical issues before completion Uses the `specsafe complete` command to move spec to COMPLETE stage Moves spec to production-ready stage after completion Takes spec ID as input (e.g., SPEC-20240204-001) Automates the finalization of specs after QA validation specsafe-complete is a Test-Driven Development framework for AI assisted development that completes a SpecSafe specification, marking it as production-ready.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('grimmolf/mga-soap-calculator/Global Truth Safety', 'community', 'grimmolf', 'mga-soap-calculator', 'grimmolf/mga-soap-calculator', 'Global Truth Safety', 0, 0, 41, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:57.121Z', '2dca6cc7f9d742ba4f95cc2f00a763302b03ae59b23002d7f4783f3450ac3b77', '{"id":"grimmolf/mga-soap-calculator/Global Truth Safety","name":"Global Truth Safety","description":{"en":"Global Truth Safety is a soap calculator for Midnight Garden Apothecary, enabling developers to make technical assertions and link them to logs, test output, benchmarks, or specs. It benefits developers delivering code, tests, or operational changes.","zh":"Global Truth Safety 是一个 Soap 计算器，用于 Midnight Garden Apothecary 的自定义添加剂质量影响计算","ja":"Global Truth Safety は、Midnight Garden Apothecary 用のカスタム添加剤品質影響計算のための Soap 計算器です","ko":"Global Truth Safety 는 Midnight Garden Apothecary 를 위한 맞춤형 첨가제 품질 영향 계산용 Soap 계산기입니다","es":"Global Truth Safety es una habilidad que calcula la calidad de los aditivos en la Apothecary de Midnight Garden. Proporciona cálculos personalizados de impacto de calidad","fr":"Global Truth Safety est une compétence qui calcule la qualité des additifs dans l''Apothecary de Midnight Garden. Elle fournit des calculs personnalisés d''impact de qualité","de":"Global Truth Safety ist eine Fähigkeit, die die Qualität von Additiven in der Apotheke von Midnight Garden berechnet. Sie bietet benutzerdefinierte Berechnungen des Qualitätsimpacts","pt":"O Global Truth Safety é uma ferramenta para garantir a qualidade e segurança dos códigos e operações, com recursos de cálculo de impacto de aditivos personalizados","ru":"Global Truth Safety - это инструмент для обеспечения качества и безопасности кода и операций, с функциями расчета влияния пользовательских добавок","ar":"أداة Global Truth Safety هي أداة لضمان جودة وأما