INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('grimmolf/mga-soap-calculator/Global Truth Safety', 'Global Truth Safety', 'grimmolf', 'mga-soap-calculator', 'community', 'Global Truth Safety grimmolf mga-soap-calculator community Global Truth Safety is a soap calculator for Midnight Garden Apothecary, enabling developers to make technical assertions and link them to logs, test output, benchmarks, or specs. It benefits developers delivering code, tests, or operational changes. Global Truth Safety 是一个 Soap 计算器，用于 Midnight Garden Apothecary 的自定义添加剂质量影响计算 Global Truth Safety は、Midnight Garden Apothecary 用のカスタム添加剤品質影響計算のための Soap 計算器です Global Truth Safety 는 Midnight Garden Apothecary 를 위한 맞춤형 첨가제 품질 영향 계산용 Soap 계산기입니다 Global Truth Safety es una habilidad que calcula la calidad de los aditivos en la Apothecary de Midnight Garden. Proporciona cálculos personalizados de impacto de calidad Global Truth Safety est une compétence qui calcule la qualité des additifs dans l''Apothecary de Midnight Garden. Elle fournit des calculs personnalisés d''impact de qualité Global Truth Safety ist eine Fähigkeit, die die Qualität von Additiven in der Apotheke von Midnight Garden berechnet. Sie bietet benutzerdefinierte Berechnungen des Qualitätsimpacts O Global Truth Safety é uma ferramenta para garantir a qualidade e segurança dos códigos e operações, com recursos de cálculo de impacto de aditivos personalizados Global Truth Safety - это инструмент для обеспечения качества и безопасности кода и операций, с функциями расчета влияния пользовательских добавок أداة Global Truth Safety هي أداة لضمان جودة وأمان الشفرات والعمليات، مع خيارات لحساب تأثير الإضافات المخصصة how to use Global Truth Safety what is Global Truth Safety Global Truth Safety alternative Global Truth Safety vs soap calculators Global Truth Safety install guide Global Truth Safety setup for Midnight Garden Apothecary custom additive quality impact calculations ensuring real code deliveries linking technical assertions to logs AI エージェント 代码真实性 安全性保证 Soap 计算器 自定义添加剂 质量影响计算 实时测试 技术断言 Ensures real, running, and verified code deliveries Surfaces blockers, regressions, risks, or problems immediately upon discovery Makes technical assertions and links them to logs, test output, benchmarks, or specs Discovers missing test coverage, flaky tests, or undocumented behavior Supports custom additive quality impact calculations for soap recipes Global Truth Safety is a skill that ensures real, running, and verified code deliveries and system behavior observations through custom additive quality impact calculations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bartstc/vite-ts-react-template/commit-work', 'community', 'bartstc', 'vite-ts-react-template', 'bartstc/vite-ts-react-template', 'commit-work', 0, 0, 41, '2026-03-08T01:57:15.327Z', '2026-03-08T02:04:15.203Z', '369786c13587086f6d052256a9fd4a1cdcb4173952b5bc9ce15afce9f0aeb00a', '{"id":"bartstc/vite-ts-react-template/commit-work","name":"commit-work","description":{"en":"The commit-work skill provides a basic dev setup for Single Page Application development, including key tools and settings for seamless DX. It helps developers make commits that are easy to review and safe to ship.","zh":"Commit Work 提供基本的开发设置，用于单页应用开发，包含关键工具和设置以实现无缝开发体验","ja":"Commit Work は、シングルページアプリケーション開発用の基本的な開発設定を提供し、主要なツールと設定を含むことで無駄のない開発体験を実現します","ko":"Commit Work는 싱글 페이지 애플리케이션 개발을 위한 기본 개발 설정을 제공하며 주요 도구 및 설정을 포함하여 무결점 개발 경험을 제공합니다","es":"Commit Work proporciona una configuración de desarrollo básica para aplicaciones de página única con herramientas clave y demostraciones de buenas prácticas","fr":"Commit Work fournit une configuration de développement de base pour les applications à page unique avec des outils clés et des démonstrations de bonnes pratiques","de":"Commit Work bietet eine grundlegende Entwicklungssetup für Single-Page-Anwendungen mit wichtigen Tools und Demonstrationen von Best Practices","pt":"O commit work é um projeto que fornece uma configuração básica de desenvolvimento para SPA, incluindo ferramentas e práticas recomendadas","ru":"Commit work - это проект, предоставляющий базовую конфигурацию разработки для одностраничных приложений, включая рекомендованные инструменты и практики","ar":"أداة Commit Work هي مشروع يوفر إعدادًا أساسيًا للتنمية للتطبيقات ذات الصفحة الواحدة، بما في ذلك الأدوات والممارسات الموصى بها"},"seo":{"title":{"en":"commit-work: Best Practices Setup Guide for AI Agents","zh":"Commit Work 设置指南：优化代码提交和审查","ja":"Commit Work セットアップガイド：コードレビューの効率化 - AIエージェント","ko":"Commit Work 설정 가이드: 코드 제출과 검토 최적화","es":"Configuración de Commit Work: Guía de Mejores Prácticas p...","fr":"Guide de Configuration de Commit Work : Bonnes Pratiques ...","de":"Commit Work-Setup: Leitfaden für Entwickler mit Conventio...","pt":"Guia de Configuração do Commit Work para Desenvolvimento ...","ru":"ИИ Агенты: Настройка Commit Work для Разработки Одностран...","ar":"إعداد أداة Commit Work لتنمية التطبيقات ذات الصفحة الواحدة"},"description":{"en":"Discover how to make commits easy to review and safe to ship with commit-work. Learn the workflow and checklist for seamless DX and good practices.","zh":"使用 Commit Work 设置指南，优化代码提交和审查流程，提高开发团队的效率","ja":"Commit Work を使用してコードレビューの効率を向上させ、開発チームの生産性を高める - AIエージェント","ko":"Commit Work 설정 가이드를 사용하여 코드 제출과 검토를 최적화하고 개발 팀의 효율성을 높여보세요","es":"Aprende a configurar Commit Work para desarrollar aplicaciones de página única con herramientas clave y mejores prácticas para una experiencia de desarrollo ...","fr":"Découvrez comment configurer Commit Work pour développer des applications à page unique avec des outils clés et des meilleures pratiques pour une expérience ...","de":"Erfahren Sie, wie Sie Commit Work für die Entwicklung von Single-Page-Anwendungen mit wichtigen Tools und Best Practices für eine optimale Entwicklererfahrun...","pt":"Aprenda a configurar o commit work para desenvolvimento de SPA com ferramentas e práticas recomendadas","ru":"Узнайте, как настроить commit work для разработки одностраничных приложений с помощью рекомендованных инструментов и практик","ar":"تعرف على كيفية إعداد أداة Commit Work لتنمية التطبيقات ذات الصفحة الواحدة باستخدام الأدوات والممارسات الموصى بها"},"definition":{"en":"commit-work is a project that provides a basic dev setup for Single Page Application development, focusing on good practices and tooling for easy and safe commits.","zh":"Commit Work 是一种开发工具，帮助开发者提交高质量的代码并优化代码审查流程","ja":"Commit Work は、開発者が高品質のコードを提出し、コードレビューのプロセスを最適化するのを助ける開発ツールです","ko":"Commit Work는 개발자가 고품질의 코드를 제출하고 코드 검토 프로세스를 최적화하는 것을 도와주는 개발 도구입니다","es":"Commit Work es una herramienta de desarrollo que ayuda a los desarrolladores a crear commits seguros y fáciles de revisar","fr":"Commit Work est un outil de développement qui aide les développeurs à créer des commits sûrs et faciles à revoir","de":"Commit Work ist ein Entwicklertools, das Entwicklern hilft, sichere und leicht überprüfbare Commits zu erstellen","pt":"O que é commit work? É um projeto que fornece uma configuração básica de desenvolvimento para SPA","ru":"Что такое commit work? Это проект, предоставляющий базовую конфигурацию разработки для одностраничных приложений","ar":"ما هي أداة Commit Work؟ هي مشروع يوفر إعدادًا أساسيًا للتنمية للتطبيقات ذات الصفحة الواحدة"},"features":{"en":["Supports Conventional Commits for standardized commit messages","Includes a workflow checklist for logically scoped commits","Allows for multiple small commits when there are unrelated changes","Enforces rules such as max subject length and required scopes","Provides a demo app presenting good practices and used tooling in action","Includes settings for seamless Developer Experience (DX)"],"zh":["支持 Conventional Commits","提供单提交或多提交选项","包含提交风格和规则设置","优化代码审查流程","提高开发团队的效率"],"ja":["Conventional Commits をサポート","単一コミットまたは複数コミットオプションを提供","コミットスタイルとルール設定を含む","コードレビューのプロセスを最適化","開発チームの生産性を高める"],"ko":["Conventional Commits 지원","단일 제출 또는 다중 제출 옵션 제공","제출 스타일 및 규칙 설정 포함","코드 검토 프로세스 최적화","개발 팀의 효율성을 높임"],"es":["Configuración de desarrollo básica para aplicaciones de página única","Herramientas clave para una experiencia de desarrollo óptima","Demostraciones de buenas prácticas para commits seguros y fáciles de revisar","Soporte para Conventional Commits","Opción para commits individuales o múltiples"],"fr":["Configuration de développement de base pour les applications à page unique","Outils clés pour une expérience de développement optimale","Démonstrations de bonnes pratiques pour des commits sûrs et faciles à revoir","Prise en charge de Conventional Commits","Option pour des commits individuels ou multiples"],"de":["Grundlegende Entwicklungssetup für Single-Page-Anwendungen","Wichtige Tools für eine optimale Entwicklererfahrung","Demonstrationen von Best Practices für sichere und leicht überprüfbare Commits","Unterstützung für Conventional Commits","Option für einzelne oder multiple Commits"],"pt":["Ferramentas para desenvolvimento de SPA","Configuração para experiência de desenvolvimento sem interrupções","Aplicativo demo que apresenta boas práticas e ferramentas em ação","Commits lógicos e seguros","Mensagens de commit que descrevem as alterações e os motivos"],"ru":["Инструменты для разработки одностраничных приложений","Настройка для бесперебойного опыта разработки","Демо-приложение, демонстрирующее хорошие практики и инструменты в действии","Логические и безопасные коммиты","Сообщения коммитов, описывающие изменения и причины"],"ar":["أدوات لتنمية التطبيقات ذات الصفحة الواحدة","إعداد للخبرة التنموية دون انقطاع","تطبيق تجريبي يظهر الممارسات الجيدة والأدوات في العمل","التزامات منطقية وآمنة","رسائل الالتزام التي تصف التغييرات والأسباب"]},"keywords":{"en":["how to use commit-work","commit-work setup guide","commit-work alternative","commit-work vs git flow","what is commit-work","commit-work install","commit-work best practices","commit-work for AI agents","commit-work workflow","commit-work checklist"],"zh":["Commit Work","代码提交","代码审查","Conventional Commits","开发工具","代码质量","开发效率","AI开发工具"],"ja":["Commit Work","コードレビュー","Conventional Commits","開発ツール","コード品質","開発効率","AI開発ツール","エージェント"],"ko":["Commit Work","코드 제출","코드 검토","Conventional Commits","개발 도구","코드 품질","개발 효율","AI 개발 도구","에이전트"],"es":["Commit Work","desarrollo de aplicaciones de página única","Conventional Commits","herramientas de desarrollo","mejores prácticas para commits","configuración de desarrollo","experiencia de desarrollo óptima","desarrollo de software"],"fr":["Commit Work","développement d''applications à page unique","Conventional Commits","outils de développement","bonnes pratiques pour les commits","configuration de développement","expérience de développement optimale","développement de logiciels"],"de":["Commit Work","Entwicklung von Single-Page-Anwendungen","Conventional Commits","Entwicklertools","Best Practices für Commits","Entwicklungssetup","optimale Entwicklererfahrung","Softwareentwicklung"],"pt":["commit work","desenvolvimento de spa","ferramentas de desenvolvimento","configuração de desenvolvimento","boas práticas de desenvolvimento","commits lógicos","mensagens de commit"],"ru":["commit work","разработка одностраничных приложений","инструменты разработки","настройка разработки","хорошие практики разработки","логические коммиты","сообщения коммитов"],"ar":["أداة Commit Work","تنمية التطبيقات ذات الصفحة الواحدة","أدوات التنمية","إعداد التنمية","الممارسات الجيدة للتنمية","التزامات منطقية","رسائل الالتزام"]}},"owner":"bartstc","repo":"vite-ts-react-template","repoPath":"bartstc/vite-ts-react-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.327Z","topics":[],"category":"community","skillMd":{"name":"commit-work","description":"Create high-quality git commits: review/stage intended changes, split into logical commits, and write clear commit messages (including Conventional Commits). Use when the user asks to commit, craft a commit message, stage changes, or split work into multiple commits.","bodyPreview":"# Commit work\n\n## Goal\n\nMake commits that are easy to review and safe to ship:\n\n- only intended changes are included\n- commits are logically scoped (split when needed)\n- commit messages describe what changed and why\n\n## Inputs to ask for (if missing)\n\n- Single commit or multiple commits? (If unsure: default to multiple small commits when there are unrelated changes.)\n- Commit style: Conventional Commits are required.\n- Any rules: max subject length, required scopes.\n\n## Workflow (checklist)\n\n1.","body":"# Commit work\n\n## Goal\n\nMake commits that are easy to review and safe to ship:\n\n- only intended changes are included\n- commits are logically scoped (split when needed)\n- commit messages describe what changed and why\n\n## Inputs to ask for (if missing)\n\n- Single commit or multiple commits? (If unsure: default to multiple small commits when there are unrelated changes.)\n- Commit style: Conventional Commits are required.\n- Any rules: max subject length, required scopes.\n\n## Workflow (checklist)\n\n1. Inspect the working tree before staging\n   - `git status`\n   - `git diff` (unstaged)\n   - If many changes: `git diff --stat`\n2. Decide commit boundaries (split if needed)\n   - Split by: feature vs refactor, backend vs frontend, formatting vs logic, tests vs prod code, dependency bumps vs behavior changes.\n   - If changes are mixed in one file, plan to use patch staging.\n3. Stage only what belongs in the next commit\n   - Prefer patch staging for mixed changes: `git add -p`\n   - To unstage a hunk/file: `git restore --staged -p` or `git restore --staged <path>`\n4. Review what will actually be committed\n   - `git diff --cached`\n   - Sanity checks:\n     - no secrets or tokens\n     - no accidental debug logging\n     - no unrelated formatting churn\n5. Describe the staged change in 1-2 sentences (before writing the message)\n   - \"What changed?\" + \"Why?\"\n   - If you cannot describe it cleanly, the commit is probably too big or mixed; go back to step 2.\n6. Write the commit message\n   - Use Conventional Commits (required):\n     - `type(scope): short summary`\n     - blank line\n     - body (what/why, not implementation diary)\n     - footer (BREAKING CHANGE) if needed\n   - Prefer an editor for multi-line messages: `git commit -v`\n   - Use `references/commit-message-template.md` if helpful.\n7. Run the smallest relevant verification\n   - Run the repo''s fastest meaningful check (unit tests, lint, or build) before moving on.\n8. Repeat for the next commit until the working tree is clean\n\n## Deliverable\n\nProvide:\n\n- the final commit message(s)\n- a short summary per commit (what/why)\n- the commands used to stage/review (at minimum: `git diff --cached`, plus any tests run)\n"},"lastSynced":"2026-03-08T02:04:15.203Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents requiring standardized commit practices and Conventional Commits","zh":"适用于需要标准化提交实践和遵循Conventional Commits的版本控制代理","ja":"Conventional Commitsに従った標準的なコミット慣行を必要とするバージョン管理エージェントに最適","ko":"표준화된 커밋 관행과 Conventional Commits를 필요로 하는 버전 관리 에이전트에 적합","es":"Ideal para Agentes de Control de Versiones que requieren prácticas de compromiso estandarizadas y Commits Convencionales","fr":"Idéal pour les agents de contrôle de version nécessitant des pratiques de validation standardisées et des Commits Conventionnels","de":"Ideal für Version Control Agents, die standardisierte Commit-Praktiken und Conventional Commits erfordern","pt":"Ideal para Agentes de Controle de Versão que requerem práticas de commit padronizadas e Commits Convencionais","ru":"Идеально для агентов контроля версий, требующих стандартизированных практик коммитов и Конвенциональных коммитов","ar":"مثالي لعمليات التحكم في الإصدار التي تتطلب ممارسات الإيداع الموحدة والالتزامات التقليدية"},"recommendation":{"en":"Empowers agents to create logically scoped commits with descriptive messages, ensuring seamless code reviews and safe deployments using Conventional Commits and adhering to specific commit styles and rules","zh":"赋予代理创建逻辑作用域的提交和描述性消息的能力，确保无缝的代码审查和安全的部署，使用Conventional Commits并遵循特定的提交样式和规则","ja":"エージェントが論理的にスコープされたコミットと記述的メッセージを作成できるようにし、Conventional Commitsと特定のコミットスタイルとルールに従って、無停止のコードレビューと安全なデプロイを可能にする","ko":"에이전트가 논리적으로 범위가 지정된 커밋과 설명 메시지를 생성할 수 있도록 하여 Conventional Commits와 특정 커밋 스타일 및 규칙을 준수하면서 무중단 코드 리뷰 및 안전한 배포를 보장","es":"Habilita a los agentes a crear commits con ámbito lógico y mensajes descriptivos, lo que garantiza revisiones de código sin problemas y despliegues seguros utilizando Commits Convencionales y ajustándose a estilos y reglas de compromiso específicos","fr":"Permet aux agents de créer des commits à portée logique avec des messages descriptifs, garantissant ainsi des examens de code sans heurts et des déploiements sûrs à l''aide de Commits Conventionnels et en respectant des styles et des règles de validation spécifiques","de":"Ermächtigt Agenten, logisch umfangreiche Commits mit beschreibenden Nachrichten zu erstellen, was nahtlose Code-Reviews und sichere Deployments unter Verwendung von Conventional Commits und unter Einhaltung spezifischer Commit-Stile und -Regeln gewährleistet","pt":"Habilita os agentes a criar commits com escopos lógicos e mensagens descritivas, garantindo revisões de código sem problemas e implantações seguras usando Commits Convencionais e seguindo estilos e regras de commit específicos","ru":"Наделяет агентов возможностью создавать логически упорядоченные коммиты с описательными сообщениями, обеспечивая беспроблемные обзоры кода и безопасные развертывания с использованием Конвенциональных коммитов и соблюдением определенных стилей и правил коммитов","ar":"يمكّن الوكلاء من إنشاء التزامات مدروسة مع رسائل وصفية، مما يضمن مراجعات التعليمات البرمجية بدون مشاكل والتركيبات الآمنة باستخدام الالتزامات التقليدية والامتثال لأسلوب التزام محدد وقواعده"},"useCases":{"en":["Automating commit message generation","Validating commit scopes and sizes","Standardizing commit history for easier reviews"],"zh":["自动生成提交消息","验证提交范围和大小","标准化提交历史以便于审查"],"ja":["コミットメッセージの自動生成","コミットのスコープとサイズの検証","コードレビューの容易化のためのコミット履歴の標準化"],"ko":["커밋 메시지 자동 생성","커밋 범위 및 크기 검증","코드 리뷰를 쉽게 하기 위한 커밋 기록 표준화"],"es":["Automatización de la generación de mensajes de compromiso","Validación de ámbitos y tamaños de compromiso","Estandarización del historial de compromiso para revisiones más fáciles"],"fr":["Automatisation de la génération de messages de validation","Validation des portées et des tailles de validation","Standardisation de l''historique de validation pour des examens plus faciles"],"de":["Automatisierung der Commit-Nachrichtengenerierung","Validierung von Commit-Umfängen und -Größen","Standardisierung der Commit-Historie für einfachere Überprüfungen"],"pt":["Automatizar a geração de mensagens de commit","Validar escopos e tamanhos de commit","Padronizar o histórico de commit para revisões mais fáceis"],"ru":["Автоматизировать генерацию сообщений коммита","Проверять области и размеры коммита","Стандартизировать историю коммитов для более легких обзоров"],"ar":["تأتمتة إنشاء رسائل الإيداع","تحقق من نطاقات وأحجام الإيداع","توحيد تاريخ الإيداع لمراجعات أسهل"]},"limitations":{"en":["Requires adherence to Conventional Commits format","May require additional setup for custom commit rules and styles"],"zh":["需要遵循Conventional Commits格式","可能需要额外的设置以满足自定义提交规则和样式"],"ja":["Conventional Commits形式に従う必要がある","カスタムコミットルールとスタイルに対応するために追加の設定が必要になる可能性がある"],"ko":["Conventional Commits 형식을 따라야 함","사용자 정의 커밋 규칙 및 스타일을满足하기 위해 추가 설정이 필요할 수 있음"],"es":["Requiere adherencia al formato de Commits Convencionales","Puede requerir configuración adicional para reglas y estilos de compromiso personalizados"],"fr":["Nécessite l''adhésion au format des Commits Conventionnels","Peut nécessiter une configuration supplémentaire pour des règles et des styles de validation personnalisés"],"de":["Erfordert Einhaltung des Conventional Commits-Formats","Kann zusätzliche Einrichtung für benutzerdefinierte Commit-Regeln und -Stile erfordern"],"pt":["Exige aderência ao formato de Commits Convencionais","Pode exigir configuração adicional para regras e estilos de commit personalizados"],"ru":["Требует соблюдения формата Конвенциональных коммитов","Может потребовать дополнительной настройки для пользовательских правил и стилей коммитов"],"ar":["يتطلب الالتزام bằng تنسيق الالتزامات التقليدية","قد يتطلب إعدادًا إضافيًا لقواعد وأساليب الإيداع المخصصة"]},"version":4},"contentHash":"369786c13587086f6d052256a9fd4a1cdcb4173952b5bc9ce15afce9f0aeb00a","qualityScore":41}');
