INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bartstc/vite-ts-react-template/commit-work', 'commit-work', 'bartstc', 'vite-ts-react-template', 'community', 'commit-work bartstc vite-ts-react-template community The commit-work skill provides a basic dev setup for Single Page Application development, including key tools and settings for seamless DX. It helps developers make commits that are easy to review and safe to ship. Commit Work 提供基本的开发设置，用于单页应用开发，包含关键工具和设置以实现无缝开发体验 Commit Work は、シングルページアプリケーション開発用の基本的な開発設定を提供し、主要なツールと設定を含むことで無駄のない開発体験を実現します Commit Work는 싱글 페이지 애플리케이션 개발을 위한 기본 개발 설정을 제공하며 주요 도구 및 설정을 포함하여 무결점 개발 경험을 제공합니다 Commit Work proporciona una configuración de desarrollo básica para aplicaciones de página única con herramientas clave y demostraciones de buenas prácticas Commit Work fournit une configuration de développement de base pour les applications à page unique avec des outils clés et des démonstrations de bonnes pratiques Commit Work bietet eine grundlegende Entwicklungssetup für Single-Page-Anwendungen mit wichtigen Tools und Demonstrationen von Best Practices O commit work é um projeto que fornece uma configuração básica de desenvolvimento para SPA, incluindo ferramentas e práticas recomendadas Commit work - это проект, предоставляющий базовую конфигурацию разработки для одностраничных приложений, включая рекомендованные инструменты и практики أداة Commit Work هي مشروع يوفر إعدادًا أساسيًا للتنمية للتطبيقات ذات الصفحة الواحدة، بما في ذلك الأدوات والممارسات الموصى بها how to use commit-work commit-work setup guide commit-work alternative commit-work vs git flow what is commit-work commit-work install commit-work best practices commit-work for AI agents commit-work workflow commit-work checklist Commit Work 代码提交 代码审查 Conventional Commits 开发工具 代码质量 开发效率 AI开发工具 Supports Conventional Commits for standardized commit messages Includes a workflow checklist for logically scoped commits Allows for multiple small commits when there are unrelated changes Enforces rules such as max subject length and required scopes Provides a demo app presenting good practices and used tooling in action Includes settings for seamless Developer Experience (DX) commit-work is a project that provides a basic dev setup for Single Page Application development, focusing on good practices and tooling for easy and safe commits.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jibaxZZZ/codex-root-configuration/explore-docs', 'community', 'jibaxZZZ', 'codex-root-configuration', 'jibaxZZZ/codex-root-configuration', 'explore-docs', 0, 0, 41, '2026-03-08T01:57:15.378Z', '2026-03-08T02:05:26.453Z', 'f49691727a8214a761184b836711a9fcdd5629028880ff0fb262dd04cb1e05e1', '{"id":"jibaxZZZ/codex-root-configuration/explore-docs","name":"explore-docs","description":{"en":"The explore-docs skill helps developers access library details and documentation. It benefits those working with specific library/framework usage details.","zh":"explore-docs技能提供快速查阅库和框架的详细信息，包括API、示例和配置","ja":"explore-docsスキルは、ライブラリとフレームワークの詳細情報、API、例、構成を素早く検索する機能を提供","ko":"explore-docs 스킬은 라이브러리 및 프레임워크의詳細 정보, API, 예시 및 구성 등을 신속하게 조회하는 기능을 제공합니다.","es":"Explore-docs es una habilidad que proporciona detalles de bibliotecas y frameworks, incluyendo ejemplos de código y referencias de API. Utiliza Context7 y web.run para obtener documentación oficial.","fr":"Explore-docs est une compétence qui fournit des détails sur les bibliothèques et les frameworks, y compris des exemples de code et des références d''API. Utilise Context7 et web.run pour obtenir la documentation officielle.","de":"Explore-docs ist eine Fähigkeit, die Details zu Bibliotheken und Frameworks bereitstellt, einschließlich Codebeispielen und API-Referenzen. Verwendet Context7 und web.run, um offizielle Dokumentationen zu erhalten.","pt":"O explore-docs é uma habilidade que fornece detalhes de uso de bibliotecas e frameworks, incluindo APIs, exemplos e configurações. É útil quando a tarefa depende de detalhes de uso de bibliotecas.","ru":"Explore-docs - это навык, который предоставляет информацию о библиотеках и фреймворках, включая API, примеры и конфигурации. Он полезен, когда задача зависит от деталей использования библиотек.","ar":"explore-docs هو مهارة يوفر تفاصيل استخدام المكتبات والإطارات، بما في ذلك واجهات برمجة التطبيقات وأمثلة وضبطات. وهو مفيد عندما تعتمد المهمة على تفاصيل استخدام المكتبات"},"seo":{"title":{"en":"explore-docs: API Documentation Setup Guide | AI Agent Skill","zh":"探索文档：AI工具快速查阅库框架详细信息","ja":"ドキュメントの探索：AIエージェントによるライブラリ/フレームワーク詳細の検索","ko":"문서 탐색: AI 에이전트를 사용한 라이브러리/프레임워크 세부 정보 조회","es":"Guía de configuración para explorar documentación de bibl...","fr":"Guide d''exploration de documentation de bibliothèques ave...","de":"Setup-Leitfaden für die Erforschung von Bibliotheks-Dokum...","pt":"Guia de Configuração do explore-docs: Navegando Documenta...","ru":"ИИ Агенты: Руководство по Настройке explore-docs для Изуч...","ar":"دليل إعداد explore-docs: استكشاف وثائق المكتبات البرمجية"},"description":{"en":"Unlock library details with explore-docs. Discover how to fetch targeted docs, extract APIs, and configure your project with ease. Get started now!","zh":"使用explore-docs技能，快速获取库和框架的详细信息，包括API、示例和配置","ja":"explore-docsスキルを使用して、ライブラリとフレームワークの詳細情報、API、例、構成を素早く取得","ko":"explore-docs 스킬을 사용하여 라이브러리 및 프레임워크의詳細 정보, API, 예시 및 구성 등을 신속하게 가져옵니다.","es":"Descubre cómo utilizar explore-docs para obtener detalles de bibliotecas y frameworks, incluyendo ejemplos de código y referencias de API","fr":"Découvrez comment utiliser explore-docs pour obtenir des détails sur les bibliothèques et les frameworks, y compris des exemples de code et des références d''API","de":"Erfahren Sie, wie Sie explore-docs verwenden, um Details zu Bibliotheken und Frameworks zu erhalten, einschließlich Codebeispielen und API-Referenzen","pt":"Aprenda a configurar o explore-docs para obter detalhes de uso de bibliotecas e frameworks, incluindo APIs, exemplos e configurações.","ru":"Узнайте, как настроить explore-docs для получения информации о библиотеках и фреймворках, включая API, примеры и конфигурации.","ar":"تعلم كيفية إعداد explore-docs للحصول على تفاصيل استخدام المكتبات والإطارات، بما في ذلك واجهات برمجة التطبيقات وأمثلة وضبطات"},"defini