INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flet-dev/flet/implement-flet-extension', 'implement-flet-extension', 'flet-dev', 'flet', 'community', 'implement-flet-extension flet-dev flet community The implement-flet-extension skill enables developers to build real-time web, mobile, and desktop apps in Python, using Flet and external Flutter packages. It benefits developers without frontend experience. Flet 扩展允许开发人员使用 Python 构建实时 Web、移动和桌面应用，无需前端经验 Flet 拡張を使用すると、開発者は Python を使用してリアルタイム Web、モバイル、デスクトップ アプリを構築できます。前端の経験は必要ありません Flet 확장을 사용하면 개발자가 Python을 사용하여 실시간 웹, 모바일, 데스크톱 앱을 빌드할 수 있습니다. 프론트엔드 경험은 필요하지 않습니다 La extensión Flet permite a los desarrolladores crear aplicaciones web, móviles y de escritorio en tiempo real con Python, sin necesidad de experiencia en frontend. L''extension Flet permet aux développeurs de créer des applications web, mobiles et de bureau en temps réel avec Python, sans nécessité d''expérience en frontend. Die Flet-Erweiterung ermöglicht es Entwicklern, Echtzeit-Web-, Mobile- und Desktop-Anwendungen mit Python zu erstellen, ohne dass Frontend-Erfahrung erforderlich ist. O Flet-Extension permite que desenvolvedores criem aplicações em Python sem experiência em frontend. Aprenda a implementá-lo Flet-Extension позволяет разработчикам создавать приложения на Python без опыта в frontend. Узнайте, как реализовать ملحق Flet يسمح للمطورين ببناء تطبيقات في بيثون بدون خبرة في واجهة المستخدم. تعلم كيفية التنفيذ how to use implement-flet-extension what is implement-flet-extension implement-flet-extension alternative implement-flet-extension vs Flutter implement-flet-extension install implement-flet-extension setup guide Flet extension development Python Flutter integration real-time web app development Flet 扩展 Python 实时应用 无需前端经验 flet_* 包 包健康状况 许可兼容性 API 表面 pub.dev 包 版本范围 Implements Flet extensions using existing flet_* packages as templates Integrates with external Flutter packages from pub.dev Supports API surface exposure in Python, including properties, methods, and events Confirms package health through maintenance activity and null-safety checks Ensures license compatibility for seamless integration implement-flet-extension is a skill that allows developers to create Flet extensions around external Flutter packages using Python');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryan-alexander-zhang/persimmon/app-common-workflow-generator', 'community', 'ryan-alexander-zhang', 'persimmon', 'ryan-alexander-zhang/persimmon', 'app-common-workflow-generator', 0, 0, 41, '2026-03-08T01:57:15.387Z', '2026-03-08T02:05:55.604Z', '7b4bb0099d16cd674f570125c93f05316f7c56769facfae58115a73f8c2a806c', '{"id":"ryan-alexander-zhang/persimmon/app-common-workflow-generator","name":"app-common-workflow-generator","description":{"en":"The app-common-workflow-generator skill creates Java DDD scaffolds for common workflows, benefiting developers who need to implement workflow handlers and retry policies.","zh":"app-common-workflow-generator是一个Java DDD Scaffold工具，用于生成应用程序公共工作流","ja":"app-common-workflow-generatorはJava DDD Scaffoldツールで、アプリケーションの共通ワークフローを生成する","ko":"app-common-workflow-generator는 Java DDD Scaffold 도구로, 애플리케이션 공통 작업 흐름을 생성합니다","es":"El generador de flujos de trabajo comunes de aplicaciones es una herramienta de Java DDD que permite crear arquitecturas de software escalables y mantenibles","fr":"Le générateur de flux de travail d''applications communes est un outil Java DDD qui permet de créer des architectures logicielles évolutives et maintenables","de":"Der App-Common-Workflow-Generator ist ein Java-DDD-Tool, das die Erstellung von skalierbaren und wartbaren Software-Architekturen ermöglicht","pt":"O app-common-workflow-generator é uma ferramenta para criar fluxos de trabalho comuns em Java DDD. Ele gera step handlers e políticas de retry personalizadas","ru":"ИИ Агенты: app-common-workflow-generator - это инструмент для создания общих рабочих процессов в Java DDD. Он генерирует обработчики шагов и политику повторных попыток на заказ","ar":"الوكلاء الذكية: app-common-workflow-generator هو أداة لإنشاء سلاسل عمل مشتركة في Java DDD. يولد معالجات الخطوة وسياسات الإعادة المخصصة"},"seo":{"title