INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryan-alexander-zhang/persimmon/app-common-workflow-generator', 'app-common-workflow-generator', 'ryan-alexander-zhang', 'persimmon', 'community', 'app-common-workflow-generator ryan-alexander-zhang persimmon community The app-common-workflow-generator skill creates Java DDD scaffolds for common workflows, benefiting developers who need to implement workflow handlers and retry policies. app-common-workflow-generator是一个Java DDD Scaffold工具，用于生成应用程序公共工作流 app-common-workflow-generatorはJava DDD Scaffoldツールで、アプリケーションの共通ワークフローを生成する app-common-workflow-generator는 Java DDD Scaffold 도구로, 애플리케이션 공통 작업 흐름을 생성합니다 El generador de flujos de trabajo comunes de aplicaciones es una herramienta de Java DDD que permite crear arquitecturas de software escalables y mantenibles Le générateur de flux de travail d''applications communes est un outil Java DDD qui permet de créer des architectures logicielles évolutives et maintenables Der App-Common-Workflow-Generator ist ein Java-DDD-Tool, das die Erstellung von skalierbaren und wartbaren Software-Architekturen ermöglicht O app-common-workflow-generator é uma ferramenta para criar fluxos de trabalho comuns em Java DDD. Ele gera step handlers e políticas de retry personalizadas ИИ Агенты: app-common-workflow-generator - это инструмент для создания общих рабочих процессов в Java DDD. Он генерирует обработчики шагов и политику повторных попыток на заказ الوكلاء الذكية: app-common-workflow-generator هو أداة لإنشاء سلاسل عمل مشتركة في Java DDD. يولد معالجات الخطوة وسياسات الإعادة المخصصة how to use app-common-workflow-generator app-common-workflow-generator setup guide Java DDD scaffold generator workflow handler implementation retry policy configuration app-common-workflow-generator alternative app-common-workflow-generator vs other workflow generators install app-common-workflow-generator app-common-workflow-generator tutorial app-common-workflow-generator Java DDD Scaffold workflowType retry policy WAITING语义 WorkflowStepHandler AIエージェント Java开发工具 Generates step handlers implementing WorkflowStepHandler Supports linear step lists with ordered stepSeq and stepType Includes retry policy requirements with max attempts and backoff Handles WAITING semantics with deadline and wake-up event type Creates app/common workflow code with optional features app-common-workflow-generator is a Java-based skill that generates scaffold code for common workflows, including step handlers and retry policies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rahulmanuwas/chitti/chitti-mcp', 'community', 'rahulmanuwas', 'chitti', 'rahulmanuwas/chitti', 'chitti-mcp', 0, 0, 41, '2026-03-08T01:57:15.394Z', '2026-03-08T02:06:16.983Z', '03d039d92fe305a2a27ccf8a111f002e93c76f9ff2df119455bed53e02bbb7d7', '{"id":"rahulmanuwas/chitti/chitti-mcp","name":"chitti-mcp","description":{"en":"The chitti-mcp skill enables developers to manage decisions via Chitti''s MCP tools, supporting record, recall, and audit functionalities. It benefits AI agent developers needing decision tracking.","zh":"Chitti MCP Skill 是一个用于记录、回忆和审计决策的工具。使用 MCP 服务器和工具来快速开始","ja":"Chitti MCP スキルは、決裁を記録、再生、監査するためのツールです。MCP サーバーとツールを使用して、すぐに開始できます","ko":"Chitti MCP 스킬은 결정 기록, 회수 및 감사를 위한 도구입니다. MCP 서버와 도구를 사용하여 빠르게 시작할 수 있습니다","es":"Chitti MCP es una habilidad para grabar, recordar y auditar decisiones con herramientas de IA. Utiliza scripts como start_server.sh y mcp_call.sh","fr":"Chitti MCP est une compétence pour enregistrer, rappeler et auditer les décisions avec des outils d''IA. Utilisez des scripts tels que start_server.sh et mcp_call.sh","de":"Chitti MCP ist eine Fähigkeit, um Entscheidungen mit KI-Tools aufzuzeichnen, abzurufen und zu überprüfen. Verwenden Sie Skripte wie start_server.sh und mcp_call.sh","pt":"O Chitti-MCP é uma habilidade que fornece ferramentas para registrar, lembrar e auditar decisões. Ele inclui comandos como chitti.decide e chitti.recall","ru":"Chitti-MCP - это навык, который предоставляет инструменты для записи, воспоминания и аудита решений. Он включает команды, такие как chitti.decide и chitti.recall ИИ Агентов","ar":"Chitti-MCP هو مهارة توفر أدوات لتسجيل و استدعاء و التدقيق في القرارات. يتضمن أوامر مثل chitti.decide و chitti.recall للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"chitti-mcp: Decision Management Setup Guide | AI Agent Skill","zh":"Chitti MCP Skill 快速入门指