INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rahulmanuwas/chitti/chitti-mcp', 'chitti-mcp', 'rahulmanuwas', 'chitti', 'community', 'chitti-mcp rahulmanuwas chitti community The chitti-mcp skill enables developers to manage decisions via Chitti''s MCP tools, supporting record, recall, and audit functionalities. It benefits AI agent developers needing decision tracking. Chitti MCP Skill 是一个用于记录、回忆和审计决策的工具。使用 MCP 服务器和工具来快速开始 Chitti MCP スキルは、決裁を記録、再生、監査するためのツールです。MCP サーバーとツールを使用して、すぐに開始できます Chitti MCP 스킬은 결정 기록, 회수 및 감사를 위한 도구입니다. MCP 서버와 도구를 사용하여 빠르게 시작할 수 있습니다 Chitti MCP es una habilidad para grabar, recordar y auditar decisiones con herramientas de IA. Utiliza scripts como start_server.sh y mcp_call.sh Chitti MCP est une compétence pour enregistrer, rappeler et auditer les décisions avec des outils d''IA. Utilisez des scripts tels que start_server.sh et mcp_call.sh Chitti MCP ist eine Fähigkeit, um Entscheidungen mit KI-Tools aufzuzeichnen, abzurufen und zu überprüfen. Verwenden Sie Skripte wie start_server.sh und mcp_call.sh O Chitti-MCP é uma habilidade que fornece ferramentas para registrar, lembrar e auditar decisões. Ele inclui comandos como chitti.decide e chitti.recall Chitti-MCP - это навык, который предоставляет инструменты для записи, воспоминания и аудита решений. Он включает команды, такие как chitti.decide и chitti.recall ИИ Агентов Chitti-MCP هو مهارة توفر أدوات لتسجيل و استدعاء و التدقيق في القرارات. يتضمن أوامر مثل chitti.decide و chitti.recall للوكلاء الذكاء الاصطناعي how to use chitti-mcp chitti-mcp setup guide chitti-mcp decision management chitti-mcp vs other AI agent skills installing chitti-mcp chitti-mcp tutorial for developers Chitti MCP Skill AI 工具 决策记录 MCP 服务器 CLI 命令 快速开始 开发者指南 Starts the MCP server using the `scripts/start_server.sh` command Supports one-shot tool calls via `scripts/mcp_call.sh` with JSON payloads Provides `chitti.decide` tool for recording decisions with `action`, `amount`, and `reason` parameters Offers `chitti.recall` tool for querying decision history with filter support Utilizes shell scripts for easy server management and tool invocation chitti-mcp is a skill that provides decision management capabilities using Chitti''s MCP tools, allowing for recording, recalling, and auditing decisions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('canxin121/codex-taskloop-plugin/codex-taskloop-plugin', 'community', 'canxin121', 'codex-taskloop-plugin', 'canxin121/codex-taskloop-plugin', 'codex-taskloop-plugin', 0, 0, 41, '2026-03-08T01:57:15.398Z', '2026-03-08T02:06:28.932Z', 'd56acaea9cc622128414caf2c7a7043372035524d269e6c4471cd6e0ade73d4c', '{"id":"canxin121/codex-taskloop-plugin/codex-taskloop-plugin","name":"codex-taskloop-plugin","description":{"en":"The codex-taskloop-plugin skill automates tasks inside a single Codex session, benefiting developers who need to manage multiple tasks efficiently. It provides a core workflow for starting, continuing, and managing tasks.","zh":"Codex Taskloop Plugin 是一个用于管理任务循环的工具，支持启动、继续、列出、重命名、恢复和删除任务","ja":"Codex Taskloop Plugin はタスクループを管理するためのツールで、開始、続行、リスト、名前変更、再開、削除などの機能を提供します","ko":"Codex Taskloop Plugin은 태스크 루프를 관리하기 위한 도구로 시작, 계속, 목록, 이름 변경, 재개, 삭제 등의 기능을 제공합니다","es":"El plugin codex-taskloop-plugin permite a los desarrolladores gestionar tareas dentro de una sesión de Codex con funcionalidades como start, continue, list, rename, resume y delete.","fr":"Le plugin codex-taskloop-plugin permet aux développeurs de gérer des tâches à l''intérieur d''une session Codex avec des fonctionnalités comme start, continue, list, rename, resume et delete.","de":"Das codex-taskloop-plugin ermöglicht es Entwicklern, Aufgaben innerhalb einer Codex-Sitzung mit Funktionalitäten wie Start, Continue, List, Rename, Resume und Delete zu verwalten.","pt":"O Codex Taskloop Plugin é uma ferramenta para automatizar tarefas dentro de uma sessão Codex. Ele permite iniciar, continuar, listar, renomear, retomar ou excluir tarefas de Taskloop.","ru":"Codex Taskloop Plugin - это инструмент для автоматизации задач внутри одной сессии Codex. Он позволяет запускать, продолжать, перечислять, переименовывать, возобновлять или удалять задачи Taskloop.","ar":"Codex Taskloop Plugin هو أداة لتحسين إدارة المهام داخل جلسة Codex. يسمح ببدء، استئناف، قائمة، إعادة تسمية، استئناف أو حذف مهام Taskloop."},"seo":{"title":{"en":"codex-taskloop-plugin: Task Automation Setup Guide | AI A...","zh":"Codex Taskloop Plugin 安装指南","ja":"Codex Taskloop Plugin のベストプラクティス","ko":"Codex Taskloop Plugin 설정 가이드","es":"Guía de configuración del plugin codex-taskloop-plugin pa...","fr":"Guide de mise en route du plugin codex-taskloop-plugin po...","de":"Einrichtungsleitfaden für das codex-taskloop-plugin für K...","pt":"Guia de Configuração do Codex Taskloop Plugin","ru":"Настройка Codex Taskloop Plugin: ИИ Агенты для Автоматизации","ar":"دليل إعداد Codex Taskloop Plugin لآلات الإيضاح"},"description":{"en":"Discover how to automate tasks with codex-taskloop-plugin. Learn to install, use, and optimize this AI agent skill for efficient task management.","zh":"了解 Codex Taskloop Plugin 的功能和安装步骤，实现任务循环管理","ja":"Codex Taskloop Plugin を使用してタスクループを管理する方法を学ぶ","ko":"Codex Taskloop Plugin을 사용하여 태스크 루프를 관리하는 방법을 알아보세요","es":"Descubre cómo configurar y utilizar el plugin codex-taskloop-plugin para gestionar tareas dentro de una sesión de Codex con Agentes de IA","fr":"Découvrez comment configurer et utiliser le plugin codex-taskloop-plugin pour gérer des tâches à l''intérieur d''une session Codex avec des Outils d''IA","de":"Erfahren Sie, wie Sie das codex-taskloop-plugin konfigurieren und verwenden, um Aufgaben innerhalb einer Codex-Sitzung mit KI-Tools zu verwalten","pt":"Aprenda a configurar o Codex Taskloop Plugin para automatizar tarefas dentro de uma sessão Codex","ru":"Узнайте, как настроить Codex Taskloop Plugin для автоматизации задач в рамках одной сессии Codex с помощью ИИ Агентов","ar":"اكتشف كيفية إعداد Codex Taskloop Plugin لتحسين إدارة المهام داخل جلسة Codex باستخدام أدوات الإيضاح"},"definition":{"en":"codex-taskloop-plugin is a skill that automates task management inside a Codex session, using the MCP tool and task_loop command.","zh":"Codex Taskloop Plugin 是一个用于管理任务循环的 AI 工具","ja":"Codex Taskloop Plugin はタスクループを管理するための AI エージェントです","ko":"Codex Taskloop Plugin은 태스크 루프를 관리하기 위한 AI 에이전트입니다","es":"El plugin codex-taskloop-plugin es una herramienta para la gestión de tareas dentro de una sesión de Codex","fr":"Le plugin codex-taskloop-plugin est un outil pour la gestion de tâches à l''intérieur d''une session Codex","de":"Das codex-taskloop-plugin ist ein Tool für die Aufgabenverwaltung innerhalb einer Codex-Sitzung","pt":"O que é Codex Taskloop Plugin? É uma ferramenta de automação de tarefas para sessões Codex","ru":"Что такое Codex Taskloop Plugin? Это инструмент для автоматизации задач в рамках сессии Codex","ar":"ما هو Codex Taskloop Plugin? هو أداة لتحسين إدارة المهام داخل جلسة Codex"},"features":{"en":["Starts a loop with the MCP tool task_loop","Supports installation via scripts/install.sh","Allows listing, renaming, resuming, and deleting tasks","Requires codex-taskloop-plugin MCP server registration","Uses project and user scope for installation"],"zh":["支持启动、继续、列出、重命名、恢复和删除任务","使用 MCP 工具 task_loop 启动循环","支持项目范围和用户范围的安装","提供 scripts/install.sh 安装脚本"],"ja":["開始、続行、リスト、名前変更、再開、削除などの機能を提供","MCP ツール task_loop を使用してループを開始","プロジェクト範囲とユーザー範囲のインストールをサポート","scripts/install.sh インストールスクリプトを提供"],"ko":["시작, 계속, 목록, 이름 변경, 재개, 삭제 등의 기능을 제공","MCP 도구 task_loop를 사용하여 루프를 시작","프로젝트 범위와 사용자 범위의 설치를 지원","scripts/install.sh 설치 스크립트를 제공"],"es":["Gestión de tareas con funcionalidades como start, continue, list, rename, resume y delete","Integración con el servidor MCP","Instalación mediante scripts en ámbito de proyecto o usuario","Uso de la herramienta task_loop para iniciar un bucle"],"fr":["Gestion de tâches avec des fonctionnalités comme start, continue, list, rename, resume et delete","Intégration avec le serveur MCP","Installation via des scripts dans la portée du projet ou de l''utilisateur","Utilisation de l''outil task_loop pour lancer une boucle"],"de":["Aufgabenverwaltung mit Funktionalitäten wie Start, Continue, List, Rename, Resume und Delete","Integration mit dem MCP-Server","Installation über Skripte im Projekt- oder Benutzerbereich","Verwendung des Tools task_loop zum Starten einer Schleife"],"pt":["Iniciar loops com o MCP tool ''task_loop''","Automatizar tarefas de Taskloop dentro de uma sessão Codex","Suporte à instalação em escopo de projeto ou usuário","Integração com o stop hook do codex-taskloop-plugin"],"ru":["Запуск циклов с помощью инструмента MCP ''task_loop''","Автоматизация задач Taskloop в рамках одной сессии Codex","Поддержка установки в проектном или пользовательском объеме","Интеграция с хуком остановки codex-taskloop-plugin"],"ar":["بدء الحلقات باستخدام أداة MCP ''task_loop''","تحسين إدارة المهام Taskloop داخل جلسة Codex","دعم التثبيت في نطاق المشروع أو المستخدم","التكامل مع مشبك التوقف codex-taskloop-plugin"]},"keywords":{"en":["how to use codex-taskloop-plugin","codex-taskloop-plugin setup guide","codex-taskloop-plugin alternative","codex-taskloop-plugin vs task automation tools","codex-taskloop-plugin install","what is codex-taskloop-plugin","codex-taskloop-plugin tutorial","task automation with codex-taskloop-plugin"],"zh":["Codex Taskloop Plugin","AI 工具","任务循环管理","MCP 工具","task_loop","项目范围安装","用户范围安装"],"ja":["Codex Taskloop Plugin","AI エージェント","タスクループ管理","MCP ツール","task_loop","プロジェクト範囲のインストール","ユーザー範囲のインストール"],"ko":["Codex Taskloop Plugin","AI 에이전트","태스크 루프 관리","MCP 도구","task_loop","프로젝트 범위의 설치","사용자 범위의 설치"],"es":["plugin codex-taskloop-plugin","Agentes de IA","gestión de tareas","MCP","task_loop"," instalación de plugins","desarrollo de software","herramientas de desarrollo"],"fr":["plugin codex-taskloop-plugin","Outils d''IA","gestion de tâches","MCP","task_loop","installation de plugins","développement de logiciels","outils de développement"],"de":["codex-taskloop-plugin","KI-Tools","Aufgabenverwaltung","MCP","task_loop","Plugin-Installation","Software-Entwicklung","Entwicklertools"],"pt":["Codex Taskloop Plugin","automação de tarefas","sessão Codex","MCP tool","Taskloop","instalação em escopo de projeto","instalação em escopo de usuário"],"ru":["Codex Taskloop Plugin","автоматизация задач","сессия Codex","инструмент MCP","Taskloop","установка в проектном объеме","установка в пользовательском объеме","ИИ Агенты"],"ar":["Codex Taskloop Plugin","تحسين إدارة المهام","جلسة Codex","أداة MCP","Taskloop","تثبيت في نطاق المشروع","تثبيت في نطاق المستخدم","آلات الإيضاح"]}},"owner":"canxin121","repo":"codex-taskloop-plugin","repoPath":"canxin121/codex-taskloop-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.398Z","topics":[],"category":"community","skillMd":{"name":"codex-taskloop-plugin","description":"Run in-session task loops via the codex-taskloop-plugin MCP server and stop hook.","bodyPreview":"# Codex Taskloop Plugin\n\n## When to use\n\nUse this skill when a user asks to start, continue, list, rename, resume, or delete\nTaskloop tasks inside a single Codex session.\n\n## Preconditions\n\n- The codex-taskloop-plugin MCP server is registered.\n- The codex-taskloop-plugin stop hook is installed.\n\nIf not installed:\n- Project scope: `scripts/install.sh --scope project --project \"<path>\"`\n- User scope: `scripts/install.sh --scope user`\n\n## Core workflow\n\n1) Start a loop with the MCP tool `task_loop`","body":"# Codex Taskloop Plugin\n\n## When to use\n\nUse this skill when a user asks to start, continue, list, rename, resume, or delete\nTaskloop tasks inside a single Codex session.\n\n## Preconditions\n\n- The codex-taskloop-plugin MCP server is registered.\n- The codex-taskloop-plugin stop hook is installed.\n\nIf not installed:\n- Project scope: `scripts/install.sh --scope project --project \"<path>\"`\n- User scope: `scripts/install.sh --scope user`\n\n## Core workflow\n\n1) Start a loop with the MCP tool `task_loop` and a clear prompt.\n2) Use `completion_promise` so the loop stops when the assistant outputs\n   `<promise>...</promise>`.\n3) Control tasks with `task_list`, `task_resume`, `task_rename`, and `task_delete`.\n4) Storage:\n   - Project install enforces project-only storage.\n   - User install allows `project` or `user` per tool call.\n\n## Tool quick reference\n\n- `task_loop`: prompt (required), task_name, max_iterations, completion_promise,\n  completion_matcher, history_limit, storage, project_dir\n- `task_list`: storage, project_dir, limit, offset\n- `task_resume`: task_name, storage, project_dir\n- `task_rename`: task_name, new_name, storage, project_dir\n- `task_delete`: task_name, storage, project_dir\n\n## Conventions\n\n- Use a short, meaningful task_name or let it auto-generate from the first line.\n- Put the promise text inside `<promise>...</promise>` exactly when done.\n"},"lastSynced":"2026-03-08T02:06:28.932Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor, Windsurf, or Claude Code needing to automate tasks within a single Codex session efficiently.","zh":"非常适合像Cursor、Windsurf或Claude Code这样的AI代理，需要在单个Codex会话中高效地自动执行任务。","ja":"Cursor、Windsurf、またはClaude CodeのようなAIエージェントに最適で、単一のCodexセッション内でタスクを効率的に自動化する必要があります。","ko":"커서, 윈드서프 또는 클로드 코드와 같은 AI 에이전트에 적합하며 단일 Codex 세션 내에서 작업을 효율적으로 자동화해야 합니다.","es":"Perfecto para agentes de IA como Cursor, Windsurf o Claude Code que necesitan automatizar tareas dentro de una sola sesión de Codex de manera eficiente.","fr":"Parfait pour les agents IA comme Cursor, Windsurf ou Claude Code ayant besoin d''automatiser des tâches au sein d''une seule session Codex de manière efficace.","de":"Perfekt für KI-Agents wie Cursor, Windsurf oder Claude Code, die Aufgaben innerhalb einer einzelnen Codex-Sitzung effizient automatisieren müssen.","pt":"Perfeito para Agentes de IA como Cursor, Windsurf ou Claude Code que precisam automatizar tarefas dentro de uma única sessão Codex de forma eficiente.","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf или Claude Code, которым необходимо автоматизировать задачи в течение одной сессии Codex эффективно.","ar":"مثالي لنظامي الوكيل مثل Cursor و Windsurf أو Claude Code الذي يحتاج إلى توفير مهام داخل جلسة Codex واحدة بكفاءة."},"recommendation":{"en":"Empowers agents to manage multiple tasks seamlessly using the codex-taskloop-plugin, providing a core workflow for starting, continuing, and managing tasks via the MCP tool, utilizing protocols like task_loop for streamlined task management.","zh":"通过codex-taskloop-plugin赋予代理管理多个任务的能力，提供一个核心工作流来启动、继续和管理任务，利用诸如task_loop的协议实现流畅的任务管理，所有这些都通过MCP工具来完成。","ja":"codex-taskloop-pluginを使用してエージェントに複数のタスクを管理する能力を提供し、MCPツールを使用してタスクを開始、続行、管理するためのコアワークフローを提供し、task_loopなどのプロトコルを使用してタスク管理を스트リーミングします。","ko":"codex-taskloop-plugin을 사용하여 에이전트가 여러 작업을 관리할 수 있는 기능을 제공하며 MCP 도구를 사용하여 작업을 시작, 계속, 관리하는 데 필요한 핵심 워크플로우를 제공하며 task_loop와 같은 프로토콜을 사용하여 작업 관리를 스트리밍합니다.","es":"Habilita a los agentes a gestionar múltiples tareas de manera fluida utilizando el plugin codex-taskloop-plugin, proporcionando un flujo de trabajo central para iniciar, continuar y gestionar tareas a través de la herramienta MCP, utilizando protocolos como task_loop para una gestión de tareas optimizada.","fr":"Permet aux agents de gérer plusieurs tâches de manière fluide en utilisant le plugin codex-taskloop-plugin, fournissant un flux de travail central pour démarrer, continuer et gérer des tâches via l''outil MCP, en utilisant des protocoles comme task_loop pour une gestion de tâches rationalisée.","de":"Ermöglicht es Agenten, mehrere Aufgaben nahtlos zu verwalten, indem sie das codex-taskloop-plugin verwenden, und bietet einen Kern-Workflow für das Starten, Fortsetzen und Verwalten von Aufgaben über das MCP-Tool, unter Nutzung von Protokollen wie task_loop für eine optimierte Aufgabenverwaltung.","pt":"Habilita os agentes a gerenciar várias tarefas de forma transparente usando o codex-taskloop-plugin, fornecendo um fluxo de trabalho central para iniciar, continuar e gerenciar tarefas via a ferramenta MCP, utilizando protocolos como task_loop para gerenciamento de tarefas otimizado.","ru":"Наделяет агентов возможностью управлять несколькими задачами без проблем с помощью codex-taskloop-plugin, предоставляя основной рабочий процесс для запуска, продолжения и управления задачами через инструмент MCP, используя протоколы, такие как task_loop для оптимизированного управления задачами.","ar":"يمنح الوكلاء القدرة على إدارة مهام متعددة بطريقة سلسة باستخدام codex-taskloop-plugin، وتوفير تدفق عمل أساسي لبدء واستمرار وتنظيم المهام من خلال أداة MCP، واستخدام بروتوكولات مثل task_loop لإدارة المهام المتسلسلة."},"useCases":{"en":["Automating task loops within a Codex session","Managing multiple tasks efficiently with task_loop","Streamlining workflows by starting, continuing, listing, renaming, resuming, or deleting tasks"],"zh":["在Codex会话中自动执行任务循环","使用task_loop高效地管理多个任务","通过启动、继续、列出、重命名、恢复或删除任务来简化工作流程"],"ja":["Codexセッション内でタスクループを自動化する","task_loopを使用して複数のタスクを効率的に管理する","タスクを開始、続行、リスト、名前を変更、再開、または削除することでワークフローをストリーミングする"],"ko":["Codex 세션 내에서 작업 루프를 자동화하는 것","task_loop를 사용하여 여러 작업을 효율적으로 관리하는 것","작업을 시작, 계속, 목록, 이름을 변경, 다시 시작 또는 삭제하여 워크플ロー 스트리밍"],"es":["Automatizar bucles de tareas dentro de una sesión de Codex","Gestionar múltiples tareas de manera eficiente con task_loop","Optimizar flujos de trabajo iniciando, continuando, listando, renombrando, reanudando o eliminando tareas"],"fr":["Automatiser des boucles de tâches au sein d''une session Codex","Gérer plusieurs tâches de manière efficace avec task_loop","Rationaliser les flux de travail en démarrant, continuant, listant, renommant, reprenant ou supprimant des tâches"],"de":["Automatisieren von Aufgabenschleifen innerhalb einer Codex-Sitzung","Mehrere Aufgaben effizient mit task_loop verwalten","Arbeitsabläufe optimieren, indem Aufgaben gestartet, fortgesetzt, aufgelistet, umbenannt, wieder aufgenommen oder gelöscht werden"],"pt":["Automatizar loops de tarefas dentro de uma sessão Codex","Gerenciar várias tarefas de forma eficiente com task_loop","Otimizar fluxos de trabalho iniciando, continuando, listando, renomeando, retomando ou excluindo tarefas"],"ru":["Автоматизировать циклы задач внутри сессии Codex","Управлять несколькими задачами эффективно с помощью task_loop","Оптимизировать рабочие процессы, запуская, продолжая, перечисляя, переименовывая, возобновляя или удаляя задачи"],"ar":["توفير حلقات المهام داخل جلسة Codex","إدارة مهام متعددة بكفاءة مع task_loop","تحسين سير العمل من خلال بدء واستمرار وإنشاء قائمة واعادة تسمية واستئناف أو حذف المهام"]},"limitations":{"en":["Requires the codex-taskloop-plugin MCP server to be registered","Needs the codex-taskloop-plugin stop hook to be installed","Limited to project or user scope installation via scripts/install.sh"],"zh":["需要注册codex-taskloop-plugin MCP服务器","需要安装codex-taskloop-plugin停止钩子","仅限通过脚本/install.sh进行项目或用户范围的安装"],"ja":["codex-taskloop-plugin MCPサーバーを登録する必要がある","codex-taskloop-plugin停止フックをインストールする必要がある","スクリプト/install.shを使用してプロジェクトまたはユーザーの範囲内でのみインストール可能"],"ko":["codex-taskloop-plugin MCP 서버를 등록해야 함","codex-taskloop-plugin 중지 후크를 설치해야 함","스크립트/install.sh를 사용하여 프로젝트 또는 사용자 범위 내에서만 설치할 수 있음"],"es":["Requiere que el servidor MCP del plugin codex-taskloop-plugin esté registrado","Necesita que el hook de parada del plugin codex-taskloop-plugin esté instalado","Limitado a la instalación de ámbito de proyecto o usuario a través de scripts/install.sh"],"fr":["Nécessite que le serveur MCP du plugin codex-taskloop-plugin soit enregistré","A besoin que le hook d''arrêt du plugin codex-taskloop-plugin soit installé","Limité à l''installation dans la portée du projet ou de l''utilisateur via scripts/install.sh"],"de":["Benötigt, dass der MCP-Server des codex-taskloop-plugin-Plugins registriert ist","Benötigt, dass der Stopp-Hook des codex-taskloop-plugin-Plugins installiert ist","Begrenzt auf die Installation im Projekt- oder Benutzerbereich über scripts/install.sh"],"pt":["Exige que o servidor MCP do codex-taskloop-plugin seja registrado","Necessita que o hook de parada do codex-taskloop-plugin seja instalado","Limitado à instalação de escopo de projeto ou usuário via scripts/install.sh"],"ru":["Требует регистрации сервера MCP плагина codex-taskloop","Требует установки хука остановки плагина codex-taskloop","Ограничен установкой в объеме проекта или пользователя через scripts/install.sh"],"ar":["يتطلب تسجيل خادم MCP لملحق codex-taskloop-plugin","يتطلب تثبيت كابح إيقاف ملحق codex-taskloop-plugin","محدد إلى تثبيت نطاق المشروع أو المستخدم من خلال scripts/install.sh"]},"version":4},"contentHash":"d56acaea9cc622128414caf2c7a7043372035524d269e6c4471cd6e0ade73d4c","qualityScore":41}');
