INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('canxin121/codex-taskloop-plugin/codex-taskloop-plugin', 'codex-taskloop-plugin', 'canxin121', 'codex-taskloop-plugin', 'community', 'codex-taskloop-plugin canxin121 codex-taskloop-plugin community The codex-taskloop-plugin skill automates tasks inside a single Codex session, benefiting developers who need to manage multiple tasks efficiently. It provides a core workflow for starting, continuing, and managing tasks. Codex Taskloop Plugin 是一个用于管理任务循环的工具，支持启动、继续、列出、重命名、恢复和删除任务 Codex Taskloop Plugin はタスクループを管理するためのツールで、開始、続行、リスト、名前変更、再開、削除などの機能を提供します Codex Taskloop Plugin은 태스크 루프를 관리하기 위한 도구로 시작, 계속, 목록, 이름 변경, 재개, 삭제 등의 기능을 제공합니다 El plugin codex-taskloop-plugin permite a los desarrolladores gestionar tareas dentro de una sesión de Codex con funcionalidades como start, continue, list, rename, resume y delete. Le plugin codex-taskloop-plugin permet aux développeurs de gérer des tâches à l''intérieur d''une session Codex avec des fonctionnalités comme start, continue, list, rename, resume et delete. Das codex-taskloop-plugin ermöglicht es Entwicklern, Aufgaben innerhalb einer Codex-Sitzung mit Funktionalitäten wie Start, Continue, List, Rename, Resume und Delete zu verwalten. O Codex Taskloop Plugin é uma ferramenta para automatizar tarefas dentro de uma sessão Codex. Ele permite iniciar, continuar, listar, renomear, retomar ou excluir tarefas de Taskloop. Codex Taskloop Plugin - это инструмент для автоматизации задач внутри одной сессии Codex. Он позволяет запускать, продолжать, перечислять, переименовывать, возобновлять или удалять задачи Taskloop. Codex Taskloop Plugin هو أداة لتحسين إدارة المهام داخل جلسة Codex. يسمح ببدء، استئناف، قائمة، إعادة تسمية، استئناف أو حذف مهام Taskloop. how to use codex-taskloop-plugin codex-taskloop-plugin setup guide codex-taskloop-plugin alternative codex-taskloop-plugin vs task automation tools codex-taskloop-plugin install what is codex-taskloop-plugin codex-taskloop-plugin tutorial task automation with codex-taskloop-plugin Codex Taskloop Plugin AI 工具 任务循环管理 MCP 工具 task_loop 项目范围安装 用户范围安装 Starts a loop with the MCP tool task_loop Supports installation via scripts/install.sh Allows listing, renaming, resuming, and deleting tasks Requires codex-taskloop-plugin MCP server registration Uses project and user scope for installation codex-taskloop-plugin is a skill that automates task management inside a Codex session, using the MCP tool and task_loop command.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('djaiss/journalOS/modules-readme-updater', 'community', 'djaiss', 'journalOS', 'djaiss/journalOS', 'modules-readme-updater', 0, 0, 41, '2026-03-08T01:57:15.387Z', '2026-03-08T02:07:02.360Z', 'f0a3cd0efe692f4d6e5728aea1b44cf7b494a68264ccfde34ff2374eca85d56a', '{"id":"djaiss/journalOS/modules-readme-updater","name":"modules-readme-updater","description":{"en":"The modules-readme-updater skill updates the project README.md to accurately document all existing journal modules in a clear structure. It benefits JournalOS developers by maintaining consistent documentation.","zh":"modules-readme-updater Skill 自动更新项目 README.md 文件，确保模块文档的准确性和一致性","ja":"modules-readme-updater はプロジェクトの README.md ファイルを自動更新し、モジュールのドキュメントを正確に保つ AIエージェント Skill です","ko":"modules-readme-updater Skill은 프로젝트 README.md 파일을 자동으로 업데이트 하여 모듈 문서의 정확성과 일관성을 유지하는 AI 도구입니다","es":"El actualizador de README de módulos es un skill que actualiza la documentación de módulos en el archivo README.md de tu proyecto JournalOS. Aprende a configurar y utilizar este skill para mantener tu proyecto organizado","fr":"Le module de mise à jour de README est un skill qui met à jour la documentation des modules dans le fichier README.md de votre projet JournalOS. Découvrez comment configurer et utiliser ce skill pour maintenir votre projet organisé","de":"Das Modul-README-Updater-Tool ist ein Skill, der die Modul-Dokumentation im README.md-File Ihres JournalOS-Projekts aktualisiert. Erfahren Sie, wie Sie diesen Skill konfigurieren und verwenden können, um Ihr Projekt organisiert zu halten","pt":"O modules-readme-updater é uma ferramenta que atualiza a documentação de módulos em projetos JournalOS, garantindo consistência e clareza.","ru":"ИИ Агент modules-readme-updater обновляет документацию модулей в проектах JournalOS, обеспечивая согласованность и ясность.","ar":"يع