INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('djaiss/journalOS/modules-readme-updater', 'modules-readme-updater', 'djaiss', 'journalOS', 'community', 'modules-readme-updater djaiss journalOS community The modules-readme-updater skill updates the project README.md to accurately document all existing journal modules in a clear structure. It benefits JournalOS developers by maintaining consistent documentation. modules-readme-updater Skill 自动更新项目 README.md 文件，确保模块文档的准确性和一致性 modules-readme-updater はプロジェクトの README.md ファイルを自動更新し、モジュールのドキュメントを正確に保つ AIエージェント Skill です modules-readme-updater Skill은 프로젝트 README.md 파일을 자동으로 업데이트 하여 모듈 문서의 정확성과 일관성을 유지하는 AI 도구입니다 El actualizador de README de módulos es un skill que actualiza la documentación de módulos en el archivo README.md de tu proyecto JournalOS. Aprende a configurar y utilizar este skill para mantener tu proyecto organizado Le module de mise à jour de README est un skill qui met à jour la documentation des modules dans le fichier README.md de votre projet JournalOS. Découvrez comment configurer et utiliser ce skill pour maintenir votre projet organisé Das Modul-README-Updater-Tool ist ein Skill, der die Modul-Dokumentation im README.md-File Ihres JournalOS-Projekts aktualisiert. Erfahren Sie, wie Sie diesen Skill konfigurieren und verwenden können, um Ihr Projekt organisiert zu halten O modules-readme-updater é uma ferramenta que atualiza a documentação de módulos em projetos JournalOS, garantindo consistência e clareza. ИИ Агент modules-readme-updater обновляет документацию модулей в проектах JournalOS, обеспечивая согласованность и ясность. يعمل modules-readme-updater على تحديث وثائق المكونات الإضافية في مشاريع JournalOS، مما يضمن الاتساق والوضوح. how to use modules-readme-updater modules-readme-updater setup guide journalos documentation automation modules-readme-updater alternative automating readme updates journalos module documentation modules-readme-updater AI 工具 自动更新 README 模块文档 项目管理 代码质量 自动化 Updates README.md to reflect changes in journal modules Ensures consistent and alphabetical documentation of modules Automates insertion of module information under the Features section Supports updates when new modules are added or removed Maintains proper indentation and structure in README.md modules-readme-updater is a skill that automates updates to the README.md file in JournalOS projects, ensuring accurate and consistent documentation of journal modules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jsboige/roo-extensions/git-sync', 'community', 'jsboige', 'roo-extensions', 'jsboige/roo-extensions', 'git-sync', 0, 0, 41, '2026-03-08T01:57:15.412Z', '2026-03-08T02:07:06.403Z', 'e6fb766d5d40ff11869452b34b86f6d4ca5cdef0b74239bd4ee233c51e1f2d5a', '{"id":"jsboige/roo-extensions/git-sync","name":"git-sync","description":{"en":"The git-sync skill enables AI agents to synchronize Git repositories, ensuring consistent project updates across multiple machines. It benefits developers working on collaborative projects with roo-extensions.","zh":"Git Sync 是用于 roo-extensions 的 submodule 和 merges Conservatifs 同步工具","ja":"Git Sync は roo-extensions 用の submodule と merges Conservatifs 同期ツールです","ko":"Git Sync는 roo-extensions용 submodule 및 merges Conservatifs 동기화 도구입니다","es":"Git-sync es una habilidad para sincronizar cambios en roo-extensions con submodule mcps/internal y merges conservativos. Es útil para recuperar cambios remotos y mantener actualizados","fr":"Git-sync est une compétence pour synchroniser les modifications dans roo-extensions avec le submodule mcps/internal et les merges conservatifs. Elle est utile pour récupérer les modifications distantes et rester à jour","de":"Git-sync ist eine Fähigkeit zur Synchronisierung von Änderungen in roo-extensions mit dem Submodul mcps/internal und konservativen Merges. Sie ist nützlich, um remote Änderungen zu übernehmen und auf dem neuesten Stand zu bleiben","pt":"O Git-Sync é uma ferramenta de sincronização de código que permite atualizar seu projeto com as últimas alterações do repositório remoto","ru":"Git-Sync - это инструмент синхронизации кода, который позволяет обновить проект с последними изменениями из удаленного репозитория с помощью ИИ Агентов","ar":"Git-Sync هو أداة مزامنة الكود التي تمكنك من تحديث مشروعك بأحدث التغييرات من المستودع البعيد مع أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"git-sync: Synchronization Setup Guide for AI Agents","zh":"Git Sync_SETUP Guide - AIエージェント_for roo-extensions","ja":"Git Sync ベストプラクティス - AIエージェント_for roo-extensions","ko":"Git Sync 설정 가이드 - AI 도구_for roo-extensions","es":"Guía de configuración de git-sync para desarrolladores","fr":"Guide d''installation de git-sync pour les développeurs","de":"Einrichtungsleitfaden für git-sync-Entwickler","pt":"Guia de Configuração do Git-Sync: Sincronização de Código","ru":"Настройка Git-Sync: Руководство по синхронизации кода с И...","ar":"دليل إعداد Git-Sync: مزامنة الكود مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to synchronize Git repositories with git-sync. Learn to override global skills and configure submodule synchronization for seamless collaboration.","zh":"了解 Git Sync 的功能和用途，实现 roo-extensions 的 submodule 和 merges Conservatifs 同步","ja":"Git Sync の機能と使い方をマスターし、roo-extensions の submodule と merges Conservatifs を同期します","ko":"Git Sync 기능과 용도를 익히고 roo-extensions의 submodule 및 merges Conservatifs 동기화를 구현하세요","es":"Aprende a configurar git-sync para sincronizar cambios en roo-extensions con submodule mcps/internal y merges conservativos","fr":"Découvrez comment installer git-sync pour synchroniser les modifications dans roo-extensions avec le submodule mcps/internal et les merges conservatifs","de":"Erfahren Sie, wie Sie git-sync für die Synchronisierung von Änderungen in roo-extensions mit dem Submodul mcps/internal und konservativen Merges einrichten","pt":"Aprenda a configurar o Git-Sync para sincronizar seu código com o repositório remoto e mantenha seu projeto atualizado","ru":"Узнайте, как настроить Git-Sync для синхронизации кода с удаленным репозиторием и поддержания проекта в актуальном состоянии с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Git-Sync لتحديث الكود الخاص بك مع المستودع البعيد و الحفاظ على مشروعك محدثًا مع أدوات الذكاء الاصطناعي"},"definition":{"en":"git-sync is a skill that provides Git synchronization for roo-extensions, utilizing submodule synchronization and conservative merges.","zh":"Git Sync 是一种用于实现 Git 仓库 submodule 和 merges Conservatifs 同步的 AI 工具","ja":"Git Sync は Git リポジトリの submodule と merges Conservatifs を同期する AI エージェントの一種です","ko":"Git Sync는 Git 저장소의 submodule 및 merges Conservatifs 동기화를 thực現하는 AI 도구의 일종입니다","es":"Git-sync es una habilidad de sincronización para roo-extensions que utiliza submodulos y merges conservativos","fr":"Git-sync est une compétence de synchronisation pour roo-extensions qui utilise des sous-modules et des merges conservatifs","de":"Git-sync ist eine Synchronisationsfähigkeit für roo-extensions, die Submodule und konservative Merges verwendet","pt":"Git-Sync é uma habilidade que sincroniza o código do projeto com o repositório remoto","ru":"Git-Sync - это навык, который синхронизирует код проекта с удаленным репозиторием","ar":"Git-Sync هو مهارة تزامن الكود الخاص بمشروع مع المستودع البعيد"},"features":{"en":["Overrides global skills using ~/.claude/skills/git-sync/SKILL.md","Utilizes submodule synchronization with mcps/internal","Performs conservative merges for multi-machine environments","Supports synchronization during session startup and phase 2 sync","Enables updates retrieval before starting work","Automates synchronization after receiving updates"],"zh":["支持 roo-extensions 的 submodule 同步","实现 merges Conservatifs 同步","支持多机同步","用于 Git 仓库同步","提供 Override 项目的功能","支持 generic Template"],"ja":["roo-extensions の submodule 同期をサポート","merges Conservatifs 同期を実現","マルチマシン同期をサポート","Git リポジトリ同期に使用","Override プロジェクト機能を提供","generic Template をサポート"],"ko":["roo-extensions의 submodule 동기화를 지원","merges Conservatifs 동기화를 구현","다중 기기 동기화를 지원","Git 저장소 동기화에 사용","Override 프로젝트 기능을 제공","generic Template를 지원"],"es":["Sincronización de cambios en roo-extensions","Uso de submodule mcps/internal","Merges conservativos para mantener la integridad de los datos","Compatible con multi-máquinas","Recuperación de cambios remotos","Mantenimiento de actualizaciones"],"fr":["Synchronisation des modifications dans roo-extensions","Utilisation du sous-module mcps/internal","Merges conservatifs pour maintenir l''intégrité des données","Compatibilité avec plusieurs machines","Récupération des modifications distantes","Maintenance des mises à jour"],"de":["Synchronisierung von Änderungen in roo-extensions","Verwendung des Submoduls mcps/internal","Konservative Merges zur Aufrechterhaltung der Datenintegrität","Kompatibilität mit Mehrfachmaschinen","Übernahme von remote Änderungen","Wartung von Aktualisierungen"],"pt":["Sincronização de código com repositório remoto","Suporte a submodule mcps/internal","Merges conservativos para multi-máquinas","Compatibilidade com roo-extensions","Override de configurações globais"],"ru":["Синхронизация кода с удаленным репозиторием","Поддержка подмодуля mcps/internal","Сохраняющие слияния для много-машин","Совместимость с roo-extensions","Переопределение глобальных настроек"],"ar":["مزامنة الكود مع المستودع البعيد","دعم فرعي mcps/internal","الدمج المحافظ للماكينات المتعددة","التوافق مع roo-extensions","إعادة تعريف الإعدادات العالمية"]},"keywords":{"en":["how to use git-sync","git-sync setup guide","git-sync alternative","git-sync vs git-submodule","git-sync install","what is git-sync","git-sync for AI agents","git-sync synchronization","git-sync for roo-extensions"],"zh":["Git Sync","AIエージェント","roo-extensions","submodule 同步","merges Conservatifs","Git 仓库同步","Override 项目","generic Template","AI 工具"],"ja":["Git Sync","AIエージェント","roo-extensions","submodule 同期","merges Conservatifs","Git リポジトリ同期","Override プロジェクト","generic Template","AI ツール"],"ko":["Git Sync","AI 도구","roo-extensions","submodule 동기화","merges Conservatifs","Git 저장소 동기화","Override 프로젝트","generic Template","AI 에이전트"],"es":["git-sync","sincronización de git","roo-extensions","submodule mcps/internal","merges conservativos","desarrollo de software","herramientas de desarrollo","AI Agentes","git para desarrolladores"],"fr":["git-sync","synchronisation de git","roo-extensions","sous-module mcps/internal","merges conservatifs","développement de logiciels","outils de développement","Agents IA","git pour les développeurs"],"de":["git-sync","Git-Synchronisierung","roo-extensions","Submodul mcps/internal","konservative Merges","Software-Entwicklung","Entwickler-Tools","KI-Agenten","Git für Entwickler"],"pt":["git-sync","sincronização de código","repositório remoto","roo-extensions","mcps/internal","merge conservativo","multi-máquinas","configuração de git-sync"],"ru":["git-sync","синхронизация кода","удаленный репозиторий","roo-extensions","mcps/internal","сохраняющее слияние","много-машин","настройка git-sync","ИИ Агенты"],"ar":["git-sync","مزامنة الكود","المستودع البعيد","roo-extensions","mcps/internal","الدمج المحافظ","الماكينات المتعددة","إعدادات git-sync","أدوات الذكاء الاصطناعي"]}},"owner":"jsboige","repo":"roo-extensions","repoPath":"jsboige/roo-extensions","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.412Z","topics":[],"category":"community","skillMd":{"name":"git-sync","description":"Synchronisation Git pour roo-extensions avec gestion du submodule mcps/internal et résolution manuelle des conflits (multi-machines). Utilise ce skill en début de session, avant de travailler, ou quand un message RooSync signale des commits. Phrase déclencheur : git sync, pull, synchronise, mets à jour le repo.","version":"2.0.0","bodyPreview":"# Skill : Git Sync - Override roo-extensions\n\n> **Override projet** : Surcharge la skill globale `~/.claude/skills/git-sync/SKILL.md`.\n> Template generique : `.claude/configs/skills/git-sync/SKILL.md`\n\nSynchronisation Git pour roo-extensions avec submodule `mcps/internal` et merges conservatifs (multi-machines).\n\n---\n\n## Quand utiliser\n\n- En debut de session pour recuperer les changements distants\n- Pendant un tour de sync (Phase 2)\n- Avant de commencer du travail pour etre a jour\n- Apres recept","body":"# Skill : Git Sync - Override roo-extensions\n\n> **Override projet** : Surcharge la skill globale `~/.claude/skills/git-sync/SKILL.md`.\n> Template generique : `.claude/configs/skills/git-sync/SKILL.md`\n\nSynchronisation Git pour roo-extensions avec submodule `mcps/internal` et merges conservatifs (multi-machines).\n\n---\n\n## Quand utiliser\n\n- En debut de session pour recuperer les changements distants\n- Pendant un tour de sync (Phase 2)\n- Avant de commencer du travail pour etre a jour\n- Apres reception d''un message RooSync signalant des commits\n\n---\n\n## Workflow\n\n### Phase 0 : Grounding Sémantique (Bookend Début)\n\n**OBLIGATOIRE avant toute synchronisation.**\n\n```\ncodebase_search(query: \"git sync submodule conflict merge resolution\", workspace: \"d:\\\\roo-extensions\")\n```\n\nBut : Identifier les patterns de résolution de conflits, les workflows git existants, et les fichiers de configuration submodule.\n\n### Etape 1 : Fetch et analyse\n\n```bash\ngit fetch origin\ngit log HEAD..origin/main --oneline\n```\n\n- Compter les commits entrants\n- Identifier les auteurs et les fichiers modifies\n\n### Etape 2 : Pull conservatif\n\n```bash\ngit pull --no-rebase origin main\n```\n\n**TOUJOURS `--no-rebase`** pour preserver l''historique et eviter les conflits en cascade.\n\n### Etape 3 : Resolution de conflits (si necessaire)\n\nSi des conflits sont detectes :\n\n1. Lister fichiers en conflit (`git status`)\n2. Pour chaque fichier :\n   - Lire avec marqueurs `<<<<<<<`, `=======`, `>>>>>>>`\n   - Analyser les deux versions\n   - Resoudre (garder version recente/complete ou combiner)\n   - Editer pour supprimer les marqueurs\n3. `git add` fichiers resolus\n4. `git commit` (message merge)\n\n**Apres resolution : pusher immediatement** pour debloquer les autres machines.\n\n### Etape 4 : Submodule update\n\n```bash\ngit submodule update --init --recursive\n```\n\nSi le submodule est en conflit ou divergent :\n- Verifier modifications locales (`cd mcps/internal && git status`)\n- Si modifs importantes : `git stash` ou `git commit -m \"wip\"`\n- Sinon : `git checkout -- .` (abandon)\n- Retour repertoire principal\n\n### Etape 5 : Verification finale\n\n```bash\ngit status --short\ngit log --oneline -3\ngit submodule status\n```\n\n### Rapport\n\n```\n## Git Sync Status\n\n### Remote\n- Commits entrants : X\n- Auteurs : [liste]\n\n### Merge\n- Status : Success | Conflits resolus | Conflits non resolus\n- Fichiers modifies : Y\n- Conflits resolus : [liste si applicable]\n\n### Submodule mcps/internal\n- Commit : [hash]\n- Status : Clean | Modified\n\n### Etat actuel\n- Branch : main @ [hash]\n- Pret pour push : Oui | Non (raison)\n```\n\n---\n\n## Commandes de reference\n\n### Status complet\n```bash\ngit status --short && git submodule status\n```\n\n### Derniers commits\n```bash\ngit log --oneline -10\n```\n\n### Commits du submodule\n```bash\ncd mcps/internal && git log --oneline -5\n```\n\n### Preparation commit (sans commiter)\n```bash\ngit diff --stat\ngit status\n```\n\n---\n\n## Regles\n\n- **TOUJOURS** utiliser `--no-rebase` pour preserver l''historique\n- **JAMAIS** de force push\n- **JAMAIS** de `git checkout` ou `git pull` dans le submodule `mcps/internal/` sans verification\n- En cas de conflit, resoudre proprement (ne jamais `git add` a l''aveugle)\n- Les fichiers de config locaux (.claude/local/*) sont ignores par git\n- NE PAS commiter sans instruction explicite de l''utilisateur\n\n---\n\n## Phase 6 : Validation Sémantique (Bookend Fin)\n\n**OBLIGATOIRE après toute synchronisation réussie.**\n\n```\ncodebase_search(query: \"git status submodule synced merged resolved\", workspace: \"d:\\\\roo-extensions\")\n```\n\nBut : Confirmer que l''état de synchronisation est cohérent avec l''index. Vérifier que les fichiers modifiés pendant le sync sont visibles dans les résultats.\n"},"lastSynced":"2026-03-08T02:07:06.403Z","agentAnalysis":{"suitability":{"en":"Perfect for Collaborative Development Agents needing seamless Git repository synchronization across multiple machines.","zh":"非常适合需要在多台机器上实现无缝 Git 仓库同步的协作开发代理。","ja":"マルチマシン間でシームレスなGitリポジトリの同期が必要なコラボレーション開発エージェントに最適です。","ko":"여러 대의 기기 간에 무중단 Git 저장소 동기화를 필요로 하는 협력 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo Colaborativo que necesitan una sincronización sin problemas del repositorio Git en varias máquinas.","fr":"Parfait pour les agents de développement collaboratif nécessitant une synchronisation sans problème du référentiel Git sur plusieurs machines.","de":"Perfekt für Collaborative Development Agents, die eine reibungslose Git-Repository-Synchronisierung auf mehreren Maschinen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Colaborativo que precisam de sincronização de repositório Git sem problemas em várias máquinas.","ru":"Идеально подходит для агентов совместной разработки, требующих бесшовной синхронизации репозитория Git на нескольких машинах.","ar":"مثالي لعميل التطوير التعاوني الذي يحتاج إلى تنسيق مستودع Git بدون مشاكل عبر عدة أجهزة."},"recommendation":{"en":"Empowers agents to synchronize Git repositories with submodule updates, such as `mcps/internal`, and perform conservative merges, ensuring consistent project updates across machines using Git protocols and submodule management.","zh":"赋予代理同步 Git 仓库的能力，包括子模块更新（如 `mcps/internal` ），并执行保守合并，确保在使用 Git 协议和子模块管理的机器上保持项目更新的一致性。","ja":"エージェントにGitリポジトリを同期する機能を付与し、サブモジュールの更新（例： `mcps/internal` ）を含み、保守的マージを実行して、Gitプロトコルとサブモジュール管理を使用するマシンで一貫したプロジェクト更新を保証します。","ko":"에이전트에게 Git 저장소를 동기화할 수 있는 능력을 부여하고, 서브모듈 업데이트를 포함하여(예: `mcps/internal`), 보수적인 병합을 수행하여 Git 프로토콜과 서브모듈 관리를 사용하는 기기에서 프로젝트 업데이트가 일관되게 유지되도록 합니다.","es":"Habilita a los agentes a sincronizar los repositorios Git con actualizaciones de submódulos, como `mcps/internal`, y a realizar fusiones conservadoras, garantizando actualizaciones de proyecto coherentes en varias máquinas utilizando protocolos Git y administración de submódulos.","fr":"Permet aux agents de synchroniser les référentiels Git avec des mises à jour de sous-modules, tels que `mcps/internal`, et de réaliser des fusions conservatrices, garantissant des mises à jour de projet cohérentes sur plusieurs machines en utilisant les protocoles Git et la gestion des sous-modules.","de":"Ermächtigt Agenten, Git-Repositorys mit Submodule-Updates wie `mcps/internal` zu synchronisieren und konservative Merge-Vorgänge durchzuführen, um konsistente Projektaktualisierungen auf mehreren Maschinen mithilfe von Git-Protokollen und Submodule-Verwaltung sicherzustellen.","pt":"Habilita os agentes a sincronizar repositórios Git com atualizações de submódulos, como `mcps/internal`, e realizar mesclas conservadoras, garantindo atualizações de projeto consistentes em máquinas usando protocolos Git e gerenciamento de submódulos.","ru":"Позволяет агентам синхронизировать репозитории Git с обновлениями подмодулей, такими как `mcps/internal`, и выполнять консервативные слияния, обеспечивая последовательные обновления проекта на машинах с использованием протоколов Git и управления подмодулями.","ar":"يتيح للعميل مزامنة مستودعات Git مع تحديثات الفرعية، مثل `mcps/internal`، وإجراء دمج محافظ، مما يضمن تحديثات متسقة للمشروع عبر الأجهزة باستخدام بروتوكولات Git وإدارة الفرعية."},"useCases":{"en":["Synchronizing repositories at the start of a session to retrieve remote changes","Performing sync operations during collaborative project phases","Updating local repositories before beginning work to ensure consistency","Syncing repositories after receiving updates"],"zh":["会话开始时同步仓库以检索远程更改","在协作项目阶段执行同步操作","开始工作前更新本地仓库以确保一致性","接收更新后同步仓库"],"ja":["セッション開始時にリポジトリを同期してリモートの変更を取得する","コラボレーションプロジェクトの段階で同期操作を実行する","作業を開始する前にローカルリポジトリを更新して一貫性を確保する","更新を受信した後にリポジトリを同期する"],"ko":["세션이 시작할 때 원격 변경 사항을 가져오기 위해 저장소를 동기화하는 것","협력 프로젝트 단계에서 동기화 작업을 수행하는 것","일관성을 보장하기 위해 작업을 시작하기 전에 로컬 저장소를 업데이트하는 것","업데이트를 받은 후 저장소를 동기화하는 것"],"es":["Sincronizar repositorios al comienzo de una sesión para recuperar cambios remotos","Realizar operaciones de sincronización durante fases de proyecto colaborativo","Actualizar repositorios locales antes de comenzar a trabajar para garantizar la coherencia","Sincronizar repositorios después de recibir actualizaciones"],"fr":["Synchroniser les référentiels au début d''une session pour récupérer les modifications distantes","Effectuer des opérations de synchronisation pendant les phases de projet collaboratif","Mettre à jour les référentiels locaux avant de commencer à travailler pour assurer la cohérence","Synchroniser les référentiels après avoir reçu des mises à jour"],"de":["Repositorys am Anfang einer Sitzung synchronisieren, um Remote-Änderungen abzurufen","Synchronisierungsoperationen während der Phasen des Collaborative-Projekts durchführen","Lokale Repositorys vor Beginn der Arbeit aktualisieren, um Konsistenz sicherzustellen","Repositorys nach Erhalt von Aktualisierungen synchronisieren"],"pt":["Sincronizar repositórios no início de uma sessão para recuperar alterações remotas","Realizar operações de sincronização durante fases de projeto colaborativo","Atualizar repositórios locais antes de iniciar o trabalho para garantir a consistência","Sincronizar repositórios após receber atualizações"],"ru":["Синхронизировать репозитории в начале сессии для получения удаленных изменений","Выполнять операции синхронизации во время фаз совместного проекта","Обновлять локальные репозитории перед началом работы для обеспечения согласованности","Синхронизировать репозитории после получения обновлений"],"ar":["مزامنة المستودعات في بداية الجلسة لاسترجاع التغييرات عن بعد","إجراء عمليات المزامنة خلال مراحل المشروع التعاوني","تحديث المستودعات المحلية قبل البدء في العمل لضمان الاتساق","مزامنة المستودعات بعد استلام التحديثات"]},"limitations":{"en":["Requires Git installation and configuration","Limited to Git repositories with submodule support","Needs read/write access to repository directories"],"zh":["需要 Git 的安装和配置","仅限于具有子模块支持的 Git 仓库","需要对仓库目录具有读写访问权限"],"ja":["Gitのインストールと設定が必要","サブモジュールをサポートするGitリポジトリのみ","リポジトリディレクトリに対する読み取り/書き込みアクセスが必要"],"ko":["Git 설치 및 구성이 필요함","서브모듈을 지원하는 Git 저장소에만 해당함","저장소 디렉토리에 대한 읽기/쓰기 접근 권한이 필요함"],"es":["Requiere instalación y configuración de Git","Limitado a repositorios Git con compatibilidad de submódulos","Necesita acceso de lectura y escritura a los directorios del repositorio"],"fr":["Nécessite l''installation et la configuration de Git","Limité aux référentiels Git avec prise en charge des sous-modules","Nécessite un accès en lecture et en écriture aux répertoires du référentiel"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf Git-Repositorys mit Submodule-Unterstützung","Benötigt Lese- und Schreibzugriff auf Repository-Verzeichnisse"],"pt":["Requer instalação e configuração do Git","Limitado a repositórios Git com suporte a submódulos","Necessita de acesso de leitura/escrita aos diretórios do repositório"],"ru":["Требует установки и настройки Git","Ограничен репозиториями Git с поддержкой подмодулей","Требует доступа на чтение/запись к директориям репозитория"],"ar":["يتطلب تثبيت وتكوين Git","محدود بمستودعات Git التي تدعم الفرعية","يحتاج إلى وصول للقراءة/الكتابة إلى دليل المستودع"]},"version":4},"contentHash":"e6fb766d5d40ff11869452b34b86f6d4ca5cdef0b74239bd4ee233c51e1f2d5a","qualityScore":41}');
