INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jsboige/roo-extensions/git-sync', 'git-sync', 'jsboige', 'roo-extensions', 'community', 'git-sync jsboige roo-extensions community The git-sync skill enables AI agents to synchronize Git repositories, ensuring consistent project updates across multiple machines. It benefits developers working on collaborative projects with roo-extensions. Git Sync 是用于 roo-extensions 的 submodule 和 merges Conservatifs 同步工具 Git Sync は roo-extensions 用の submodule と merges Conservatifs 同期ツールです Git Sync는 roo-extensions용 submodule 및 merges Conservatifs 동기화 도구입니다 Git-sync es una habilidad para sincronizar cambios en roo-extensions con submodule mcps/internal y merges conservativos. Es útil para recuperar cambios remotos y mantener actualizados Git-sync est une compétence pour synchroniser les modifications dans roo-extensions avec le submodule mcps/internal et les merges conservatifs. Elle est utile pour récupérer les modifications distantes et rester à jour Git-sync ist eine Fähigkeit zur Synchronisierung von Änderungen in roo-extensions mit dem Submodul mcps/internal und konservativen Merges. Sie ist nützlich, um remote Änderungen zu übernehmen und auf dem neuesten Stand zu bleiben O Git-Sync é uma ferramenta de sincronização de código que permite atualizar seu projeto com as últimas alterações do repositório remoto Git-Sync - это инструмент синхронизации кода, который позволяет обновить проект с последними изменениями из удаленного репозитория с помощью ИИ Агентов Git-Sync هو أداة مزامنة الكود التي تمكنك من تحديث مشروعك بأحدث التغييرات من المستودع البعيد مع أدوات الذكاء الاصطناعي how to use git-sync git-sync setup guide git-sync alternative git-sync vs git-submodule git-sync install what is git-sync git-sync for AI agents git-sync synchronization git-sync for roo-extensions Git Sync AIエージェント roo-extensions submodule 同步 merges Conservatifs Git 仓库同步 Override 项目 generic Template AI 工具 Overrides global skills using ~/.claude/skills/git-sync/SKILL.md Utilizes submodule synchronization with mcps/internal Performs conservative merges for multi-machine environments Supports synchronization during session startup and phase 2 sync Enables updates retrieval before starting work Automates synchronization after receiving updates git-sync is a skill that provides Git synchronization for roo-extensions, utilizing submodule synchronization and conservative merges.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fredeschmidt/byg-nemt-selv/update-skill', 'community', 'fredeschmidt', 'byg-nemt-selv', 'fredeschmidt/byg-nemt-selv', 'update-skill', 0, 0, 41, '2026-03-08T01:57:15.419Z', '2026-03-08T02:07:22.089Z', '710cdd10473db9e3d2ca998198cb49fe18835515bec3494a41bc7ce568444cdd', '{"id":"fredeschmidt/byg-nemt-selv/update-skill","name":"update-skill","description":{"en":"The update-skill is an AI agent capability that modifies SKILL.md and AGENTS.md files by integrating updates into the existing structure. It benefits developers and technical writers maintaining clean, non-duplicative AI agent documentation.","zh":"更新技能是AIエージェント中的一个重要技能，用于更新SKILL.md和AGENTS.md文件","ja":"更新スキルはAIエージェントにおける重要なスキルであり、SKILL.mdとAGENTS.mdファイルを更新するために使用される","ko":"업데이트 스킬은 AI 에이전트에서 중요한 스킬로, SKILL.md와 AGENTS.md 파일을 업데이트하는 데 사용됩니다","es":"La habilidad de actualización permite a los usuarios actualizar archivos como SKILL.md y AGENTS.md de manera clara y concisa, integrando cambios de forma lógica","fr":"La compétence de mise à jour permet aux utilisateurs de mettre à jour des fichiers tels que SKILL.md et AGENTS.md de manière claire et concise, en intégrant les modifications de façon logique","de":"Die Aktualisierungsfähigkeit ermöglicht es Benutzern, Dateien wie SKILL.md und AGENTS.md klar und präzise zu aktualisieren, indem Änderungen logisch integriert werden","pt":"O update-skill é uma habilidade que ajuda a manter as instruções claras e concisas, integrando atualizações de forma lógica.","ru":"ИИ Агенты: Update Skill - это навык, который помогает поддерживать инструкции краткими и ясными, интегрируя обновления логично.","ar":"مهارة التحديث هي قدرة تساعد على الحفاظ على الإرشادات واضحة وموجزة، مع دمج التحديثات بطريقة منطقية."},"seo":{"title":{"en":"update-skill: Clean AI Agent File Updates | AI Agent Skill","zh":"更新技能设置指南 - AIエージェント整合","ja":"AIエージェントの更新スキルセットアップガイド","ko":"AI 에이전트 업데이트 스킬 설정 가이드","es":"Guía de Configuración para Actualizar Habilidades de Agen...","fr":"Guide de Configuration pour la Mise à Jour des Compétence...","de":"Konfigurationsleitfaden für die Aktualisierung von KI-Age...","pt":"Guia de Configuração do Update Skill para Ferramentas de IA","ru":"Настройка ИИ Агентов: Руководство по Update Skill","ar":"دليل إعداد مهارة التحديث لآلات الية الذكية"},"description":{"en":"Learn how update-skill intelligently updates SKILL.md & AGENTS.md files without losing original intent. This AI agent skill integrates changes logically inst...","zh":"了解更新技能的最佳实践，整合更新到全技能流中，保持指令简洁清晰","ja":"AIエージェントの更新スキルを最適化するためのベストプラクティスを学ぶ","ko":"AI 에이전트 업데이트 스킬을 최적화하는 방법에 대한 정보를 제공합니다","es":"Aprende a actualizar habilidades de agentes de IA de manera eficiente con nuestras mejores prácticas y reglas para una integración sin problemas","fr":"Découvrez comment mettre à jour les compétences des agents IA de manière efficace avec nos meilleures pratiques et règles pour une intégration sans problème","de":"Erfahren Sie, wie Sie KI-Agentenfähigkeiten effizient aktualisieren können, mit unseren Best Practices und Regeln für eine problemlose Integration","pt":"Aprenda a usar o update-skill para manter suas instruções claras e atualizadas, integrando mudanças de forma lógica e sem perda de intenção.","ru":"Узнайте, как использовать update-skill для поддержания инструкций в актуальном состоянии, интегрируя изменения логично и без потери смысла.","ar":"تعرف على كيفية استخدام مهارة التحديث للاحتفاظ بتعليمات واضحة ومحدّثة، مع دمج التغييرات بطريقة منطقية ودون فقدان النية."},"definition":{"en":"update-skill is an AI agent capability that handles user requests to update SKILL.md or AGENTS.md files. It ensures instructions remain short, clear, and integrated by reading entire files before making logical, non-duplicative edits.","zh":"更新技能是一种AIエージェント技能，用于更新和整合SKILL.md和AGENTS.md文件","ja":"更新スキルは、SKILL.mdとAGENTS.mdファイルを更新し整合するAIエージェントスキルの一種","ko":"업데이트 스킬은 SKILL.md와 AGENTS.md 파일을 업데이트하고 통합하는 AI 에이전트 스킬입니다","es":"La habilidad de actualización es una función que permite a los usuarios actualizar archivos de habilidades de agentes de IA de manera eficiente","fr":"La compétence de mise à jour est une fonctionnalité qui permet aux utilisateurs de mettre à jour des fichiers de compétences des agents IA de manière efficace","de":"Die Aktualisierungsfähigkeit ist eine Funktion, die es Benutzern ermöglicht, KI-Agentenfähigkeitsdateien effizient zu aktualisieren","pt":"O que é update-skill? É uma habilidade que atualiza arquivos de habilidades e agentes de forma eficiente.","ru":"Что такое Update Skill? Это навык, который обновляет файлы навыков и ИИ Агентов эффективно.","ar":"ما هي مهارة التحديث؟ هي قدرة تحدث ملفات المهارات والوكلاء الاصطناعيين بطريقة فعالة."},"features":{"en":["Reads entire target SKILL.md file before editing","Parses relevant AGENTS.md files for context prior to updates","Places changes in logical locations within the document structure","Removes or merges redundant content to prevent duplication","Maintains original user intent while cleaning file content"],"zh":["读取整个目标技能文件 trước編輯","读取相关文件（例如AGENTS.md）前編輯","将更改放在逻辑上属于的地方","删除或合并重复的指令"],"ja":["ターゲットスキルファイルを全部読み込む前に編集","関連ファイル（例：AGENTS.md）を読み込む前に編集","変更を論理的に属する場所に配置","重複した指令を削除または統合"],"ko":["대상 스킬 파일 전체를 읽은 후 편집","관련 파일(예: AGENTS.md)을 읽은 후 편집","변경을 논리적으로 속한 곳에 배치","중복된 지시를 삭제 또는 통합"],"es":["Lectura de archivos de habilidades antes de la edición","Integración de cambios en el flujo de habilidades completo","Eliminación o fusión de instrucciones duplicadas","Colocación de cambios en la ubicación lógica","Compatibilidad con archivos como SKILL.md y AGENTS.md"],"fr":["Lecture de fichiers de compétences avant l''édition","Intégration des modifications dans le flux de compétences complet","Élimination ou fusion d''instructions dupliquées","Placement des modifications à l''emplacement logique","Compatibilité avec des fichiers tels que SKILL.md et AGENTS.md"],"de":["Lesevorgang für Fähigkeitsdateien vor der Bearbeitung","Integration von Änderungen in den vollständigen Fähigkeitsfluss","Entfernen oder Zusammenführen von duplizierten Anweisungen","Platzierung von Änderungen an der logischen Position","Kompatibilität mit Dateien wie SKILL.md und AGENTS.md"],"pt":["Leitura de arquivos de habilidades e agentes antes de editar","Integração de atualizações de forma lógica e sem perda de intenção","Remoção ou mesclagem de instruções duplicadas","Manutenção de instruções claras e concisas","Compatibilidade com tecnologias como React e Python"],"ru":["Чтение файлов навыков и ИИ Агентов перед редактированием","Интеграция обновлений логично и без потери смысла","Удаление или слияние дублирующихся инструкций","Поддержание инструкций краткими и ясными","Совместимость с технологиями như React и Python"],"ar":["قراءة ملفات المهارات والوكلاء الاصطناعيين قبل التعديل","دمج التحديثات بطريقة منطقية ودون فقدان النية","إزالة أو دمج الإرشادات المكررة","الحفاظ على الإرشادات واضحة وموجزة","التوافق مع التكنولوجيا مثل React و Python"]},"keywords":{"en":["how to use update-skill","update-skill vs manual editing","update-skill install guide","what is update-skill","update-skill for AGENTS.md","update-skill alternative","SKILL.md update automation","AI agent documentation skills","update-skill setup tutorial"],"zh":["AIエージェント更新技能","SKILL.md更新","AGENTS.md更新","AI工具更新","更新技能设置","AIエージェント整合"],"ja":["AIエージェント更新スキル","SKILL.md更新","AGENTS.md更新","AIツール更新","更新スキルセットアップ","AIエージェント統合"],"ko":["AI 에이전트 업데이트 스킬","SKILL.md 업데이트","AGENTS.md 업데이트","AI 툴 업데이트","업데이트 스킬 설정","AI 에이전트 통합"],"es":["actualización de habilidades de agentes de IA","configuración de agentes de IA","mejores prácticas para la actualización de habilidades","integración de cambios en habilidades de agentes de IA","edición de archivos de habilidades","agentes de IA","herramientas de IA"],"fr":["mise à jour des compétences des agents IA","configuration des agents IA","meilleures pratiques pour la mise à jour des compétences","intégration des modifications dans les compétences des agents IA","édition de fichiers de compétences","agents IA","outils IA"],"de":["Aktualisierung von KI-Agentenfähigkeiten","Konfiguration von KI-Agents","Best Practices für die Aktualisierung von Fähigkeiten","Integration von Änderungen in KI-Agentenfähigkeiten","Bearbeitung von Fähigkeitsdateien","KI-Agents","KI-Tools"],"pt":["update-skill","ferramentas de ia","desenvolvimento de habilidades","integração de atualizações","manutenção de instruções","react","python","cli"],"ru":["update-skill","ии агенты","разработка навыков","интеграция обновлений","поддержание инструкций","react","python","cli"],"ar":["مهارة التحديث","آلات الية الذكية","تطوير المهارات","دمج التحديثات","صيانة الإرشادات","react","python","cli"]}},"owner":"fredeschmidt","repo":"byg-nemt-selv","repoPath":"fredeschmidt/byg-nemt-selv","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.419Z","topics":[],"category":"community","skillMd":{"name":"update-skill","description":"Update existing skills while keeping them simple, coherent, and non-duplicative; always recommend the best placement for new rules.","bodyPreview":"# Update Skill\n\nUse this skill when a user asks to update `SKILL.md` or `AGENTS.md` and wants the result cleaner without losing intent.\n\n## Goal\n\nKeep instructions short, clear, and non-duplicative.\nIntegrate updates into the full skill flow, not as isolated add-ons.\n\n## Required Rules\n\n1. Read the whole target skill file before editing.\n2. Read relevant related files (for example `AGENTS.md`) before editing.\n3. Place changes where they logically belong; do not append blindly.\n4. Remove or merge","body":"# Update Skill\n\nUse this skill when a user asks to update `SKILL.md` or `AGENTS.md` and wants the result cleaner without losing intent.\n\n## Goal\n\nKeep instructions short, clear, and non-duplicative.\nIntegrate updates into the full skill flow, not as isolated add-ons.\n\n## Required Rules\n\n1. Read the whole target skill file before editing.\n2. Read relevant related files (for example `AGENTS.md`) before editing.\n3. Place changes where they logically belong; do not append blindly.\n4. Remove or merge overlaps and repeated wording.\n5. Keep sections short, headings predictable, and language direct.\n6. Preserve behavioral intent when refactoring.\n\n## Placement Decision (Mandatory)\n\nRecommend the best location before editing, even if the user named a file.\n\nChoose in this order:\n\n1. Existing skill, existing section (best).\n2. Existing skill, new section (if concept is new but belongs there).\n3. Different existing skill (if concern belongs elsewhere).\n4. New skill (only if reusable and it does not fit existing skills cleanly).\n\nIf the requested file is a poor fit, state:\n1. Why it is a mismatch.\n2. Which file is better.\n3. Whether to move or duplicate (default: move).\n\nRecommend a new skill only when all are true:\n1. The rule is reusable across multiple skills.\n2. It defines a distinct workflow.\n3. Adding it to an existing skill would cause clutter.\n\n## Workflow\n\n1. Parse the requested update.\n2. Read all relevant file(s) end-to-end.\n3. Identify duplication, conflicts, and wording drift.\n4. Give placement recommendation with rationale.\n5. Apply edit in the chosen location.\n6. Refactor nearby text for flow and consistency.\n7. Run a cleanup pass: deduplicate, normalize terms, tighten sections.\n8. Report outcome clearly.\n\n## Output Requirements\n\nReport:\n\n1. Placement recommendation and reason.\n2. Files changed.\n3. Cleanup performed.\n4. Remaining ambiguity and recommended next step.\n"},"lastSynced":"2026-03-08T02:07:22.089Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Writing Agents needing to maintain clean and non-duplicative documentation files like SKILL.md and AGENTS.md","zh":"适用于需要维护干净且无重复文档文件的技术写作代理，例如SKILL.md和AGENTS.md","ja":"技術文章作成エージェントがクリーンで重複のないドキュメントファイルを維持する必要がある場合に最適です。例えば、SKILL.mdやAGENTS.mdなど","ko":"청소와 중복 없는 문서 파일을 유지해야 하는 기술 글쓰기 에이전트에 적합합니다. 예를 들어, SKILL.md와 AGENTS.md","es":"Ideal para Agentes de Escritura Técnica que necesitan mantener archivos de documentación limpios y no duplicados como SKILL.md y AGENTS.md","fr":"Idéal pour les agents de rédaction technique ayant besoin de maintenir des fichiers de documentation propres et non duplicatifs comme SKILL.md et AGENTS.md","de":"Ideal für technische Schreibagenten, die saubere und nicht duplizierende Dokumentationsdateien wie SKILL.md und AGENTS.md pflegen müssen","pt":"Ideal para Agentes de Redação Técnica que precisam manter arquivos de documentação limpos e não duplicativos, como SKILL.md e AGENTS.md","ru":"Идеально для Технических Агентов по Написанию, которым необходимо поддерживать чистые и не дублирующие документы, такие как SKILL.md и AGENTS.md","ar":"مثالي لعميل الكتابة الفنية الذي يحتاج إلى الحفاظ على ملفات توثيق نظيفة وغیر مكررة مثل SKILL.md و AGENTS.md"},"recommendation":{"en":"Empowers agents to integrate updates into existing documentation structures, ensuring instructions remain short, clear, and non-duplicative, while leveraging file formats like .md and protocols for seamless information flow","zh":"赋予代理将更新集成到现有的文档结构中，确保说明保持简短、清晰和无重复，同时利用文件格式如.md和协议实现无缝信息流","ja":"エージェントが更新を既存のドキュメント構造に統合できるようにし、説明が短く、明確で重複しないまま、.mdなどのファイル形式やプロトコルを利用して情報の流れをスムーズにする","ko":"에이전트가 기존의 문서 구조에 업데이트를 통합할 수 있도록 하여 설명이 짧고, 명확하고 중복되지 않게 유지하도록 하며, .md와 같은 파일 형식 및 프로토콜을 활용하여 정보 흐름을 원활하게 합니다.","es":"Permite a los agentes integrar actualizaciones en las estructuras de documentación existentes, garantizando que las instrucciones permanezcan breves, claras y no duplicadas, al mismo tiempo que aprovechan formatos de archivo como .md y protocolos para un flujo de información sin problemas","fr":"Permet aux agents d''intégrer des mises à jour dans les structures de documentation existantes, en garantissant que les instructions restent courtes, claires et non duplicatives, tout en exploitant des formats de fichiers comme .md et des protocoles pour un flux d''informations sans problème","de":"Ermächtigt Agenten, Updates in bestehende Dokumentationsstrukturen zu integrieren, sodass Anweisungen kurz, klar und nicht dupliziert bleiben, während Dateiformate wie .md und Protokolle für einen reibungslosen Informationsfluss genutzt werden","pt":"Habilita os agentes a integrar atualizações nas estruturas de documentação existentes, garantindo que as instruções permaneçam curtas, claras e não duplicativas, aproveitando formatos de arquivo como .md e protocolos para um fluxo de informações sem interrupções","ru":"Наделяет агентов возможностью интегрировать обновления в существующие структуры документации, гарантируя, что инструкции остаются короткими, ясными и не дублирующими, используя форматы файлов, такие как .md, и протоколы для бесперебойного потока информации","ar":"يُمكّن الوكيل من دمج التحديثات في الهياكل الوثائقية الحالية، مع ضمان بقاء الإرشادات قصيرة وواضحة وغیر مكررة، مع الاستفادة من صيغ الملفات مثل .md والبروتوكولات من أجل تدفق المعلومات دون انقطاع"},"useCases":{"en":["Updating SKILL.md files with new capabilities","Merging duplicate entries in AGENTS.md","Reorganizing documentation for clarity and readability"],"zh":["使用新功能更新SKILL.md文件","合并AGENTS.md中的重复条目","重新组织文档以提高清晰度和可读性"],"ja":["新しい機能でSKILL.mdファイルを更新する","AGENTS.mdの重複エントリをマージする","ドキュメントを再構成して明確性と可読性を高める"],"ko":["새로운 기능으로 SKILL.md 파일을 업데이트하는 것","AGENTS.md의 중복 항목을 병합하는 것","문서를 재구성하여 명확성과 가독성을 높이는 것"],"es":["Actualización de archivos SKILL.md con nuevas capacidades","Fusión de entradas duplicadas en AGENTS.md","Reorganización de la documentación para mejorar la claridad y la legibilidad"],"fr":["Mise à jour des fichiers SKILL.md avec de nouvelles capacités","Fusion d''entrées dupliquées dans AGENTS.md","Réorganisation de la documentation pour améliorer la clarté et la lisibilité"],"de":["Aktualisierung von SKILL.md-Dateien mit neuen Fähigkeiten","Zusammenführung von doppelten Einträgen in AGENTS.md","Neuorganisation der Dokumentation zur Verbesserung von Klarheit und Lesbarkeit"],"pt":["Atualizar arquivos SKILL.md com novas capacidades","Mesclar entradas duplicadas em AGENTS.md","Reorganizar a documentação para clareza e legibilidade"],"ru":["Обновлять файлы SKILL.md с новыми возможностями","Объединять дублирующие записи в AGENTS.md","Перестраивать документацию для ясности и читаемости"],"ar":["تحديث ملفات SKILL.md بسمات جديدة","دمج المدخلات المكررة في AGENTS.md","إعادة تنظيم الوثائق من أجل الوضوح والقابلية للقراءة"]},"limitations":{"en":["Requires access to SKILL.md and AGENTS.md files","Limited to markdown file formats"],"zh":["需要访问SKILL.md和AGENTS.md文件","仅限于markdown文件格式"],"ja":["SKILL.mdファイルとAGENTS.mdファイルへのアクセスが必要","マークダウンファイル形式のみに限定"],"ko":["SKILL.md 파일과 AGENTS.md 파일에 대한 액세스가 필요함","마크다운 파일 형식만으로 제한됨"],"es":["Requiere acceso a los archivos SKILL.md y AGENTS.md","Limitado a formatos de archivo markdown"],"fr":["Requiert un accès aux fichiers SKILL.md et AGENTS.md","Limité aux formats de fichiers markdown"],"de":["Benötigt Zugriff auf die Dateien SKILL.md und AGENTS.md","Begrenzt auf Markdown-Dateiformate"],"pt":["Requer acesso aos arquivos SKILL.md e AGENTS.md","Limitado a formatos de arquivo markdown"],"ru":["Требует доступа к файлам SKILL.md и AGENTS.md","Ограничен форматами файлов markdown"],"ar":["يتطلب الوصول إلى ملفات SKILL.md و AGENTS.md","محدود بصيغ الملفات markdown"]},"version":4},"contentHash":"710cdd10473db9e3d2ca998198cb49fe18835515bec3494a41bc7ce568444cdd","qualityScore":41}');
