INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fredeschmidt/byg-nemt-selv/update-skill', 'update-skill', 'fredeschmidt', 'byg-nemt-selv', 'community', 'update-skill fredeschmidt byg-nemt-selv community The update-skill is an AI agent capability that modifies SKILL.md and AGENTS.md files by integrating updates into the existing structure. It benefits developers and technical writers maintaining clean, non-duplicative AI agent documentation. 更新技能是AIエージェント中的一个重要技能，用于更新SKILL.md和AGENTS.md文件 更新スキルはAIエージェントにおける重要なスキルであり、SKILL.mdとAGENTS.mdファイルを更新するために使用される 업데이트 스킬은 AI 에이전트에서 중요한 스킬로, SKILL.md와 AGENTS.md 파일을 업데이트하는 데 사용됩니다 La habilidad de actualización permite a los usuarios actualizar archivos como SKILL.md y AGENTS.md de manera clara y concisa, integrando cambios de forma lógica La compétence de mise à jour permet aux utilisateurs de mettre à jour des fichiers tels que SKILL.md et AGENTS.md de manière claire et concise, en intégrant les modifications de façon logique Die Aktualisierungsfähigkeit ermöglicht es Benutzern, Dateien wie SKILL.md und AGENTS.md klar und präzise zu aktualisieren, indem Änderungen logisch integriert werden O update-skill é uma habilidade que ajuda a manter as instruções claras e concisas, integrando atualizações de forma lógica. ИИ Агенты: Update Skill - это навык, который помогает поддерживать инструкции краткими и ясными, интегрируя обновления логично. مهارة التحديث هي قدرة تساعد على الحفاظ على الإرشادات واضحة وموجزة، مع دمج التحديثات بطريقة منطقية. how to use update-skill update-skill vs manual editing update-skill install guide what is update-skill update-skill for AGENTS.md update-skill alternative SKILL.md update automation AI agent documentation skills update-skill setup tutorial AIエージェント更新技能 SKILL.md更新 AGENTS.md更新 AI工具更新 更新技能设置 AIエージェント整合 Reads entire target SKILL.md file before editing Parses relevant AGENTS.md files for context prior to updates Places changes in logical locations within the document structure Removes or merges redundant content to prevent duplication Maintains original user intent while cleaning file content update-skill is an AI agent capability that handles user requests to update SKILL.md or AGENTS.md files. It ensures instructions remain short, clear, and integrated by reading entire files before making logical, non-duplicative edits.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lolopinto/ent/git-pr-changelog', 'community', 'lolopinto', 'ent', 'lolopinto/ent', 'git-pr-changelog', 0, 0, 41, '2026-03-08T01:57:15.437Z', '2026-03-08T02:07:39.257Z', '63a16980624bb0424ed0a0427bac2fca94ad663de86423679842cb87bcaeeab6', '{"id":"lolopinto/ent/git-pr-changelog","name":"git-pr-changelog","description":{"en":"The git-pr-changelog skill automates the standard Git PR and changelog workflow for developers, executing tasks like verifying repo state and updating CHANGELOG.md. It benefits developers by simplifying their Git workflow.","zh":"Git PR + Changelog 工作流程自动化代码提交和更新 CHANGELOG.md。通过 Git 命令行工具执行标准流程。","ja":"Git PR + Changelog ワークフローは、コードの提交と CHANGELOG.md の更新を自動化する AI エージェントです。","ko":"Git PR + Changelog 워크플로우는 코드 제출과 CHANGELOG.md 업데이트를 자동화하는 AI 도구입니다.","es":"El agente git-pr-changelog automatiza el flujo de trabajo de Git, incluyendo la verificación del estado del repositorio, la creación de confirmaciones y la actualización del archivo CHANGELOG.md","fr":"L''agent git-pr-changelog automatise le flux de travail Git, y compris la vérification de l''état du référentiel, la création de validations et la mise à jour du fichier CHANGELOG.md","de":"Der git-pr-changelog-Agent automatisiert den Git-Workflow, einschließlich der Überprüfung des Repository-Zustands, der Erstellung von Commits und der Aktualisierung der Datei CHANGELOG.md","pt":"O git-pr-changelog é uma ferramenta que automatiza o fluxo de trabalho de PR e Changelog no GitHub. Ele executa o fluxo padrão de verificação do estado do repositório, stage de alterações, commit, push, abertura de PR e atualização do CHANGELOG.md.","ru":"git-pr-changelog - это инструмент, который автоматизирует работу с PR и Чangelog в GitHub. Он выполняет стандартный поток проверки состояния репозитория, stage изменений, commit, push, открытия PR и обновления CHANGELOG.md для ИИ Агентов","ar":"git-pr-changelog هو أداة لتسريع سير العمل لإعداد.setRequest و سجل التغييرات في GitHub. يقوم بتنفيذ سير العمل القياسي لتحقق حالة المستودع ومرحلة التغييرات والالتزام والدفع وفتح طلبات السحب وتحديث CHANGELOG.md"},"seo":{"title":{"en":"git-pr-changelog: Automated Git PR and Changelog Workflow...","zh":"Git PR + Changelog 工作流程设置指南","ja":"Git PR + Changelog ワークフロー ベストプラクティス - AIエージェント","ko":"Git PR + Changelog 워크플로우 설정 가이드 - AI 도구","es":"Guía de configuración de git-pr-changelog para flujos de ...","fr":"Guide de mise en place de git-pr-changelog pour les flux ...","de":"Einrichtungsleitfaden für git-pr-changelog-Workflows in Git","pt":"Guia de Configuração do git-pr-changelog: Fluxo de Trabal...","ru":"Настройка git-pr-changelog: Работа с PR и Чangelog для ИИ...","ar":"دليل إعداد git-pr-changelog: سير عمل إعداد.setRequest و س..."},"description":{"en":"Streamline your Git workflow with git-pr-changelog. Learn how to automate PR and changelog updates. Get started now and optimize your development process!","zh":"了解 Git PR + Changelog 工作流程的设置和优化，自动化代码提交和更新 CHANGELOG.md","ja":"Git PR + Changelog ワークフローを自動化する方法を学び、開発効率を向上させます - AIエージェント","ko":"Git PR + Changelog 워크플로우를 설정하고 최적화하여 코드 제출과 CHANGELOG.md 업데이트를 자동화합니다 - AI 도구","es":"Aprende a implementar git-pr-changelog para automatizar flujos de trabajo de Git y mantener un registro de cambios actualizado","fr":"Découvrez comment mettre en place git-pr-changelog pour automatiser les flux de travail Git et maintenir un journal des modifications à jour","de":"Erfahren Sie, wie Sie git-pr-changelog einrichten, um Git-Workflows zu automatisieren und ein aktuelles Änderungsprotokoll zu pflegen","pt":"Aprenda a configurar o git-pr-changelog para automatizar o fluxo de trabalho de PR e Changelog no GitHub","ru":"Узнайте, как настроить git-pr-changelog для автоматизации работы с PR и Чangelog в GitHub с помощью ИИ Агентов","ar":"تعلم كيفية إعداد git-pr-changelog لتسريع سير العمل لإعداد.setRequest و سجل التغييرات في GitHub"},"definition":{"en":"git-pr-changelog is a skill that automates the Git PR and changelog workflow, including verifying repository state, staging changes, and updating CHANGELOG.md with PR numbers.","zh":"Git PR + Changelog 工作流程是一种自动化代码提交和更新 CHANGELOG.md 的方法","ja":"Git PR + Changelog ワークフローは、コードの提交と CHANGELOG.md の更新を自動化するワークフローです","ko":"Git PR + Changelog 워크플로우는 코드 제출과 CHANGELOG.md 업데이트를 자동화하는 워크플로우입니다","es":"git-pr-changelog es un agente que automatiza el flujo de trabajo de Git, combinando la creación de solicitudes de extracción con la actualización del registro de cambios","fr":"git-pr-changelog est un agent qui automatise le flux de travail Git, en combinant la création de demandes d''extraction avec la mise à jour du journal des modifications","de":"git-pr-changelog ist ein Agent, der den Git-Workflow automatisiert, indem er die Erstellung von Pull-Requests mit der Aktualisierung des Änderungsprotokolls kombiniert","pt":"O git-pr-changelog é uma ferramenta de automação que integra o fluxo de trabalho de PR e Changelog no GitHub","ru":"git-pr-changelog - это инструмент автоматизации, который интегрирует работу с PR и Чangelog в GitHub для ИИ Агентов","ar":"git-pr-changelog هو أداة أتمتة لتسريع سير العمل لإعداد.setRequest و سجل التغييرات في GitHub"},"features":{"en":["Executes standard Git flow: verify repo state, stage changes, commit, push, and open PR","Updates CHANGELOG.md with PR numbers","Uses Git commands like git rev-parse and git status to inspect repository state","Stages specific files requested by the user, leaving unrelated changes untouched","Checks remotes using git remote -v and confirms repo root with git rev-parse --show-toplevel"],"zh":["自动化代码提交","更新 CHANGELOG.md","Git 命令行工具集成","支持多个 Git 分支","自动检测仓库状态"],"ja":["コードの自動提交","CHANGELOG.md の更新","Git コマンドラインツールとの統合","複数の Git ブランチのサポート","リポジトリ状態の自動検出"],"ko":["코드 제출 자동화","CHANGELOG.md 업데이트","Git 명령줄 도구 통합","다중 Git 브랜치 지원","仓库 상태 자동 검출"],"es":["Verificación del estado del repositorio con git rev-parse","Creación de confirmaciones con git commit","Actualización del archivo CHANGELOG.md con el número de la solicitud de extracción","Soporte para la creación de solicitudes de extracción en GitHub","Integración con la línea de comandos de Git para una mayor flexibilidad"],"fr":["Vérification de l''état du référentiel avec git rev-parse","Création de validations avec git commit","Mise à jour du fichier CHANGELOG.md avec le numéro de la demande d''extraction","Prise en charge de la création de demandes d''extraction sur GitHub","Intégration avec la ligne de commande Git pour une plus grande flexibilité"],"de":["Überprüfung des Repository-Zustands mit git rev-parse","Erstellung von Commits mit git commit","Aktualisierung der Datei CHANGELOG.md mit der Pull-Request-Nummer","Unterstützung für die Erstellung von Pull-Requests auf GitHub","Integration mit der Git-Kommandozeile für eine größere Flexibilität"],"pt":["Verificação do estado do repositório com `git rev-parse --show-toplevel`","Stage de alterações com `git status -sb`","Commit e push com `git commit` e `git push`","Abertura de PR com `git request-pull`","Atualização do CHANGELOG.md com o número do PR"],"ru":["Проверка состояния репозитория с помощью `git rev-parse --show-toplevel`","Stage изменений с помощью `git status -sb`","Commit и push с помощью `git commit` и `git push`","Открытие PR с помощью `git request-pull`","Обновление CHANGELOG.md с номером PR для ИИ Агентов"],"ar":["التحقق من حالة المستودع باستخدام `git rev-parse --show-toplevel`","مرحلة التغييرات باستخدام `git status -sb`","الالتزام والدفع باستخدام `git commit` و `git push`","فتح طلبات السحب باستخدام `git request-pull`","تحديث CHANGELOG.md برقم طلب السحب"]},"keywords":{"en":["how to use git-pr-changelog","git-pr-changelog setup guide","git-pr-changelog alternative","git-pr-changelog vs GitHub workflow","automating Git PR and changelog","git-pr-changelog install","what is git-pr-changelog","git-pr-changelog workflow automation","git-pr-changelog for developers"],"zh":["Git PR","Changelog 工作流程","代码提交自动化","CHANGELOG.md 更新","Git 命令行工具","AI 工具","代码管理"],"ja":["Git PR","Changelog ワークフロー","コードの自動提交","CHANGELOG.md の更新","Git コマンドラインツール","AI エージェント","コード管理"],"ko":["Git PR","Changelog 워크플로우","코드 제출 자동화","CHANGELOG.md 업데이트","Git 명령줄 도구","AI 도구","코드 관리"],"es":["git-pr-changelog","flujo de trabajo de Git","automatización de Git","registro de cambios","solicitudes de extracción","GitHub","línea de comandos de Git","agente de Git"],"fr":["git-pr-changelog","flux de travail Git","automatisation de Git","journal des modifications","demandes d''extraction","GitHub","ligne de commande Git","agent Git"],"de":["git-pr-changelog","Git-Workflow","Git-Automatisierung","Änderungsprotokoll","Pull-Requests","GitHub","Git-Kommandozeile","Git-Agent"],"pt":["git-pr-changelog","fluxo de trabalho de PR","Changelog","GitHub","automação de fluxo de trabalho","ferramentas de desenvolvimento","git","PR","request-pull"],"ru":["git-pr-changelog","работа с PR","Чangelog","GitHub","автоматизация работы","инструменты разработки","git","PR","request-pull","ИИ Агенты"],"ar":["git-pr-changelog","سير العمل لإعداد.setRequest","سجل التغييرات","GitHub","أتمتة سير العمل","أدوات التطوير","git","طلبات السحب","request-pull"]}},"owner":"lolopinto","repo":"ent","repoPath":"lolopinto/ent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.437Z","topics":[],"category":"community","skillMd":{"name":"git-pr-changelog","description":"Create commits, push branches, open pull requests (gh or manual), and update changelogs with PR numbers. Use when a user asks for commit/push/PR creation or changelog updates tied to a PR.","bodyPreview":"# Git PR + Changelog Workflow\n\n## Overview\n\nExecute the standard flow: verify repo state, stage changes, commit, push, open a PR, and update `CHANGELOG.md` with the PR number.\n\n## Workflow\n\n### 1) Inspect repo state\n\n- Confirm repo root: `git rev-parse --show-toplevel`\n- Check status: `git status -sb`\n- Note branch: `git rev-parse --abbrev-ref HEAD`\n- Check remotes: `git remote -v`\n\nIf there are unrelated changes, keep them untouched and only stage the files requested by the user.\n\n### 2) Stage","body":"# Git PR + Changelog Workflow\n\n## Overview\n\nExecute the standard flow: verify repo state, stage changes, commit, push, open a PR, and update `CHANGELOG.md` with the PR number.\n\n## Workflow\n\n### 1) Inspect repo state\n\n- Confirm repo root: `git rev-parse --show-toplevel`\n- Check status: `git status -sb`\n- Note branch: `git rev-parse --abbrev-ref HEAD`\n- Check remotes: `git remote -v`\n\nIf there are unrelated changes, keep them untouched and only stage the files requested by the user.\n\n### 2) Stage changes\n\n- Stage specific paths: `git add <path>...`\n- If the user did not specify which files to include, ask before staging everything.\n\n### 3) Commit\n\n- Use a clear message: `git commit -m \"<message>\"`\n- Do not amend or reword existing commits unless explicitly asked.\n\n### 4) Push\n\n- If upstream is missing, set it: `git push -u origin <branch>`\n- Otherwise: `git push`\n\n### 5) Create PR\n\nPrefer GitHub CLI if available:\n\n- Check: `command -v gh`\n- Create: `gh pr create --fill`\n- Capture PR number/URL: `gh pr view --json number,url`\n\nIf `gh` is unavailable, provide the compare URL:\n\n- Get remote URL: `git remote get-url origin`\n- Build: `https://github.com/<org>/<repo>/compare/<branch>?expand=1`\n\n### 6) Update changelog\n\n- Find `CHANGELOG.md` (usually repo root); search for `Unreleased` or the latest version section.\n- Add a bullet under the correct section with the PR number, e.g. `- add clause loader concurrency (#1234)`.\n- If the PR number is not known yet, update it after the PR is created.\n\n### 7) Commit changelog\n\n- Stage changelog only: `git add CHANGELOG.md`\n- Commit as a follow-up: `git commit -m \"Update changelog for <topic>\"`\n- Push: `git push`\n\n## Output checklist\n\n- Provide commit SHA(s) and the PR URL.\n- Mention changelog location and the inserted entry.\n"},"lastSynced":"2026-03-08T02:07:39.257Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated Git workflow management and changelog updates.","zh":"适合需要自动化 Git 工作流管理和变更日志更新的开发代理。","ja":"開発エージェントが Git ワークフロー管理と変更ログ更新を自動化する必要がある場合に適しています。","ko":"開発 에이전트가 자동화된 Git 워크플로 관리 및 변경 로그 업데이트가 필요한 경우에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de flujo de trabajo automatizada de Git y actualizaciones de registro de cambios.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de workflow Git automatisée et de mises à jour de journal des modifications.","de":"Perfekt für Entwicklungssagenten, die eine automatisierte Git-Workflow-Verwaltung und Aktualisierungen des Änderungsprotokolls benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento de fluxo de trabalho automatizado do Git e atualizações de changelog.","ru":"Идеально подходит для агентов разработки, которым необходим автоматизированный менеджмент рабочего процесса Git и обновления changelog.","ar":"مثالي لعمليات تطوير الوكلاء الذين يحتاجون إلى إدارة تدفق العمل الآلي لجيت وتحديثات السجل"},"recommendation":{"en":"Empowers agents to automate the standard Git PR and changelog workflow, executing tasks like verifying repo state, staging changes, committing, pushing, opening a PR, and updating CHANGELOG.md with the PR number using Git commands like git rev-parse and git status.","zh":"赋予代理自动化标准 Git PR 和变更日志工作流的能力，执行任务如验证仓库状态、暂存更改、提交、推送、打开 PR，并使用 Git 命令如 git rev-parse 和 git status 更新 CHANGELOG.md 文件。","ja":"エージェントに標準の Git PR と変更ログのワークフローを自動化する能力を与え、リポジトリの状態を確認したり、変更をステージングしたり、コミットしたり、プッシュしたり、PR を開いたり、Git コマンド (git rev-parse や git status など) を使用して CHANGELOG.md ファイルを更新したりするタスクを実行します。","ko":"에이전트에게 표준 Git PR 및 변경 로그 워크플로를 자동화 할 수 있는 능력을 부여하여 리포지토리의 상태를 확인하거나 변경 사항을 스테이징하거나 커밋하거나 푸시하거나 PR을 열거나 Git 명령어(git rev-parse 및 git status 등)을 사용하여 CHANGELOG.md 파일을 업데이트하는 등의 작업을 수행합니다.","es":"Habilita a los agentes a automatizar el flujo de trabajo estándar de Git PR y changelog, ejecutando tareas como verificar el estado del repositorio, preparar cambios, confirmar, enviar, abrir una solicitud de extracción y actualizar CHANGELOG.md con el número de solicitud de extracción utilizando comandos de Git como git rev-parse y git status.","fr":"Permet aux agents d''automatiser le flux de travail standard Git PR et changelog, en exécutant des tâches comme la vérification de l''état du référentiel, la préparation des modifications, la validation, l''envoi, l''ouverture d''une demande d''extraction et la mise à jour de CHANGELOG.md avec le numéro de demande d''extraction en utilisant des commandes Git comme git rev-parse et git status.","de":"Ermächtigt Agenten, den Standard-Git-PR- und Changelog-Workflow zu automatisieren, indem Aufgaben wie Überprüfen des Repository-Zustands, Vorbereiten von Änderungen, Bestätigen, Senden, Öffnen einer Pull-Anfrage und Aktualisieren von CHANGELOG.md mit der Pull-Anfragenummer unter Verwendung von Git-Befehlen wie git rev-parse und git status ausgeführt werden.","pt":"Habilita os agentes a automatizar o fluxo de trabalho padrão do Git PR e changelog, executando tarefas como verificar o estado do repositório, preparar alterações, confirmar, enviar, abrir um PR e atualizar CHANGELOG.md com o número do PR usando comandos Git como git rev-parse e git status.","ru":"Наделяет агентов возможностью автоматизировать стандартный рабочий процесс Git PR и changelog, выполняя задачи, такие как проверка состояния репозитория, подготовка изменений, фиксация, отправка, открытие PR и обновление CHANGELOG.md с номером PR, используя команды Git, такие как git rev-parse и git status.","ar":"تمكّن الوكلاء من توفير автоматية للعملية القياسية لجيت PR وتغيير السجل، من خلال تنفيذ مهام مثل التحقق من حالة المستودع وتمهيد التغييرات والالتزام بإرسال فتحطلب Pull وتحديث CHANGELOG.md برقم Pull Request باستخدام أوامر جيت مثل git rev-parse و git status."},"useCases":{"en":["Automating Git PR creation with changelog updates","Verifying repository state before committing changes","Updating CHANGELOG.md with PR numbers"],"zh":["使用变更日志更新自动创建 Git PR","在提交更改之前验证仓库状态","使用 PR 号码更新 CHANGELOG.md"],"ja":["変更ログ更新を使用して Git PR を自動作成する","変更をコミットする前にリポジトリの状態を確認する","PR 番号を使用して CHANGELOG.md を更新する"],"ko":["변경 로그 업데이트를 사용하여 Git PR을 자동 생성하는 것","변경 사항을 커밋하기 전에 저장소 상태를 확인하는 것","PR 번호를 사용하여 CHANGELOG.md를 업데이트하는 것"],"es":["Automatización de la creación de solicitudes de extracción de Git con actualizaciones de registro de cambios","Verificación del estado del repositorio antes de confirmar cambios","Actualización de CHANGELOG.md con números de solicitud de extracción"],"fr":["Automatisation de la création de demande d''extraction Git avec mises à jour de journal des modifications","Vérification de l''état du référentiel avant de valider les modifications","Mise à jour de CHANGELOG.md avec des numéros de demande d''extraction"],"de":["Automatisierung der Erstellung von Git-Pull-Anfragen mit Aktualisierungen des Änderungsprotokolls","Überprüfung des Repository-Zustands vor dem Bestätigen von Änderungen","Aktualisierung von CHANGELOG.md mit Pull-Anfragenummern"],"pt":["Automatizar a criação de PR do Git com atualizações de changelog","Verificar o estado do repositório antes de confirmar alterações","Atualizar CHANGELOG.md com números de PR"],"ru":["Автоматизировать создание PR в Git с обновлениями changelog","Проверять состояние репозитория перед фиксацией изменений","Обновлять CHANGELOG.md с номерами PR"],"ar":["توفير автомاتية لإنشاء طلبات السحب لجيت مع تحديثات سجل التغييرات","التحقق من حالة المستودع قبل الالتزام بالتغييرات","تحديث CHANGELOG.md بأرقام الطلبات السحب"]},"limitations":{"en":["Requires Git installation and configuration","Limited to Git repositories","Needs write access to the repository and CHANGELOG.md file"],"zh":["需要 Git 安装和配置","仅限 Git 仓库","需要对仓库和 CHANGELOG.md 文件有写入权限"],"ja":["Git のインストールと設定が必要","Git リポジトリのみ","リポジトリと CHANGELOG.md ファイルへの書き込みアクセスが必要"],"ko":["Git 설치 및 구성이 필요함","Git 저장소에만 국한됨","저장소 및 CHANGELOG.md 파일에 대한 쓰기 액세스가 필요함"],"es":["Requiere instalación y configuración de Git","Limitado a repositorios de Git","Necesita acceso de escritura al repositorio y al archivo CHANGELOG.md"],"fr":["Nécessite l''installation et la configuration de Git","Limité aux référentiels Git","Nécessite un accès en écriture au référentiel et au fichier CHANGELOG.md"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf Git-Repositorys","Benötigt Schreibzugriff auf das Repository und die CHANGELOG.md-Datei"],"pt":["Requer instalação e configuração do Git","Limitado a repositórios Git","Necessita acesso de gravação ao repositório e arquivo CHANGELOG.md"],"ru":["Требуется установка и настройка Git","Ограничен репозиториями Git","Требуется доступ на запись к репозиторию и файлу CHANGELOG.md"],"ar":["يتطلب تثبيت جيت وتفصيله","محدود بمستودعات جيت","يحتاج إلى صلاحية الكتابة إلى المستودع وملف CHANGELOG.md"]},"version":4},"contentHash":"63a16980624bb0424ed0a0427bac2fca94ad663de86423679842cb87bcaeeab6","qualityScore":41}');
