INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lolopinto/ent/git-pr-changelog', 'git-pr-changelog', 'lolopinto', 'ent', 'community', 'git-pr-changelog lolopinto ent community The git-pr-changelog skill automates the standard Git PR and changelog workflow for developers, executing tasks like verifying repo state and updating CHANGELOG.md. It benefits developers by simplifying their Git workflow. Git PR + Changelog 工作流程自动化代码提交和更新 CHANGELOG.md。通过 Git 命令行工具执行标准流程。 Git PR + Changelog ワークフローは、コードの提交と CHANGELOG.md の更新を自動化する AI エージェントです。 Git PR + Changelog 워크플로우는 코드 제출과 CHANGELOG.md 업데이트를 자동화하는 AI 도구입니다. El agente git-pr-changelog automatiza el flujo de trabajo de Git, incluyendo la verificación del estado del repositorio, la creación de confirmaciones y la actualización del archivo CHANGELOG.md L''agent git-pr-changelog automatise le flux de travail Git, y compris la vérification de l''état du référentiel, la création de validations et la mise à jour du fichier CHANGELOG.md Der git-pr-changelog-Agent automatisiert den Git-Workflow, einschließlich der Überprüfung des Repository-Zustands, der Erstellung von Commits und der Aktualisierung der Datei CHANGELOG.md O git-pr-changelog é uma ferramenta que automatiza o fluxo de trabalho de PR e Changelog no GitHub. Ele executa o fluxo padrão de verificação do estado do repositório, stage de alterações, commit, push, abertura de PR e atualização do CHANGELOG.md. git-pr-changelog - это инструмент, который автоматизирует работу с PR и Чangelog в GitHub. Он выполняет стандартный поток проверки состояния репозитория, stage изменений, commit, push, открытия PR и обновления CHANGELOG.md для ИИ Агентов git-pr-changelog هو أداة لتسريع سير العمل لإعداد.setRequest و سجل التغييرات في GitHub. يقوم بتنفيذ سير العمل القياسي لتحقق حالة المستودع ومرحلة التغييرات والالتزام والدفع وفتح طلبات السحب وتحديث CHANGELOG.md how to use git-pr-changelog git-pr-changelog setup guide git-pr-changelog alternative git-pr-changelog vs GitHub workflow automating Git PR and changelog git-pr-changelog install what is git-pr-changelog git-pr-changelog workflow automation git-pr-changelog for developers Git PR Changelog 工作流程 代码提交自动化 CHANGELOG.md 更新 Git 命令行工具 AI 工具 代码管理 Executes standard Git flow: verify repo state, stage changes, commit, push, and open PR Updates CHANGELOG.md with PR numbers Uses Git commands like git rev-parse and git status to inspect repository state Stages specific files requested by the user, leaving unrelated changes untouched Checks remotes using git remote -v and confirms repo root with git rev-parse --show-toplevel git-pr-changelog is a skill that automates the Git PR and changelog workflow, including verifying repository state, staging changes, and updating CHANGELOG.md with PR numbers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('filipstrand/mflux/mflux-pr', 'community', 'filipstrand', 'mflux', 'filipstrand/mflux', 'mflux-pr', 0, 0, 41, '2026-03-08T01:57:15.440Z', '2026-03-08T02:07:42.142Z', 'ee1f921ab3a281463ed0bf6e02f9572ab757519c9db5fd7734c8d6e371e7ca8d', '{"id":"filipstrand/mflux/mflux-pr","name":"mflux-pr","description":{"en":"mflux-pr provides native MLX implementations for state-of-the-art generative image models, benefiting developers with efficient pull request workflows","zh":"mflux-pr提供MLX本地实现的状态-of-the-art生成图像模型，帮助开发者高效地管理代码","ja":"mflux-prはMLXネイティブ実装のステートオブザアート生成画像モデルを提供し、開発者がコードを効率的に管理できるようにします","ko":"mflux-pr은 MLX 네이티브 구현의 최첨단 생성 이미지 모델을 제공하여 개발자가 코드를 효율적으로 관리할 수 있도록 합니다","es":"mflux-pr ofrece implementaciones nativas de MLX para modelos de imágenes generativas de última generación. Aprende a configurar y utilizar esta herramienta","fr":"mflux-pr propose des implementations natives MLX pour les modèles d''images génératives de pointe. Découvrez comment configurer et utiliser cet outil","de":"mflux-pr bietet native MLX-Implementierungen für state-of-the-art-Generative-Bildmodelle. Erfahren Sie, wie Sie dieses Tool konfigurieren und verwenden","pt":"mflux-pr é uma ferramenta para melhorar o fluxo de trabalho de pull request com implementações nativas MLX de modelos de imagem generativos. Ela fornece uma sequência segura para abrir PRs e executa testes rápidos","ru":"mflux-pr - это инструмент для оптимизации рабочего процесса pull request с использованием родных реализаций MLX генеративных моделей изображений. Он предоставляет безопасную последовательность для открытия PR и выполняет быстрые тесты","ar":"مflux-pr هو أداة لتحسين تدفق عمل الطلبات الجديدة مع تنفيذات ملائمة MLX لنمذجة الصور التوليدية. يوفر تسلسلًا آمنًا لفتح الطلبات الجديدة ويعمل الاختبارات السريعة"},"seo":{"title":{"en":"mflux-pr: Optimized Pull Request Workflow for AI Agents","zh":"mflux-pr 工作流设置指南","ja":"mflux-pr ワークフロー設定ガイド","ko":"mflux-pr 워크플로우 설정 가이드","es":"Guía de Configuración de mflux-pr para Modelos de Imágene...","fr":"Guide de Configuration de mflux-pr pour les Modèles d''Ima...","de":"Einrichtungsleitfaden für mflux-pr bei Generativen Bildmo...","pt":"Guia de Configuração mflux-pr para Desenvolvedores","ru":"Настройка mflux-pr: Руководство для Разработчиков ИИ Агентов","ar":"إعداد مflux-pr: دليل للمطورين باستخدام أدوات الذكاء الاصط..."},"description":{"en":"Streamline your PR process with mflux-pr - learn how to use /pr and /test-fast commands for efficient testing and repository management","zh":"了解mflux-pr的技术细节，包括MLX本地实现和状态-of-the-art生成图像模型","ja":"mflux-prの技術的詳細を学び、MLXネイティブ実装とステートオブザアート生成画像モデルを理解する","ko":"mflux-pr의 기술적 세부 사항을 알아보고 MLX 네이티브 구현 및 최첨단 생성 이미지 모델을 이해하십시오","es":"Aprende a utilizar mflux-pr para implementar modelos de imágenes generativas de última generación con este tutorial práctico","fr":"Découvrez comment utiliser mflux-pr pour mettre en œuvre des modèles d''images génératives de pointe avec ce didacticiel","de":"Erfahren Sie, wie Sie mflux-pr verwenden, um state-of-the-art-Generative-Bildmodelle mit diesem Praxistutorial zu implementieren","pt":"Aprenda a configurar mflux-pr para melhorar o fluxo de trabalho de pull request com implementações nativas MLX de modelos de imagem generativos","ru":"Узнайте, как настроить mflux-pr для оптимизации рабочего процесса pull request с использованием родных реализаций MLX генеративных моделей изображений и ИИ А...","ar":"تعلم كيفية إعداد مflux-pr لتحسين تدفق عمل الطلبات الجديدة مع تنفيذات ملائمة MLX لنمذجة الصور التوليدية باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"mflux-pr is a skill that implements native MLX for generative image models, providing a structured pull request workflow","zh":"mflux-pr是MLX本地实现的状态-of-the-art生成图像模型的工作流","ja":"mflux-prはMLXネイティブ実装のステートオブザアート生成画像モデルのワークフローです","ko":"mflux-pr은 MLX 네이티브 구현의 최첨단 생성 이미지 모델의 워크플로우입니다","e