INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('podverse/podverse/podverse-api-patterns', 'podverse-api-patterns', 'podverse', 'podverse', 'community', 'podverse-api-patterns podverse podverse community The podverse-api-patterns skill provides a quick reference for common patterns used in the podverse-api application, benefiting developers working with monorepo infrastructure. Podverse API 开发模式提供快速参考，用于常见的 API 应用开发模式，包括 Monorepo 上下文和帮助包 Podverse API パターンは、一般的な API アプリケーション開発パターンのためのクイック リファレンスを提供します。Monorepo コンテキストとヘルパー パッケージが含まれます Podverse API 개발 패턴은 일반적인 API 애플리케이션 개발 패턴에 대한 빠른 참조를 제공합니다. Monorepo 컨텍스트와 헬퍼 패키지가 포함됩니다 El patrón de API de Podverse proporciona una referencia rápida para patrones comunes utilizados en la aplicación podverse-api Le modèle d''API Podverse fournit une référence rapide pour les modèles couramment utilisés dans l''application podverse-api Das Podverse-API-Muster bietet eine schnelle Referenz für gängige Muster, die in der podverse-api-Anwendung verwendet werden O Podverse é um monorepo que fornece um conjunto de padrões e ferramentas para desenvolver aplicações robustas e escaláveis. Podverse - это монорепо, которое предоставляет набор шаблонов и инструментов для разработки прочных и масштабируемых приложений с помощью ИИ Агентов Podverse هو مونوريبو يوفر مجموعة من الأنماط والأدوات لتطوير تطبيقات قوية وموسعة النطاق how to use podverse-api-patterns podverse-api-patterns monorepo setup podverse-api-patterns alternative podverse-api-patterns vs npm podverse-api-patterns install guide what is podverse-api-patterns podverse-api-patterns best practices podverse-api-patterns tutorial Podverse API Monorepo API 应用开发 帮助包 ORM 实体 消息队列 AI 工具 AI 开发 API 设计模式 Utilizes @podverse/helpers for validation and requests Leverages @podverse/orm for Object-Relational Mapping (ORM) entities Integrates @podverse/mq for message queue management Supports modular development with packages/helpers and packages/orm Streamlines development with a monorepo structure at apps/api/ podverse-api-patterns is a monorepo for all infrastructure, modules, applications, and deployments related to the podverse-api application.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('askherconsulting/AI_SDLC_MCP/ai-sdlc-mcp-vibium-testing', 'community', 'askherconsulting', 'AI_SDLC_MCP', 'askherconsulting/AI_SDLC_MCP', 'ai-sdlc-mcp-vibium-testing', 0, 0, 41, '2026-03-08T01:57:15.484Z', '2026-03-08T02:10:02.479Z', 'c64db8e981464800a95e02e5d06ee802052a7f8c64bf32ece4d8cd8cb55ed404', '{"id":"askherconsulting/AI_SDLC_MCP/ai-sdlc-mcp-vibium-testing","name":"ai-sdlc-mcp-vibium-testing","description":{"en":"The ai-sdlc-mcp-vibium-testing skill enables developers to modify and maintain end-to-end tests for Node + Express apps, ensuring upload flow and health check stability. It benefits developers working with multipart forms and image uploads.","zh":"AI SDLC MCP Webapp测试技能用于Node + Express应用程序的端到端测试，确保上传流和健康检查的稳定性","ja":"AIエージェントを使用したMCP Webappテストスキルは、Node + Expressアプリケーションのエンドツーエンドテストを実行し、アップロードフローとヘルスチェックの安定性を確保する","ko":"AI SDLC MCP Webapp 테스트 스킬은 Node + Express 애플리케이션의 엔드 투 엔드 테스트를 실행하여 업로드 흐름과 헬스 체크의 안정성을 보장합니다","es":"El skill ai-sdlc-mcp-vibium-testing permite probar aplicaciones web con Node y Express, incluyendo pruebas de subida de imágenes y comprobaciones de salud","fr":"Le skill ai-sdlc-mcp-vibium-testing permet de tester des applications web avec Node et Express, y compris les tests de téléchargement d''images et les vérifications de santé","de":"Das Skill ai-sdlc-mcp-vibium-testing ermöglicht das Testen von Webanwendungen mit Node und Express, einschließlich Bildupload- und Gesundheitsprüfungen","pt":"O ai-sdlc-mcp-vibium-testing é uma habilidade para testes de aplicativos web com Node e Express, garantindo a estabilidade dos testes e a compatibilidade com uploads de imagens","ru":"ИИ Агенты ai-sdlc-mcp-vibium-testing - это навык для тестирования веб-приложений на Node и Express, обеспечивающий стабильность тестов и совместимость с загрузкой изображений","ar":"الوكيل الذكي ai-sdlc-