INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('askherconsulting/AI_SDLC_MCP/ai-sdlc-mcp-vibium-testing', 'ai-sdlc-mcp-vibium-testing', 'askherconsulting', 'AI_SDLC_MCP', 'community', 'ai-sdlc-mcp-vibium-testing askherconsulting AI_SDLC_MCP community The ai-sdlc-mcp-vibium-testing skill enables developers to modify and maintain end-to-end tests for Node + Express apps, ensuring upload flow and health check stability. It benefits developers working with multipart forms and image uploads. AI SDLC MCP Webapp测试技能用于Node + Express应用程序的端到端测试，确保上传流和健康检查的稳定性 AIエージェントを使用したMCP Webappテストスキルは、Node + Expressアプリケーションのエンドツーエンドテストを実行し、アップロードフローとヘルスチェックの安定性を確保する AI SDLC MCP Webapp 테스트 스킬은 Node + Express 애플리케이션의 엔드 투 엔드 테스트를 실행하여 업로드 흐름과 헬스 체크의 안정성을 보장합니다 El skill ai-sdlc-mcp-vibium-testing permite probar aplicaciones web con Node y Express, incluyendo pruebas de subida de imágenes y comprobaciones de salud Le skill ai-sdlc-mcp-vibium-testing permet de tester des applications web avec Node et Express, y compris les tests de téléchargement d''images et les vérifications de santé Das Skill ai-sdlc-mcp-vibium-testing ermöglicht das Testen von Webanwendungen mit Node und Express, einschließlich Bildupload- und Gesundheitsprüfungen O ai-sdlc-mcp-vibium-testing é uma habilidade para testes de aplicativos web com Node e Express, garantindo a estabilidade dos testes e a compatibilidade com uploads de imagens ИИ Агенты ai-sdlc-mcp-vibium-testing - это навык для тестирования веб-приложений на Node и Express, обеспечивающий стабильность тестов и совместимость с загрузкой изображений الوكيل الذكي ai-sdlc-mcp-vibium-testing هو مهارة لاختبار تطبيقات الويب باستخدام Node و Express، مما يضمن استقرار الاختبارات وتوافقها مع تحميل الصور how to use ai-sdlc-mcp-vibium-testing ai-sdlc-mcp-vibium-testing setup guide ai-sdlc-mcp-vibium-testing vs jest ai-sdlc-mcp-vibium-testing install node express testing tools end-to-end testing for upload flows AI SDLC MCP Webapp测试 Node + Express应用程序测试 AI工具 端到端测试 上传流测试 健康检查测试 AI SDLC MCP Webapp测试技能 AIエージェント Runs end-to-end tests with `npm start` command Validates and preserves upload flow using multipart forms to `/pictures/upload` Serves uploaded images from `/uploads` and displays on `/pictures` Maintains stable health check semantics via `GET /health` ai-sdlc-mcp-vibium-testing is a skill for maintaining end-to-end tests in Node + Express apps, focusing on upload flow and health check semantics');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sharifli4/nestjs-infra-template/create-nestjs-exception', 'community', 'sharifli4', 'nestjs-infra-template', 'sharifli4/nestjs-infra-template', 'create-nestjs-exception', 0, 0, 41, '2026-03-08T01:57:15.498Z', '2026-03-08T02:10:15.473Z', '54180e0d6ce602c2e8cd23d8234c2b1840abdad7342749c243eb79f30ffa4eee', '{"id":"sharifli4/nestjs-infra-template/create-nestjs-exception","name":"create-nestjs-exception","description":{"en":"The create-nestjs-exception skill helps developers create standardized exceptions in NestJS projects, following best practices for error handling and documentation.","zh":"NestJS 异常创建模板提供了一种快速创建标准化异常的方式，通过遵循特定的模式和命名约定","ja":"NestJS 例外作成テンプレートは、特定のパターンと命名規約に従って標準化された例外を作成するための迅速な方法を提供します","ko":"NestJS 예외 생성 템플릿은 특정 패턴과 명명 규칙을 따라 표준화된 예외를 빠르게 생성하는 방법을 제공합니다","es":"Crea excepciones personalizadas en NestJS siguiendo patrones de proyecto y mejores prácticas, incluyendo el uso de BaseExceptionDto y ExceptionTypeEnum","fr":"Créez des exceptions personnalisées dans NestJS en suivant les modèles de projet et les meilleures pratiques, y compris l''utilisation de BaseExceptionDto et ExceptionTypeEnum","de":"Erstellen Sie benutzerdefinierte Ausnahmen in NestJS, indem Sie Projektmustern und Best Practices folgen, einschließlich der Verwendung von BaseExceptionDto und ExceptionTypeEnum","pt":"O Create NestJS Exception é um modelo de projeto para criar exceções padrão em NestJS, incluindo NotFoundException e CustomBadRequestException.","ru":"Create NestJS Exception - это шаблон проекта для создания стандартизированных исключений в NestJS, включая NotFoundException и CustomBadRequestException для ИИ Агентов.","ar":"إنشاء استثناءات NestJS هو قالب مشروع لإنشاء استثناءات معيارية في NestJS، بما في ذلك NotFoundException و CustomBadRequestException لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"create-nestjs-