INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('IPNL-POLYU/IPIN-Examples/bug-triage-evidence', 'bug-triage-evidence', 'IPNL-POLYU', 'IPIN-Examples', 'community', 'bug-triage-evidence IPNL-POLYU IPIN-Examples community The bug-triage-evidence skill helps engineers reproduce and report bugs efficiently. It assists in creating bug bundles with minimal reproduction steps and expected vs actual behavior. Bug Triage & Evidence Packaging 是一个用于优化调试流程的工具，通过创建 bug 报告和证据包来简化错误诊断 バグ トリアージ & エビデンス パッケージは、デバッグ プロセスを最適化するためのツールで、バグ レポートと証拠パッケージを作成してエラー診断を簡素化します 버그 트라이어지 & 증거 패키징은 디버깅 프로세스를 최적화하는 도구로 버그 보고서와 증거 패키지를 생성하여 오류 진단을 간소화합니다 Bug-triage-evidence es una habilidad para identificar y documentar errores de manera efectiva, utilizando técnicas de reproducción y creación de informes detallados Bug-triage-evidence est une compétence pour identifier et documenter les erreurs de manière efficace, en utilisant des techniques de reproduction et de création de rapports détaillés Bug-triage-evidence ist eine Fähigkeit, um Fehler effektiv zu identifizieren und zu dokumentieren, indem reproduzierbare Schritte und detaillierte Berichte erstellt werden O Bug-Triage-Evidence é uma ferramenta para ajudar desenvolvedores a identificar e relatar erros de forma eficaz, com recursos como reprodução de erros e criação de pacotes de evidências. Bug-Triage-Evidence - это инструмент, помогающий разработчикам выявлять и отчетать об ошибках эффективно, с функциями như воспроизведение ошибок и создание пакетов доказательств. أداة فحص الخلل Bug-Triage-Evidence هي أداة لمساعدة المطورين على تحديد الأخطاء وتقديم تقارير دقيقة، مع ميزات مثل إعادة إنتاج الأخطاء وإنشاء حزم الأدلة. how to use bug-triage-evidence bug-triage-evidence setup guide bug reporting best practices bug-triage-evidence alternative bug-triage-evidence vs debug-diary bug-triage-evidence install what is bug-triage-evidence bug-triage-evidence tutorial bug-triage-evidence for AI agents Bug Triage & Evidence Packaging 调试工具 错误诊断 AI工具 开发效率 命令行工具 Reproduces issues with minimal steps and command-line entries Captures expected vs actual behavior in 1-3 bullet points Creates bug bundles in `.dev/` folders with README.md files Includes seed information for reproducibility Supports clear bug reporting with symlinks and folder structures bug-triage-evidence is a skill that facilitates bug triage and evidence packaging for engineers, enabling them to reproduce and report issues effectively.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nico7522/card-concept-maker/FSD architecture', 'community', 'Nico7522', 'card-concept-maker', 'Nico7522/card-concept-maker', 'FSD architecture', 0, 0, 41, '2026-03-08T01:57:15.507Z', '2026-03-08T02:10:23.418Z', 'bd7eceaf8b842453101886582b574ca7fedbda41de51e8e3805e391f42e38639', '{"id":"Nico7522/card-concept-maker/FSD architecture","name":"FSD architecture","description":{"en":"FSD architecture helps developers create and manage files and folders efficiently. It provides a structured approach to file organization, benefiting developers working on complex projects.","zh":"FSD 架构是一种用于创建和移动文件或文件夹的技能，提供了 layers、slices-segments 和 public-api 的文档和教程","ja":"FSD アーキテクチャは、ファイルやフォルダを作成または移動するために使用されるスキルで、layers、slices-segments、public-api に関するドキュメントとチュートリアルを提供する","ko":"FSD 아키텍처는 파일 및 폴더를 생성하거나 이동하는 데 사용되는 기술로 layers, slices-segments, public-api에 대한 문서 및 자습서를 제공합니다","es":"La arquitectura FSD es un conjunto de reglas para crear y estructurar archivos y carpetas de manera efectiva. Conoce más sobre su documentación y tutoriales.","fr":"L''architecture FSD est un ensemble de règles pour créer et structurer des fichiers et des dossiers de manière efficace. En savoir plus sur sa documentation et ses tutoriels.","de":"Die FSD-Architektur ist ein Satz von Regeln, um Dateien und Ordner effektiv zu erstellen und zu strukturieren. Erfahren Sie mehr über ihre Dokumentation und Tutorien.","pt":"A arquitetura FSD é uma estrutura para criar e gerenciar arquivos e pastas. Ela fornece documentação e exemplos para ajudar os desenvolvedores.","ru":"Архитектура FSD - это структура для создания и управления файлами и папками. Она предоставляет документацию и примеры, чтобы помочь разработчикам с ИИ Агентами.","ar":"هندسة FSD هي هيكل لإنشاء وإدارة الملفات والمجلدات. توفر وثائق وأمثلة لتساعد المطورين مع أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"FSD Architecture: Setup Guide for AI Agents | AI Agent Skill","zh":"FSD 架构入门指南","ja":"FSD アーキテクチャ設定ガイド","ko":"FSD 아키텍처 구축 가이드","es":"Arquitectura FSD: Guía de Configuración para Desarrolladores","fr":"Architecture FSD: Guide de Mise en Place pour les Dévelop...","de":"FSD-Architektur: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração FSD Architecture: Criando Arquivos e...","ru":"Настройка FSD Architecture: Создание Файлов и Папок с ИИ ...","ar":"دليل إعداد هندسة FSD: إنشاء الملفات والمجلدات باستخدام أد..."},"description":{"en":"Unlock efficient file management with FSD architecture. Discover how to create and move files and folders with ease. Learn more and get started today!","zh":"了解 FSD 架构的技术细节，创建和移动文件或文件夹，访问文档和教程","ja":"FSD アーキテクチャのテクニカルな詳細を学び、ファイルやフォルダを作成または移動する方法をマスターする","ko":"FSD 아키텍처의 기술 세부 사항을 살펴보고 파일 및 폴더 생성 및 이동 방법을 학습하세요","es":"Aprende a crear y estructurar archivos y carpetas con la arquitectura FSD. Descubre los mejores practicas y documentación para desarrolladores.","fr":"Découvrez comment créer et structurer des fichiers et des dossiers avec l''architecture FSD. Consultez la documentation et les meilleures pratiques pour les d...","de":"Erfahren Sie, wie Sie Dateien und Ordner mit der FSD-Architektur erstellen und strukturieren. Entdecken Sie die besten Praktiken und Dokumentation für Entwic...","pt":"Aprenda a criar e gerenciar arquivos e pastas com a arquitetura FSD. Descubra como usar a documentação e os exemplos para melhorar sua produtividade.","ru":"Узнайте, как создавать и управлять файлами и папками с помощью архитектуры FSD. Изучите документацию и примеры, чтобы повысить свою производительность с ИИ А...","ar":"تعرف على كيفية إنشاء وإدارة الملفات والمجلدات باستخدام هندسة FSD. استفد من الوثائق والأمثلة لتحسين إنتاجيتك مع أدوات الذكاء الاصطناعي."},"definition":{"en":"FSD architecture is a file system design that enables efficient creation, movement, and management of files and folders, utilizing layers, slices, and segments.","zh":"FSD 架构是一种用于管理文件和文件夹的技术框架","ja":"FSD アーキテクチャは、ファイルとフォルダを管理するためのテクニカルなフレームワークです","ko":"FSD 아키텍처는 파일 및 폴더를 관리하는 기술 프레임워크입니다","es":"La arquitectura FSD es un estándar para crear y organizar archivos y carpetas.","fr":"L''architecture FSD est un standard pour créer et organiser des fichiers et des dossiers.","de":"Die FSD-Architektur ist ein Standard für die Erstellung und Organisation von Dateien und Ordnern.","pt":"FSD Architecture é uma estrutura de organização de arquivos e pastas.","ru":"FSD Architecture - это структура организации файлов и папок с ИИ Агентами.","ar":"هندسة FSD هي هيكل tổ chức الملفات والمجلدات باستخدام أدوات الذكاء الاصطناعي."},"features":{"en":["Utilizes layers for organized file structure","Employs slices and segments for efficient file management","Provides public API for seamless integration","Supports documentation for layers, slices, and public API","Offers a tutorial for getting started with FSD architecture","Enables efficient creation and movement of files and folders"],"zh":["支持 layers、slices-segments 和 public-api","提供创建和移动文件或文件夹的文档和教程","支持文件和文件夹的管理","提供了 https://fsd.how/docs/reference/layers 的文档","提供了 https://fsd.how/docs/reference/slices-segments 的文档","提供了 https://fsd.how/docs/reference/public-api 的文档"],"ja":["layers、slices-segments、public-api をサポート","ファイルやフォルダを作成または移動するためのドキュメントとチュートリアルを提供","ファイルとフォルダの管理をサポート","https://fsd.how/docs/reference/layers のドキュメントを提供","https://fsd.how/docs/reference/slices-segments のドキュメントを提供","https://fsd.how/docs/reference/public-api のドキュメントを提供"],"ko":["layers, slices-segments, public-api 지원","파일 및 폴더 생성 및 이동을 위한 문서 및 자습서 제공","파일 및 폴더 관리 지원","https://fsd.how/docs/reference/layers 문서 제공","https://fsd.how/docs/reference/slices-segments 문서 제공","https://fsd.how/docs/reference/public-api 문서 제공"],"es":["Creación de archivos y carpetas","Estructuración de directorios","Uso de la documentación de FSD","Seguimiento de tutoriales para principiantes","Uso de la API pública de FSD","Organización de capas y segmentos"],"fr":["Création de fichiers et de dossiers","Structuration de répertoires","Utilisation de la documentation FSD","Suivi de tutoriels pour débutants","Utilisation de l''API publique FSD","Organisation de couches et de segments"],"de":["Erstellung von Dateien und Ordnern","Strukturierung von Verzeichnissen","Verwendung der FSD-Dokumentation","Befolgen von Tutorien für Anfänger","Verwendung der öffentlichen FSD-API","Organisation von Schichten und Segmenten"],"pt":["Criação de arquivos e pastas","Gerenciamento de caminhos de arquivos","Documentação de referência para layers","Documentação de referência para slices e segments","Exemplos de uso da API pública"],"ru":["Создание файлов и папок","Управление путями файлов","Документация по слоям","Документация по срезам и сегментам","Примеры использования публичного API с ИИ Агентами"],"ar":["إنشاء الملفات والمجلدات","إدارة مسارات الملفات","وثائق مرجعية للطبقات","وثائق مرجعية للشريحة والقطاعات","أمثلة استخدام واجهة برمجة التطبيقات العامة مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use FSD architecture","FSD architecture tutorial","FSD architecture vs traditional file systems","FSD architecture setup guide","what is FSD architecture","FSD architecture documentation","FSD architecture layers","FSD architecture slices and segments","FSD architecture public API","FSD architecture install"],"zh":["FSD 架构","文件管理","文件夹管理","layers","slices-segments","public-api","AI 工具","AI 技术"],"ja":["FSD アーキテクチャ","ファイル管理","フォルダ管理","layers","slices-segments","public-api","AI エージェント","AI テクノロジー"],"ko":["FSD 아키텍처","파일 관리","폴더 관리","layers","slices-segments","public-api","AI 도구","AI 기술"],"es":["arquitectura FSD","creación de archivos","estructuración de directorios","documentación FSD","tutoriales FSD","API pública FSD","desarrollo de software","herramientas de desarrollo","agentes de inteligencia artificial"],"fr":["architecture FSD","création de fichiers","structuration de répertoires","documentation FSD","tutoriels FSD","API publique FSD","développement de logiciels","outils de développement","agents d''intelligence artificielle"],"de":["FSD-Architektur","Erstellung von Dateien","Strukturierung von Verzeichnissen","FSD-Dokumentation","FSD-Tutorien","öffentliche FSD-API","Software-Entwicklung","Entwicklungstools","Künstliche Intelligenz Tools"],"pt":["FSD Architecture","criação de arquivos","gerenciamento de pastas","documentação de referência","exemplos de uso da API","desenvolvimento de software","organização de arquivos"],"ru":["FSD Architecture","создание файлов","управление папками","документация по слоям","примеры использования API","разработка программного обеспечения","организация файлов с ИИ Агентами"],"ar":["هندسة FSD","إنشاء الملفات","إدارة المجلدات","وثائق مرجعية","أمثلة استخدام واجهة برمجة التطبيقات","تطوير البرمجيات","تنظيم الملفات مع أدوات الذكاء الاصطناعي"]}},"owner":"Nico7522","repo":"card-concept-maker","repoPath":"Nico7522/card-concept-maker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.507Z","topics":[],"category":"community","skillMd":{"name":"FSD architecture","description":"This skill is used to structure the project correctly by following the principles of Feature Sliced Design Architecture.","bodyPreview":"# Skill\n\nUse this skill when you need to create or move any file or folder. Use it to know where to place it.\n\n## When use it\n\n- When creating or moving any new file or folder\n\n## Instructions\n\n### Documentation\n\n- https://fsd.how/docs/reference/layers\n- https://fsd.how/docs/reference/slices-segments\n- https://fsd.how/docs/reference/public-api\n\n### Exemple\n\n- https://fsd.how/docs/get-started/tutorial","body":"# Skill\n\nUse this skill when you need to create or move any file or folder. Use it to know where to place it.\n\n## When use it\n\n- When creating or moving any new file or folder\n\n## Instructions\n\n### Documentation\n\n- https://fsd.how/docs/reference/layers\n- https://fsd.how/docs/reference/slices-segments\n- https://fsd.how/docs/reference/public-api\n\n### Exemple\n\n- https://fsd.how/docs/get-started/tutorial\n"},"lastSynced":"2026-03-08T02:10:23.418Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured file organization and efficient folder management","zh":"非常适合需要结构化文件组织和高效文件夹管理的开发代理","ja":"開発エージェントが構造化されたファイル組織と効率的なフォルダ管理を必要とする場合に最適","ko":"구조화된 파일 조직과 효율적인 폴더 관리가 필요한 개발 에이전트에 적합","es":"Perfecto para agentes de desarrollo que necesitan una organización de archivos estructurada y una gestión de carpetas eficiente","fr":"Parfait pour les agents de développement ayant besoin d''une organisation de fichiers structurée et d''une gestion de dossiers efficace","de":"Perfekt für Entwicklungsmittel benötigende Struktur und effiziente Ordnerverwaltung","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de organização de arquivos estruturada e gestão eficiente de pastas","ru":"Идеально для агентов разработки, которым необходима структурированная организация файлов и эффективное управление папками","ar":"مثالي ل와كلاء التطوير الذين يحتاجون إلى تنظيم ملفات منظم وادارة مجلدات فعالة"},"recommendation":{"en":"Empowers agents to create and manage files and folders efficiently using FSD architecture, providing a structured approach to file organization with layers and slices-segments, and utilizing the public API for seamless integration","zh":"赋予代理创建和管理文件和文件夹的能力，使用FSD架构提供结构化的文件组织方法，具有分层和切片-段，并利用公共API实现无缝集成","ja":"FSDアーキテクチャを使用して、エージェントがファイルとフォルダを作成および管理できるようにし、レイヤーとスライス-セグメントを備えた構造化されたファイル組織方法を提供し、公開APIを使用してシームレスな統合を実現","ko":"FSD 아키텍처를 사용하여 에이전트가 파일과 폴더를 생성 및 관리할 수 있도록 하며, 계층과 슬라이스-세그먼트를 갖춘 구조화된 파일 조직 방법을 제공하고, 공개 API를 사용하여无缝한 통합을 구현","es":"Habilita a los agentes a crear y gestionar archivos y carpetas de forma eficiente utilizando la arquitectura FSD, proporcionando un enfoque estructurado para la organización de archivos con capas y segmentos de rebanadas, y utilizando la API pública para una integración sin problemas","fr":"Permet aux agents de créer et de gérer des fichiers et des dossiers de manière efficace en utilisant l''architecture FSD, fournissant une approche structurée pour l''organisation des fichiers avec des couches et des segments de tranches, et en utilisant l''API publique pour une intégration transparente","de":"Ermächtigt Agenten, Dateien und Ordner effizient zu erstellen und zu verwalten, indem sie die FSD-Architektur nutzen, und bietet einen strukturierten Ansatz für die Dateiorganisation mit Schichten und Segmenten, und nutzt die öffentliche API für eine nahtlose Integration","pt":"Habilita os agentes a criar e gerenciar arquivos e pastas de forma eficiente usando a arquitetura FSD, fornecendo uma abordagem estruturada para a organização de arquivos com camadas e segmentos de fatias, e utilizando a API pública para integração sem problemas","ru":"Наделяет агентов возможностью создавать и управлять файлами и папками эффективно, используя архитектуру FSD, обеспечивая структурированный подход к организации файлов с помощью слоев и сегментов срезов, и используя публичный API для бесшовной интеграции","ar":"يمنح الوكلاء khảية إنشاء وادارة الملفات والمجلدات بفعالية باستخدام هندسة FSD، وتقديم نهج منظم لتنظيم الملفات مع طبقات وأقسام من الشريحة، واستخدام واجهة برمجة التطبيقات العامة للتكامل دون مشاكل"},"useCases":{"en":["Creating new files or folders with optimal placement","Managing complex project structures with FSD layers","Migrating existing projects to FSD architecture for improved organization"],"zh":["使用最优放置创建新文件或文件夹","使用FSD层管理复杂的项目结构","将现有项目迁移到FSD架构以改善组织"],"ja":["最適な配置で新しいファイルまたはフォルダを作成する","FSDレイヤーを使用して複雑なプロジェクト構造を管理する","既存のプロジェクトをFSDアーキテクチャに移行して組織を改善する"],"ko":["최적의 배치로 새로운 파일 또는 폴더를 생성","FSD 레이어를 사용하여 복잡한 프로젝트 구조를 관리","기존 프로젝트를 FSD 아키텍처로 마이그레이션하여 조직을 개선"],"es":["Crear nuevos archivos o carpetas con colocación óptima","Gestionar estructuras de proyecto complejas con capas FSD","Migrar proyectos existentes a la arquitectura FSD para una mejor organización"],"fr":["Créer de nouveaux fichiers ou dossiers avec un placement optimal","Gérer des structures de projet complexes avec des couches FSD","Migrer des projets existants vers l''architecture FSD pour une meilleure organisation"],"de":["Erstellen von neuen Dateien oder Ordnern mit optimaler Platzierung","Verwalten komplexer Projekstrukturen mit FSD-Schichten","Migrieren bestehender Projekte zur FSD-Architektur für eine verbesserte Organisation"],"pt":["Criar novos arquivos ou pastas com posicionamento ótimo","Gerenciar estruturas de projeto complexas com camadas FSD","Migrar projetos existentes para a arquitetura FSD para melhor organização"],"ru":["Создание новых файлов или папок с оптимальным размещением","Управление сложными структурами проектов с помощью слоев FSD","Перенос существующих проектов в архитектуру FSD для улучшения организации"],"ar":["إنشاء ملفات أو مجلدات جديدة مع وضع مثالي","إدارة هياكل المشروع المعقدة مع طبقات FSD","نقل المشاريع الحالية إلى هندسة FSD لتحسين التنظيم"]},"limitations":{"en":["Requires understanding of FSD documentation and reference materials","Limited to file and folder organization within FSD architecture"],"zh":["需要理解FSD文档和参考资料","仅限于FSD架构内的文件和文件夹组织"],"ja":["FSDドキュメントとリファレンス資料の理解が必要","FSDアーキテクチャ内でのファイルとフォルダの組織のみに限定"],"ko":["FSD 문서 및 참고 자료의 이해가 필요","FSD 아키텍처 내에서의 파일 및 폴더 조직에만 제한"],"es":["Requiere comprensión de la documentación y materiales de referencia de FSD","Limitado a la organización de archivos y carpetas dentro de la arquitectura FSD"],"fr":["Nécessite une compréhension de la documentation et des matériaux de référence de FSD","Limité à l''organisation des fichiers et des dossiers à l''intérieur de l''architecture FSD"],"de":["Erfordert das Verständnis der FSD-Dokumentation und Referenzmaterialien","Begrenzt auf die Datei- und Ordnerverwaltung innerhalb der FSD-Architektur"],"pt":["Requer entendimento da documentação e materiais de referência do FSD","Limitado à organização de arquivos e pastas dentro da arquitetura FSD"],"ru":["Требует понимания документации и справочных материалов FSD","Ограничен организацией файлов и папок внутри архитектуры FSD"],"ar":["يتطلب فهم وثائق FSD والمواد المرجعية","محدود بتنظيم الملفات والمجلدات داخل هندسة FSD"]},"version":4},"contentHash":"bd7eceaf8b842453101886582b574ca7fedbda41de51e8e3805e391f42e38639","qualityScore":41}');
