INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Nico7522/card-concept-maker/FSD architecture', 'FSD architecture', 'Nico7522', 'card-concept-maker', 'community', 'FSD architecture Nico7522 card-concept-maker community FSD architecture helps developers create and manage files and folders efficiently. It provides a structured approach to file organization, benefiting developers working on complex projects. FSD 架构是一种用于创建和移动文件或文件夹的技能，提供了 layers、slices-segments 和 public-api 的文档和教程 FSD アーキテクチャは、ファイルやフォルダを作成または移動するために使用されるスキルで、layers、slices-segments、public-api に関するドキュメントとチュートリアルを提供する FSD 아키텍처는 파일 및 폴더를 생성하거나 이동하는 데 사용되는 기술로 layers, slices-segments, public-api에 대한 문서 및 자습서를 제공합니다 La arquitectura FSD es un conjunto de reglas para crear y estructurar archivos y carpetas de manera efectiva. Conoce más sobre su documentación y tutoriales. L''architecture FSD est un ensemble de règles pour créer et structurer des fichiers et des dossiers de manière efficace. En savoir plus sur sa documentation et ses tutoriels. Die FSD-Architektur ist ein Satz von Regeln, um Dateien und Ordner effektiv zu erstellen und zu strukturieren. Erfahren Sie mehr über ihre Dokumentation und Tutorien. A arquitetura FSD é uma estrutura para criar e gerenciar arquivos e pastas. Ela fornece documentação e exemplos para ajudar os desenvolvedores. Архитектура FSD - это структура для создания и управления файлами и папками. Она предоставляет документацию и примеры, чтобы помочь разработчикам с ИИ Агентами. هندسة FSD هي هيكل لإنشاء وإدارة الملفات والمجلدات. توفر وثائق وأمثلة لتساعد المطورين مع أدوات الذكاء الاصطناعي. how to use FSD architecture FSD architecture tutorial FSD architecture vs traditional file systems FSD architecture setup guide what is FSD architecture FSD architecture documentation FSD architecture layers FSD architecture slices and segments FSD architecture public API FSD architecture install FSD 架构 文件管理 文件夹管理 layers slices-segments public-api AI 工具 AI 技术 Utilizes layers for organized file structure Employs slices and segments for efficient file management Provides public API for seamless integration Supports documentation for layers, slices, and public API Offers a tutorial for getting started with FSD architecture Enables efficient creation and movement of files and folders FSD architecture is a file system design that enables efficient creation, movement, and management of files and folders, utilizing layers, slices, and segments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jusedit/any-docs-mcp/ralph-deep-init', 'community', 'jusedit', 'any-docs-mcp', 'jusedit/any-docs-mcp', 'ralph-deep-init', 0, 0, 41, '2026-03-08T01:57:15.518Z', '2026-03-08T02:10:38.319Z', 'acb124344ca7a6832d0e58f6765af141b2ca4418eac582e4585fff9205ce46d5', '{"id":"jusedit/any-docs-mcp/ralph-deep-init","name":"ralph-deep-init","description":{"en":"The ralph-deep-init skill performs a comprehensive project initialization, generating a large, well-organized backlog by breaking down the project into functional architectural groups, ideal for complex projects with multiple features.","zh":"Ralph Deep Init 是一个通用文档管道，用于 AI 辅助工具的项目初始化和任务组织","ja":"Ralph Deep Init は、AI エージェントのプロジェクト初期化とタスク組織のための汎用ドキュメント パイプラインです","ko":"Ralph Deep Init은 AI 에이전트의 프로젝트 초기화와 태스크 구성의ための 범용 문서 파이프라인입니다","es":"ralph-deep-init es una habilidad que realiza una inicialización de proyecto integral, generando una gran cantidad de tareas detalladas organizadas por arquitectura","fr":"ralph-deep-init est une compétence qui effectue une initialisation de projet complète, générant un grand nombre de tâches détaillées organisées par architecture","de":"ralph-deep-init ist eine Fähigkeit, die eine umfassende Projektinitialisierung durchführt und eine große Anzahl detaillierter Aufgaben generiert, die nach Architektur organisiert sind","pt":"O Ralph Deep Init é uma habilidade que realiza uma inicialização abrangente de projetos, gerando uma grande lista de tarefas organizadas por grupos arquiteturais","ru":"Ralph Deep Init — это навык, который выполняет комплексную инициализацию проектов, генерируя большой список задач, организованных по архитектурным группам с помощью ИИ Агентов","ar":"Ralph Deep Init هو مهارة يقوم بتحديث المشاريع الشاملة، مما يولد قائمة كبيرة من المهام المنظمة حسب المجموعات المعمارية مع وكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"ralph-deep-init: Comprehensive Project Initialization Set...","zh":"Ralph Deep Init 设置指南 - AIエージェント项目初始化","ja":"Ralph Deep Init セットアップガイド - AIエージェントのプロジェクト初期化","ko":"Ralph Deep Init 설정 가이드 - AI 에이전트 프로젝트 초기화","es":"Guía de configuración de ralph-deep-init para proyectos c...","fr":"Guide de mise en route de ralph-deep-init pour les projet...","de":"Einrichtungsleitfaden für ralph-deep-init bei komplexen A...","pt":"Ralph Deep Init: Guia de Configuração para Inicialização ...","ru":"Ralph Deep Init: Руководство по настройке для инициализац...","ar":"Ralph Deep Init: دليل إعداد لتحديث المشاريع المعقدة مع وك..."},"description":{"en":"Discover how ralph-deep-init streamlines complex project setup with multi-stage initialization and organized backlogs. Learn how to get started today!","zh":"了解 Ralph Deep Init 的功能和特点，实现复杂项目的自动化初始化和任务组织","ja":"Ralph Deep Init の機能と特徴を学び、複雑なプロジェクトの自動化初期化とタスク組織を実現する","ko":"Ralph Deep Init 의 기능과 특징을 알아보고 복잡한 프로젝트의 자동화 초기화와 태스크 구성 구현","es":"Aprende a utilizar ralph-deep-init para inicializar proyectos complejos con múltiples características y tareas organizadas por arquitectura","fr":"Découvrez comment utiliser ralph-deep-init pour initialiser des projets complexes avec de multiples fonctionnalités et tâches organisées par architecture","de":"Erfahren Sie, wie Sie ralph-deep-init verwenden, um komplexe Projekte mit mehreren Funktionen und Aufgaben zu initialisieren, die nach Architektur organisier...","pt":"Aprenda a usar o Ralph Deep Init para inicializar projetos complexos com múltiplas funcionalidades e tarefas detalhadas","ru":"Узнайте, как использовать Ralph Deep Init для инициализации сложных проектов с несколькими функциями и подробными задачами с помощью ИИ Агентов","ar":"تعلم كيفية استخدام Ralph Deep Init لتحديث المشاريع المعقدة مع عدة وظائف ومهام مفصلة مع وكلاء الذكاء الاصطناعي"},"definition":{"en":"ralph-deep-init is a universal MCP documentation pipeline for AI assistants that initializes projects with a multi-stage process, creating detailed tasks and organizing them by architectural concerns.","zh":"Ralph Deep Init 是一个用于项目初始化的 AI 工具，通过分解项目为功能架构组来生成详细任务","ja":"Ralph Deep Init は、プロジェクトを機能アーキテクチャ グループに分解して詳細なタスクを生成するプロジェクト初期化の AI ツールです","ko":"Ralph Deep Init은 프로젝트를 기능 아키텍처 그룹으로 분해하여 상세한 태스크를 생성하는 프로젝트 초기화 AI 도구입니다","es":"ralph-deep-init es una habilidad de AI Agent que realiza una inicialización de proyecto compleja y detallada","fr":"ralph-deep-init est une compétence d''outils d''IA qui effectue une initialisation de projet complexe et détaillée","de":"ralph-deep-init ist eine Fähigkeit von AI-Tools, die eine komplexe und detaillierte Projektinitialisierung durchführt","pt":"O que é Ralph Deep Init? É uma habilidade de inicialização de projetos que gera uma lista de tarefas detalhadas","ru":"Что такое Ralph Deep Init? Это навык инициализации проектов, генерирующий подробный список задач с помощью ИИ Агентов","ar":"ما هو Ralph Deep Init? هو مهارة لتحديث المشاريع التي تولد قائمة مفصلة من المهام مع وكلاء الذكاء الاصطناعي"},"features":{"en":["Generates a large, well-organized backlog with 20-40+ detailed tasks","Breaks down projects into functional architectural groups","Organizes tasks by architectural concerns","Supports complex projects with multiple distinct functional areas","Provides an alternative to ralph-initialize for comprehensive project setup","Creates a detailed project initialization pipeline"],"zh":["生成大规模、组织良好的任务_backlog","将项目分解为功能架构组","支持20-40+个详细任务","任务组织由架构关注点驱动","适用于具有多个功能区域的复杂项目"],"ja":["大規模で整理されたタスク バックログを生成","プロジェクトを機能アーキテクチャ グループに分解","20-40+ の詳細なタスクをサポート","タスクの組織はアーキテクチャの関心によって駆動","複数の機能エリアを持つ複雑なプロジェクトに適している"],"ko":["대규모의 구성된 태스크 백로그 생성","프로젝트를 기능 아키텍처 그룹으로 분해","20-40+개의 상세한 태스크 지원","태스크 구성은 아키텍처의 관심에 의해 구동","복수의 기능 영역을 갖는 복잡한 프로젝트에 적합"],"es":["Generación de una gran cantidad de tareas detalladas","Organización de tareas por arquitectura","Inicialización de proyectos complejos con múltiples características","Creación de una gran cantidad de tareas organizadas por grupos de arquitectura funcional","Soporte para proyectos con múltiples áreas funcionales distintas"],"fr":["Génération d''un grand nombre de tâches détaillées","Organisation des tâches par architecture","Initialisation de projets complexes avec de multiples fonctionnalités","Création d''un grand nombre de tâches organisées par groupes d''architecture fonctionnelle","Prise en charge de projets avec de multiples domaines fonctionnels distincts"],"de":["Generierung einer großen Anzahl detaillierter Aufgaben","Organisation von Aufgaben nach Architektur","Initialisierung komplexer Projekte mit mehreren Funktionen","Erstellung einer großen Anzahl von Aufgaben, die nach funktionalen Architekturgruppen organisiert sind","Unterstützung von Projekten mit mehreren deutlich unterschiedlichen Funktionsbereichen"],"pt":["Inicialização de projetos complexos com múltiplas funcionalidades","Geração de lista de tarefas detalhadas organizadas por grupos arquiteturais","Suporte a projetos com 20-40+ tarefas","Organização de tarefas por preocupações arquiteturais","Suporte a projetos com múltiplas áreas funcionais distintas"],"ru":["Инициализация сложных проектов с несколькими функциями с помощью ИИ Агентов","Генерация подробного списка задач, организованных по архитектурным группам","Поддержка проектов с 20-40+ задачами","Организация задач по архитектурным проблемам","Поддержка проектов с несколькими функциональными областями"],"ar":["تحديث المشاريع المعقدة مع عدة وظائف مع وكلاء الذكاء الاصطناعي","توليد قائمة مفصلة من المهام المنظمة حسب المجموعات المعمارية","دعم المشاريع التي تحتوي على 20-40+ مهام","تنظيم المهام حسب القضايا المعمارية","دعم المشاريع التي تحتوي على عدة مناطق وظيفية متميزة"]},"keywords":{"en":["how to use ralph-deep-init","ralph-deep-init alternative","ralph-deep-init setup guide","what is ralph-deep-init","ralph-deep-init vs ralph-initialize","ralph-deep-init install","complex project initialization","multi-stage project setup","MCP documentation pipeline"],"zh":["Ralph Deep Init","AI 辅助工具","项目初始化","任务组织","功能架构组","大规模项目","复杂项目管理"],"ja":["Ralph Deep Init","AI エージェント","プロジェクト初期化","タスク組織","機能アーキテクチャ グループ","大規模プロジェクト","複雑なプロジェクト管理"],"ko":["Ralph Deep Init","AI 에이전트","프로젝트 초기화","태스크 구성","기능 아키텍처 그룹","대규모 프로젝트","복잡한 프로젝트 관리"],"es":["ralph-deep-init","AI Agent","inicialización de proyecto","tareas detalladas","arquitectura de proyecto","proyectos complejos","herramientas de desarrollo","integración de AI"],"fr":["ralph-deep-init","outils d''IA","initialisation de projet","tâches détaillées","architecture de projet","projets complexes","outils de développement","intégration d''IA"],"de":["ralph-deep-init","AI-Tools","Projektinitialisierung","detaillierte Aufgaben","Projektarchitektur","komplexe Projekte","Entwicklungstools","AI-Integration"],"pt":["Ralph Deep Init","inicialização de projetos","projetos complexos","geração de lista de tarefas","grupos arquiteturais","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Ralph Deep Init","ИИ Агенты","инициализация проектов","сложные проекты","генерация списка задач","архитектурные группы","разработка программного обеспечения","инструменты разработки"],"ar":["Ralph Deep Init","وكلاء الذكاء الاصطناعي","تحديث المشاريع","المشاريع المعقدة","توليد قائمة المهام","المجموعات المعمارية","تطوير البرمجيات","أدوات التطوير"]}},"owner":"jusedit","repo":"any-docs-mcp","repoPath":"jusedit/any-docs-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.518Z","topics":[],"category":"community","skillMd":{"name":"ralph-deep-init","description":"Build a comprehensive project backlog through multi-stage architectural analysis. Creates 6 functional groups and generates detailed tasks for each. Use when you need a large, well-organized backlog for complex projects.","bodyPreview":"# Ralph Deep Initialization\n\nThis skill performs a comprehensive, multi-stage project initialization that generates a large, well-organized backlog by breaking down the project into functional architectural groups.\n\n## When to Use This Skill\n\nUse ralph-deep-init instead of ralph-initialize when:\n\n- Building a complex project with many features\n- Need 20-40+ detailed tasks in the backlog\n- Want tasks organized by architectural concerns\n- Project has multiple distinct functional areas\n\n## Prerequi","body":"# Ralph Deep Initialization\n\nThis skill performs a comprehensive, multi-stage project initialization that generates a large, well-organized backlog by breaking down the project into functional architectural groups.\n\n## When to Use This Skill\n\nUse ralph-deep-init instead of ralph-initialize when:\n\n- Building a complex project with many features\n- Need 20-40+ detailed tasks in the backlog\n- Want tasks organized by architectural concerns\n- Project has multiple distinct functional areas\n\n## Prerequisites\n\n- Git repository initialized\n- No existing `prd.json` (or user approves overwrite)\n- Clear understanding of project requirements\n\n## Multi-Stage Process\n\n### Phase 1: Architecture\n\n**Goal:** Initialize the project structure and define the architectural map.\n\n1. **Analyze Request**\n   - Ask: \"What do you want to build?\" if not already provided\n   - Gather comprehensive project requirements\n\n2. **Create Foundation Files**\n   - `progress.md` - Standard Ralph progress log\n   - `.windsurf/rules/tech-stack.md` - Tech stack & conventions\n   - `init_progress.txt` - Temporary initialization tracking\n\n3. **Generate Architecture**\n   - Identify **6 distinct functional groups** needed for this project\n   - Examples: Auth, Database, API, Frontend, Testing, DevOps\n   - Create `groups.json` containing ONLY a JSON array of these string names\n   - Format: `[\"Group1\", \"Group2\", \"Group3\", \"Group4\", \"Group5\", \"Group6\"]`\n\n### Phase 2: Expansion (6 Iterations)\n\n**Goal:** Generate detailed tasks for each functional group.\n\nFor each of the 6 groups (iterate 1 through 6):\n\n1. **Select Target:** Pick group N from `groups.json`\n2. **Generate Tasks:** Create 3-5 detailed implementation tasks for this group\n3. **Write to File:** Save to `partial_N.json`\n\n**Task Template:**\n\nUse `.windsurf/skills/ralph-deep-init/task-examples.json` as the reference schema for each `partial_N.json`.\n\n### Phase 3: Assembly\n\n**Goal:** Compile the final Product Requirements Document.\n\n1. **Create PRD**\n   - Create `prd.json` (use `.windsurf/skills/ralph-initialize/prd-template.json` as reference)\n   - Read all `partial_*.json` files\n   - Merge all `tasks` arrays into the `backlog` field\n   - Ensure valid JSON structure\n\n2. **Cleanup**\n   - Delete `groups.json`\n   - Delete all `partial_*.json` files\n   - Keep `init_progress.txt` for reference\n\n3. **Report**\n   - Announce: \"Initialization Complete. Backlog created with [X] tasks.\"\n   - Summarize task breakdown by group\n\n## Supporting Resources\n\nReference these files:\n\n- `architecture-examples.md` - Sample functional group breakdowns\n- `task-examples.json` - Well-formed task examples\n- `groups-template.json` - Template for groups array\n\n## Success Criteria\n\nDeep initialization is complete when:\n\n- ✅ `prd.json` exists with 20+ tasks\n- ✅ Tasks are organized by functional groups\n- ✅ All tasks have `passes: false`\n- ✅ Each task has clear acceptance criteria\n- ✅ `progress.md` exists\n- ✅ Temporary files are cleaned up\n\n## Tips\n\n- Choose groups that represent distinct technical concerns\n- Ensure tasks within a group are cohesive\n- Order tasks to respect dependencies\n- Include infrastructure/testing as separate groups\n- Aim for 3-5 tasks per group (total: 18-30 tasks)\n"},"lastSynced":"2026-03-08T02:10:38.319Z","agentAnalysis":{"suitability":{"en":"Ideal for Complex Project Management Agents needing advanced backlog organization and task breakdown capabilities.","zh":"适合需要高级待办事项组织和任务分解能力的复杂项目管理代理。","ja":"複雑なプロジェクト管理エージェントが高度なバックログの組織化とタスクの分解機能を必要とする場合に適しています。","ko":"고급 백로그 조직화 및 태스크 분할 기능이 필요한 복잡한 프로젝트 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Proyectos Complejos que necesitan una organización avanzada de backlog y capacidades de desglose de tareas.","fr":"Idéal pour les Agents de Gestion de Projets Complexes ayant besoin d''une organisation de backlog avancée et de capacités de décomposition de tâches.","de":"Ideal für komplexe Projektmanagement-Agents, die eine erweiterte Backlog-Organisation und Aufgabenzerlegungsfähigkeiten benötigen.","pt":"Ideal para Agentes de Gerenciamento de Projetos Complexos que necessitam de organização avançada de backlog e capacidades de quebra de tarefas.","ru":"Идеально для Сложных Агентов Управления Проектами, требующих передовой организации бэклога и возможностей разбиения задач.","ar":"مثالي للوكلاء إدارة المشاريع المعقدة الذين يحتاجون إلى تنظيم متقدم للخلفية وقدرات تقسيم المهام."},"recommendation":{"en":"Empowers agents to generate large, well-organized backlogs by breaking down complex projects into functional architectural groups, utilizing multi-stage project initialization and organizing tasks by architectural concerns.","zh":"通过将复杂的项目分解为功能性架构组，利用多阶段项目初始化，并按架构问题组织任务，赋予代理生成大型、组织良好的待办事项列表的能力。","ja":"複雑なプロジェクトを機能的なアーキテクチャグループに分解し、多段階のプロジェクト初期化を利用し、アーキテクチャの問題でタスクを整理することで、大規模で整理されたバックログを生成するエージェントの能力を提供します。","ko":"복잡한 프로젝트를 기능적 아키텍처 그룹으로 분해하고 다단계 프로젝트 초기화를 사용하며 아키텍처 문제에 따라 태스크를 조직하여 대형으로 정리된 백로그를 생성하는 에이전트의 능력을 부여합니다.","es":"Habilita a los agentes a generar grandes backlogs bien organizados al descomponer proyectos complejos en grupos arquitectónicos funcionales, utilizando la inicialización de proyectos multietapa y organizando tareas por preocupaciones arquitectónicas.","fr":"Permet aux agents de générer de grands backlogs bien organisés en décomposant des projets complexes en groupes architecturaux fonctionnels, en utilisant l''initialisation de projets multietapas et en organisant les tâches par des préoccupations architecturales.","de":"Ermächtigt Agenten, große, gut organisierte Backlogs zu generieren, indem komplexe Projekte in funktionale architektonische Gruppen aufgeteilt werden, unter Verwendung der mehrstufigen Projekteinitalisierung und der Organisation von Aufgaben nach architektonischen Belangen.","pt":"Habilita agentes a gerar grandes backlogs bem organizados, quebrando projetos complexos em grupos arquiteturais funcionais, utilizando inicialização de projeto em várias etapas e organizando tarefas por preocupações arquiteturais.","ru":"Наделяет агентов возможностью генерировать большие, хорошо организованные бэклоги, разбивая сложные проекты на функциональные архитектурные группы, используя многоэтапную инициализацию проекта и организуя задачи по архитектурным проблемам.","ar":"تمكين الوكلاء من توليد سجلات كبيرة ومنظمة جيدًا عن طريق تقسيم المشاريع المعقدة إلى مجموعات وظيفية معمارية، باستخدام 초기ات المشروع المتعددة المراحل وتنظيم المهام حسب القضايا المعمارية."},"useCases":{"en":["Initializing complex projects with multiple features","Generating detailed task lists organized by architectural concerns","Breaking down projects into distinct functional areas"],"zh":["使用多个功能初始化复杂项目","生成按架构问题组织的详细任务列表","将项目分解为不同的功能区域"],"ja":["複数の機能を持つ複雑なプロジェクトの初期化","アーキテクチャの問題で整理された詳細タスクリストの生成","プロジェクトを異なる機能領域に分解"],"ko":["여러 기능을 가진 복잡한 프로젝트 초기화","아키텍처 문제로 정리된 상세 태스크 목록 생성","프로젝트를 다른 기능 영역으로 분해"],"es":["Inicialización de proyectos complejos con varias características","Generación de listas de tareas detalladas organizadas por preocupaciones arquitectónicas","Descomposición de proyectos en áreas funcionales distintas"],"fr":["Initialisation de projets complexes avec plusieurs fonctionnalités","Génération de listes de tâches détaillées organisées par des préoccupations architecturales","Décomposition de projets en domaines fonctionnels distincts"],"de":["Initialisierung komplexer Projekte mit mehreren Funktionen","Generierung detaillierter Aufgabenlisten, die nach architektonischen Belangen organisiert sind","Aufteilung von Projekten in unterschiedliche funktionale Bereiche"],"pt":["Inicializando projetos complexos com múltiplas funcionalidades","Gerando listas de tarefas detalhadas organizadas por preocupações arquiteturais","Quebrando projetos em áreas funcionais distintas"],"ru":["Инициализация сложных проектов с несколькими функциями","Генерация подробных списков задач, организованных по архитектурным проблемам","Разбиение проектов на отдельные функциональные области"],"ar":["ت初始化 المشاريع المعقدة المتعددة المزايا","توليد قوائم مهام مفصلة ومنظمة حسب القضايا المعمارية","تقسيم المشاريع إلى مجالات وظيفية متميزة"]},"limitations":{"en":["Requires projects with multiple features or distinct functional areas","Ideal for projects needing 20-40+ detailed tasks in the backlog"],"zh":["需要具有多个功能或不同的功能区域的项目","适合需要20-40个以上详细任务的待办事项项目"],"ja":["複数の機能または異なる機能領域を持つプロジェクトが必要","20-40以上の詳細タスクを待ち行列に必要とするプロジェクトに適しています"],"ko":["여러 기능 또는 다른 기능 영역을 가진 프로젝트가 필요","20-40개 이상의 상세 태스크가 백로그에 필요한 프로젝트에 적합"],"es":["Requiere proyectos con varias características o áreas funcionales distintas","Ideal para proyectos que necesitan 20-40+ tareas detalladas en el backlog"],"fr":["Nécessite des projets avec plusieurs fonctionnalités ou des domaines fonctionnels distincts","Idéal pour les projets nécessitant 20-40+ tâches détaillées dans le backlog"],"de":["Benötigt Projekte mit mehreren Funktionen oder unterschiedlichen funktionalen Bereichen","Ideal für Projekte, die 20-40+ detaillierte Aufgaben im Backlog benötigen"],"pt":["Requer projetos com múltiplas funcionalidades ou áreas funcionais distintas","Ideal para projetos que necessitam de 20-40+ tarefas detalhadas no backlog"],"ru":["Требует проектов с несколькими функциями или отдельными функциональными областями","Идеально для проектов, требующих 20-40+ подробных задач в бэклоге"],"ar":["يتطلب مشاريع ذات ميزات متعددة أو مجالات وظيفية متميزة","مثالي للمشاريع التي تحتاج إلى 20-40+ مهام مفصلة في السجل"]},"version":4},"contentHash":"acb124344ca7a6832d0e58f6765af141b2ca4418eac582e4585fff9205ce46d5","qualityScore":41}');
