INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jusedit/any-docs-mcp/ralph-deep-init', 'ralph-deep-init', 'jusedit', 'any-docs-mcp', 'community', 'ralph-deep-init jusedit any-docs-mcp community The ralph-deep-init skill performs a comprehensive project initialization, generating a large, well-organized backlog by breaking down the project into functional architectural groups, ideal for complex projects with multiple features. Ralph Deep Init 是一个通用文档管道，用于 AI 辅助工具的项目初始化和任务组织 Ralph Deep Init は、AI エージェントのプロジェクト初期化とタスク組織のための汎用ドキュメント パイプラインです Ralph Deep Init은 AI 에이전트의 프로젝트 초기화와 태스크 구성의ための 범용 문서 파이프라인입니다 ralph-deep-init es una habilidad que realiza una inicialización de proyecto integral, generando una gran cantidad de tareas detalladas organizadas por arquitectura ralph-deep-init est une compétence qui effectue une initialisation de projet complète, générant un grand nombre de tâches détaillées organisées par architecture ralph-deep-init ist eine Fähigkeit, die eine umfassende Projektinitialisierung durchführt und eine große Anzahl detaillierter Aufgaben generiert, die nach Architektur organisiert sind O Ralph Deep Init é uma habilidade que realiza uma inicialização abrangente de projetos, gerando uma grande lista de tarefas organizadas por grupos arquiteturais Ralph Deep Init — это навык, который выполняет комплексную инициализацию проектов, генерируя большой список задач, организованных по архитектурным группам с помощью ИИ Агентов Ralph Deep Init هو مهارة يقوم بتحديث المشاريع الشاملة، مما يولد قائمة كبيرة من المهام المنظمة حسب المجموعات المعمارية مع وكلاء الذكاء الاصطناعي how to use ralph-deep-init ralph-deep-init alternative ralph-deep-init setup guide what is ralph-deep-init ralph-deep-init vs ralph-initialize ralph-deep-init install complex project initialization multi-stage project setup MCP documentation pipeline Ralph Deep Init AI 辅助工具 项目初始化 任务组织 功能架构组 大规模项目 复杂项目管理 Generates a large, well-organized backlog with 20-40+ detailed tasks Breaks down projects into functional architectural groups Organizes tasks by architectural concerns Supports complex projects with multiple distinct functional areas Provides an alternative to ralph-initialize for comprehensive project setup Creates a detailed project initialization pipeline ralph-deep-init is a universal MCP documentation pipeline for AI assistants that initializes projects with a multi-stage process, creating detailed tasks and organizing them by architectural concerns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('QuixiAI/Hexis/email-digest', 'community', 'QuixiAI', 'Hexis', 'QuixiAI/Hexis', 'email-digest', 0, 0, 41, '2026-03-08T01:57:15.577Z', '2026-03-08T02:11:48.745Z', 'd1b51c7ba98c5641db640caeb2c99e1c9687b119c511ff6417bae8d34d081e66', '{"id":"QuixiAI/Hexis/email-digest","name":"email-digest","description":{"en":"The email-digest skill processes incoming emails into structured memories, extracting action items and surfacing threads that need attention, benefiting AI agents and developers.","zh":"Email Digest AIエージェント可以处理和摘要电子邮件，提取重要信息","ja":"Email Digest AIエージェントはメールを処理し、重要な情報を抽出する","ko":"Email Digest AI 에이전트는 이메일을 처리하고 요약하여 중요한 정보를 제공","es":"Email-digest es un flujo de trabajo que procesa correos electrónicos entrantes en memorias estructuradas, extrae elementos de acción y resalta hilos que requieren atención.","fr":"Email-digest est un workflow qui traite les emails entrants en mémoires structurées, extrait les éléments d''action et met en avant les threads qui nécessitent une attention.","de":"Email-Digest ist ein Workflow, der eingehende E-Mails in strukturierte Erinnerungen verarbeitet, Aktionselemente extrahiert und Threads hervorhebt, die Aufmerksamkeit erfordern.","pt":"O email-digest é um fluxo de trabalho que processa e-mails e extrai itens de ação importantes","ru":"ИИ Агент email-digest представляет собой рабочий процесс, который обрабатывает входящие электронные письма и извлекает важные действия","ar":"البريد الإلكتروني للتلبية هو عملية工作 لمعالجة البريد الوارد واستخراج عناصر العمل المهمة"},"seo":{"title":{"en":"email-digest: Automated Email Workflow Setup Guide | AI A...","zh":"Email Digest Setup Guide - AIエージェント技术","ja":"Email Digest ベストプラクティス - AIエージェントを使用したメール処理","ko":"Email Digest 구성 가이드 - AI 에이전트를 사용한 이메일 요약","es":"Configuración de email-digest: Guía de implementación","fr":"Mise en place de email-digest: Meilleures pratiques","de":"Email-Digest Einrichtung: Leitfaden für Entwickler","pt":"Guia de Configuração do email-digest: Processamento de E-...","ru":"Настройка ИИ Агента email-digest: Работа с входящими элек...","ar":"دليل إعداد البريد الإلكتروني للتلبية: معالجة البريد الوارد"},"description":{"en":"Discover how to automate email processing with email-digest. Learn to extract action items and surface important threads with this step-by-step guide.","zh":"使用Email Digest AIエージェント处理和摘要电子邮件，提高工作效率","ja":"Email Digest AIエージェントを使用してメールを処理し、重要な情報を抽出","ko":"Email Digest AI 에이전트를 사용하여 이메일을 처리하고 요약하여 생산성을 향상","es":"Aprende a integrar email-digest en tus proyectos con esta guía detallada. Descubre cómo procesar correos electrónicos entrantes y extraer elementos de acción.","fr":"Découvrez comment mettre en place email-digest pour traiter les emails entrants et extraire les éléments d''action. Guide étape par étape pour les développeurs.","de":"Erfahren Sie, wie Sie email-digest in Ihre Projekte integrieren können. Schritt-für-Schritt-Anleitung zum Verarbeiten von E-Mails und Extrahieren von Aktions...","pt":"Aprenda a configurar o email-digest para processar e-mails e extrair itens de ação importantes","ru":"Узнайте, как настроить ИИ Агента email-digest для обработки входящих электронных писем и извлечения важных действий","ar":"تعلم كيفية إعداد البريد الإلكتروني للتلبية لمعالجة البريد الوارد واستخراج عناصر العمل المهمة"},"definition":{"en":"email-digest is a workflow process that automates email processing, using recall to check for new mail and extract relevant information.","zh":"Email Digest 是一种AIエージェント技术，用于处理和摘要电子邮件","ja":"Email Digest はAIエージェントを使用したメール処理技術","ko":"Email Digest는 이메일을 처리하고 요약하는 AI 에이전트 기술","es":"Email-digest es un agente de IA que procesa correos electrónicos para extraer información relevante.","fr":"Email-digest est un outil d''IA qui traite les emails pour extraire des informations pertinentes.","de":"Email-Digest ist ein KI-Tool, das E-Mails verarbeitet, um relevante Informationen zu extrahieren.","pt":"O que é email-digest? Um fluxo de trabalho que processa e-mails e extrai itens de ação","ru":"Что такое ИИ Агент email-digest? Рабочий процесс, который обрабатывает входящие электронные письма и извлекает действия","ar":"ما هو البريد الإلكتروني للتلبية؟ عملية لمعالجة البريد الوارد واستخراج عناصر العمل"},"features":{"en":["Processes incoming emails into structured memories using recall","Extracts action items from emails for prioritized attention","Surfaces threads that need attention based on recency and importance","Integrates with autonomous heartbeats to check for new mail","Supports daily briefing generation with email highlights","Uses step-by-step methodology for efficient email workflow management"],"zh":["使用recall检查电子邮件的新旧","提取电子邮件中的操作项","处理和摘要电子邮件","支持autonomous heartbeats","支持daily briefing"],"ja":["recallを使用してメールの新旧を確認","メールからアクションアイテムを抽出","メールを処理し、摘要する","autonomous heartbeatsをサポート","daily briefingをサポート"],"ko":["recall를 사용하여 이메일의 새로움을 확인","이메일에서 작업 항목을 추출","이메일을 처리하고 요약","autonomous heartbeats 지원","daily briefing 지원"],"es":["Procesamiento de correos electrónicos entrantes en memorias estructuradas","Extracción de elementos de acción","Resaltado de hilos que requieren atención","Uso de la función de recuerdo para verificar la recencia de los correos electrónicos","Compatibilidad con comandos de voz como \"qué hay en mi bandeja de entrada\""],"fr":["Traitement des emails entrants en mémoires structurées","Extraction des éléments d''action","Mise en avant des threads qui nécessitent une attention","Utilisation de la fonction de rappel pour vérifier la récence des emails","Compatibilité avec les commandes vocales comme \"qu''est-ce qui est dans ma boîte de réception\""],"de":["Verarbeitung von E-Mails in strukturierte Erinnerungen","Extraktion von Aktionselementen","Hervorhebung von Threads, die Aufmerksamkeit erfordern","Verwendung der Funktion zum Zurückrufen, um die Aktualität von E-Mails zu überprüfen","Kompatibilität mit Sprachbefehlen wie \"was ist in meinem Posteingang\""],"pt":["Processamento de e-mails em lotes","Extração de itens de ação importantes","Verificação de recência de e-mails","Integração com recall para verificar novos e-mails","Suporte a autonomia para verificar e-mails em segundo plano"],"ru":["Обработка входящих электронных писем в пакетном режиме","Извлечение важных действий","Проверка свежести электронных писем","Интеграция с recall для проверки новых электронных писем","Поддержка автономности для проверки электронных писем в фоновом режиме"],"ar":["معالجة البريد الإلكتروني في مجموعات","استخراج عناصر العمل المهمة","التحقق من حداثة البريد الإلكتروني","التكامل مع recall للتحقق من البريد الإلكتروني الجديد","دعم التوافق لالتقاط البريد الإلكتروني في الخلفية"]},"keywords":{"en":["how to use email-digest","email-digest setup guide","email-digest alternative","automated email workflow","email-digest vs mailparser","what is email-digest","email-digest install","email processing automation"],"zh":["Email Digest AIエージェント","电子邮件处理","电子邮件摘要","AIエージェント技术","recall","autonomous heartbeats","daily briefing"],"ja":["Email Digest AIエージェント","メール処理","メール摘要","AIエージェント技術","recall","autonomous heartbeats","daily briefing"],"ko":["Email Digest AI 에이전트","이메일 처리","이메일 요약","AI 에이전트 기술","recall","autonomous heartbeats","daily briefing"],"es":["email-digest","agente de IA para correo electrónico","procesamiento de correo electrónico","extracción de información de correo electrónico","hilos de correo electrónico","recuerdo de correo electrónico","comandos de voz para correo electrónico"],"fr":["email-digest","outil d''IA pour email","traitement d''email","extraction d''informations d''email","threads d''email","rappel d''email","commandes vocales pour email"],"de":["email-digest","KI-Tool für E-Mail","E-Mail-Verarbeitung","Extraktion von E-Mail-Informationen","E-Mail-Threads","E-Mail-Rückruf","Sprachbefehle für E-Mail"],"pt":["email-digest","processamento de e-mails","extração de itens de ação","verificação de recência","integração com recall","autonomia em segundo plano","fluxo de trabalho de e-mail","ferramentas de produtividade"],"ru":["ИИ Агент email-digest","обработка входящих электронных писем","извлечение важных действий","проверка свежести электронных писем","интеграция с recall","автономность в фоновом режиме","рабочий процесс электронной почты","инструменты производительности"],"ar":["البريد الإلكتروني للتلبية","معالجة البريد الإلكتروني","استخراج عناصر العمل المهمة","التحقق من حداثة البريد الإلكتروني","التكامل مع recall","دعم التوافق في الخلفية","عملية البريد الإلكتروني","أدوات الإنتاجية"]}},"owner":"QuixiAI","repo":"Hexis","repoPath":"QuixiAI/Hexis","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.577Z","topics":[],"category":"community","skillMd":{"name":"email-digest","description":"Digest and ingest emails into memory, surfacing important threads and action items","bodyPreview":"# Email Digest Workflow\n\nProcess incoming emails into structured memories, extract action items, and surface threads that need attention.\n\n## When to Use\n\n- During autonomous heartbeats to check for new mail since the last digest\n- When the user asks \"what''s in my inbox\" or \"any important emails\"\n- When a goal depends on information that may have arrived via email\n- When preparing a daily briefing that includes email highlights\n\n## Step-by-Step Methodology\n\n1. **Check recency**: Use `recall` to","body":"# Email Digest Workflow\n\nProcess incoming emails into structured memories, extract action items, and surface threads that need attention.\n\n## When to Use\n\n- During autonomous heartbeats to check for new mail since the last digest\n- When the user asks \"what''s in my inbox\" or \"any important emails\"\n- When a goal depends on information that may have arrived via email\n- When preparing a daily briefing that includes email highlights\n\n## Step-by-Step Methodology\n\n1. **Check recency**: Use `recall` to find when the last email digest ran. Avoid re-processing messages already ingested.\n2. **List new emails**: Call `list_emails` with a date filter to fetch unread or recent messages. Start with the inbox; expand to other labels only if the user has configured them.\n3. **Triage by sender and subject**: Scan the list for high-signal indicators -- known contacts, reply chains the user is on, calendar invites, and keywords matching active goals.\n4. **Read priority threads**: Use `read_email` on the top 5-10 most relevant messages. Do not read every email; batch processing wastes energy and context.\n5. **Extract action items**: For each important email, identify: (a) what is being asked, (b) who is asking, (c) any deadline mentioned, (d) whether a reply is expected.\n6. **Store findings**: Use `remember` to persist action items as episodic memories with high importance. Tag with the sender, thread ID, and any relevant goal.\n7. **Surface urgency**: If an email requires a time-sensitive response, flag it in the heartbeat result so it can be raised to the user at next opportunity.\n\n## Quality Guidelines\n\n- Never store raw email bodies as memories. Summarize and extract the salient points.\n- Respect privacy: do not log email content to external services. All storage stays in the local Postgres brain.\n- When multiple emails belong to the same thread, consolidate into a single memory rather than creating duplicates.\n- If credentials are missing or expired, fail gracefully and note the issue rather than retrying in a loop.\n- Prefer recalling existing contact memories to enrich email context (who is this person, what is the relationship).\n"},"lastSynced":"2026-03-08T02:11:48.745Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing automated email processing and action item extraction.","zh":"适用于像 Cursor、Windsurf 和 Claude Code 这样的 AI Agents，它们需要自动化的电子邮件处理和操作项提取。","ja":"Cursor、Windsurf、Claude Code などのAIエージェントに適しています。自動化された電子メール処理とアクションアイテムの抽出が必要です。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 자동화 된 이메일 처리 및 작업 항목 추출이 필요합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan procesamiento de correo electrónico automatizado y extracción de elementos de acción.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant un traitement automatisé de courriels et une extraction d''éléments d''action.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die ein automatisiertes E-Mail-Verarbeitung und eine Extraktion von Aktionselementen benötigen.","pt":"Ideal para agentes de IA como Cursor, Windsurf e Claude Code que necessitam de processamento de e-mail automatizado e extração de itens de ação.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих автоматизированной обработки электронной почты и извлечения элементов действий.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يحتاجون إلى معالجة البريد الإلكتروني الآلية واستخراج عناصر الإجراء."},"recommendation":{"en":"Empowers agents to process incoming emails into structured memories, extracting action items and surfacing threads that need attention using recall and autonomous heartbeats, making it a crucial tool for tasks that depend on email information and daily briefings.","zh":"赋予代理处理传入电子邮件的能力，将其转换为结构化的记忆，提取操作项，并使用回忆和自主心跳来突出需要关注的线程，使其成为依赖电子邮件信息和每日简报的任务的重要工具。","ja":"エージェントに、受信メールを構造化されたメモリに変換する機能を与え、操作アイテムを抽出し、リコールと自律的な心拍を使用して、注目が必要なスレッドを浮き彫りにすることで、電子メール情報と日次ブリーフィングに依存するタスクの重要なツールになる。","ko":"에이전트가 전자 메일을 구조화된 메모리로 변환하여 작업 항목을 추출하고 리콜 및 자율적인 심박수를 사용하여 주의가 필요한 스레드를浮き彫りに하는 기능을 부여하여 전자 메일 정보 및 일일 브리핑에 의존하는 작업에 중요한 도구가 되도록 합니다.","es":"Permite a los agentes procesar los correos electrónicos entrantes en memorias estructuradas, extrayendo elementos de acción y resaltando los hilos que necesitan atención utilizando la memoria y los latidos autónomos, lo que lo convierte en una herramienta crucial para las tareas que dependen de la información de correo electrónico y las informes diarios.","fr":"Permet aux agents de traiter les courriels entrants en mémoires structurées, en extrayant les éléments d''action et en mettant en évidence les fils qui nécessitent une attention en utilisant la mémoire et les battements autonomes, ce qui en fait un outil crucial pour les tâches qui dépendent des informations de courriel et des briefings quotidiens.","de":"Ermöglicht es Agenten, eingehende E-Mails in strukturierte Erinnerungen zu verarbeiten, Aktionselemente zu extrahieren und Threads zu stellen, die Aufmerksamkeit benötigen, indem Recall und autonome Herzschläge verwendet werden, was es zu einem entscheidenden Werkzeug für Aufgaben macht, die von E-Mail-Informationen und täglichen Briefings abhängen.","pt":"Habilita os agentes a processar e-mails recebidos em memórias estruturadas, extraíndo itens de ação e destacando threads que precisam de atenção usando recall e batimentos cardíacos autônomos, tornando-o uma ferramenta crucial para tarefas que dependem de informações de e-mail e briefings diários.","ru":"Наделяет агентов способностью обрабатывать входящие электронные письма в структурированные воспоминания, извлекая элементы действий и выделяя темы, требующие внимания, используя реколл и автономные сердечные ритмы, что делает его важнейшим инструментом для задач, зависящих от информации электронной почты и ежедневных брифингов.","ar":"يمنح الوكلاء القدرة على معالجة البريد الإلكتروني الوارد في ذكريات منظمّة، واستخراج عناصر الإجراء وإبراز المواضيع التي تحتاج إلى الانتباه باستخدام الاستدعاء والنبضات الذاتية، مما يجعله أداة حاسمة للمهام التي تعتمد على معلومات البريد الإلكتروني والتقريرات اليومية."},"useCases":{"en":["Automating email inbox monitoring for new and important emails","Generating daily briefings that include email highlights and action items","Debugging email-dependent goals by checking for new mail since the last digest"],"zh":["自动监控电子邮件收件箱以获取新邮件和重要邮件","生成每日简报，包括电子邮件亮点和操作项","通过检查最后一次摘要以来的新邮件来调试依赖电子邮件的目标"],"ja":["新しいメールや重要なメールを取得するために電子メール受信トレイの自動監視","電子メールのハイライトや操作アイテムを含む日次ブリーフィングの生成","最後のダイジェスト以降の新しいメールを確認することで、電子メール依存の目標をデバッグ"],"ko":["새로운 메일 및 중요한 메일을 얻기 위해 전자 메일 수신함을 자동으로 모니터링","전자 메일의 하이라이트 및 작업 항목을 포함하는 일일 브리핑 생성","마지막 요약 이후의 새로운 메일을 확인하여 전자 메일 종속 목표를 디버깅"],"es":["Automatización de la supervisión de la bandeja de entrada de correo electrónico para nuevos y importantes correos electrónicos","Generación de informes diarios que incluyen destacados de correo electrónico y elementos de acción","Depuración de objetivos que dependen de correo electrónico comprobando nuevo correo desde el último resumen"],"fr":["Automatisation de la surveillance de la boîte de réception de courriels pour les nouveaux et importants courriels","Génération de briefings quotidiens qui incluent les faits saillants de courriel et les éléments d''action","Débogage des objectifs qui dépendent de courriel en vérifiant les nouveaux courriels depuis le dernier résumé"],"de":["Automatisierung der Überwachung des E-Mail-Posteingangs für neue und wichtige E-Mails","Erstellung von täglichen Berichten, die E-Mail-Highlights und Aktionselemente enthalten","Fehlerbehebung von E-Mail-abhängigen Zielen durch Überprüfung neuer E-Mails seit der letzten Zusammenfassung"],"pt":["Automatizar o monitoramento da caixa de entrada de e-mail para e-mails novos e importantes","Gerar briefings diários que incluem destaques de e-mail e itens de ação","Depurar metas dependentes de e-mail verificando se há novo correio desde o último resumo"],"ru":["Автоматизировать мониторинг входящей почты для новых и важных электронных писем","Генерировать ежедневные брифинги, включающие обзор электронной почты и элементы действий","Отладить цели, зависящие от электронной почты, проверив наличие новых писем с момента последнего сводного отчета"],"ar":["توفير مراقبة آلية لصندوق الوارد لرسائل البريد الإلكتروني الجديدة والمهمة","توليد تقارير يومية تشمل أبرز البريد الإلكتروني وعناصر الإجراء","تصحيح الأهداف التابعة للبريد الإلكتروني من خلال التحقق من وجود بريد جديد منذ آخر تلخيص"]},"limitations":{"en":["Requires email account access and credentials","Dependent on recall functionality for checking email recency"],"zh":["需要电子邮件帐户访问和凭据","依赖回忆功能来检查电子邮件的新鲜度"],"ja":["電子メールアカウントへのアクセスと資格情報が必要","電子メールの新鮮度を確認するためにリコール機能に依存"],"ko":["전자 메일 계정 액세스 및 자격 증명 필요","전자 메일의 새도움을 확인하기 위해 리콜 기능에 의존"],"es":["Requiere acceso a la cuenta de correo electrónico y credenciales","Dependiente de la funcionalidad de recall para verificar la recencia del correo electrónico"],"fr":["Nécessite un accès au compte de courriel et des informations d''identification","Dépend de la fonctionnalité de rappel pour vérifier la récence du courriel"],"de":["Benötigt Zugriff auf das E-Mail-Konto und Anmeldeinformationen","Abhängig von der Recall-Funktion für die Überprüfung der E-Mail-Recency"],"pt":["Exige acesso e credenciais da conta de e-mail","Depende da funcionalidade de recall para verificar a recência do e-mail"],"ru":["Требует доступа и учетных данных электронной почты","Зависит от функции реколл для проверки свежести электронной почты"],"ar":["يتطلب الوصول إلى حساب البريد الإلكتروني والتصريح","يعتمد على وظيفة الاستدعاء لفحص حداثة البريد الإلكتروني"]},"version":4},"contentHash":"d1b51c7ba98c5641db640caeb2c99e1c9687b119c511ff6417bae8d34d081e66","qualityScore":41}');
